# Suppress noisy Binance WebSocket error spam
class WebSocketErrorFilter(logging.Filter):
    """Filter to suppress repetitive WebSocket 'Read loop has been closed' errors."""
    def __init__(self):
        super().__init__()
        self._last_log_time = 0.0
        self._suppressed_count = 0
        
    def filter(self, record: logging.LogRecord) -> bool:
        msg = record.getMessage()
        if "Read loop has been closed" in msg or "reset the websocket connection" in msg:
            import time
            now = time.time()
            self._suppressed_count += 1
            # Only log once every 60 seconds
            if now - self._last_log_time > 60.0:
                self._last_log_time = now
                record.msg = f"[WS-SPAM-FILTER] Suppressed {self._suppressed_count} WebSocket 'Read loop closed' errors"
                self._suppressed_count = 0
                return True
            return False
        return True

# Apply filter to binance.ws.threaded_stream logger
ws_filter = WebSocketErrorFilter()
logging.getLogger("binance.ws.threaded_stream").addFilter(ws_filter)
logging.getLogger("binance.ws").addFilter(ws_filter)

