# Telegram MarkdownV2 escaping helper
def _mdv2_escape(s: str) -> str:
    """
    Escape characters for Telegram MarkdownV2 format.
    Required characters: _*[]()~`>#+-=|{}.!
    """
    for ch in r"_*[]()~`>#+-=|{}.!":
        s = s.replace(ch, f"\\{ch}")
    return s


