def get_prediction_loop_interval_seconds(main_config=None, training_mode: str = 'live') -> tuple:
    """
    Get prediction loop interval with mode-dependent defaults.
    
    Precedence:
    1. If main_config.PREDICTION_LOOP_SECONDS or env PREDICTION_LOOP_SECONDS > 0 → use it
    2. Else if training-mode is 'live' → default to 5.0 seconds
    3. Else (offline/backtest/etc.) → default to 30.0 seconds
    
    Returns:
        tuple: (interval_seconds: float, source: str)
    """
    import os
    
    # Check env var first
    env_val = os.getenv('PREDICTION_LOOP_SECONDS')
    if env_val:
        try:
            interval = float(env_val)
            if interval > 0:
                return (interval, 'env')
        except ValueError:
            pass
    
    # Check config
    if main_config is not None:
        config_val = getattr(main_config, 'PREDICTION_LOOP_SECONDS', 0)
        if config_val and config_val > 0:
            return (float(config_val), 'config')
    
    # Mode-dependent default
    if str(training_mode).lower() == 'live':
        return (5.0, 'default_live')
    else:
        return (30.0, 'default_other')


def get_post_training_pause_seconds(main_config=None, training_mode: str = 'live') -> tuple:
    """
    Get post-training pause duration with mode-dependent defaults.
    
    Precedence:
    1. If env POST_TRAINING_PAUSE_SECONDS >= 0 → use it
    2. Else if training-mode is 'live' → default to 0.0 seconds (no pause)
    3. Else → default to 10.0 seconds (preserve offline stability)
    
    Returns:
        tuple: (pause_seconds: float, source: str)
    """
    import os

    # Live trading must not rely on fixed sleeps between loops. Any pacing should come from
    # data availability / execution latency, not an operator-set static timer.
    if str(training_mode).lower() == 'live':
        return (0.0, 'forced_live')
    
    # Check env var first
    env_val = os.getenv('POST_TRAINING_PAUSE_SECONDS')
    if env_val:
        try:
            pause = float(env_val)
            if pause >= 0:  # Allow explicit 0
                return (pause, 'env')
        except ValueError:
            pass
    
    # Check config (-1 means use default)
    if main_config is not None:
        config_val = getattr(main_config, 'POST_TRAINING_PAUSE_SECONDS', -1)
        if config_val is not None and config_val >= 0:
            return (float(config_val), 'config')
    
    # Mode-dependent default
    return (10.0, 'default_other')


def get_rollout_params(main_config=None) -> dict:
    """
    Get PPO rollout parameters with optional env/config overrides.
    
    Applies sanity guards (clamping) to prevent crashes:
    - n_envs: [1, 256] - defaults to SYMBOLS × TIMEFRAMES (65) for full coverage
    - n_steps: [128, 8192]
    - batch_size: [128, 65536]
    
    Returns:
        dict: {'n_envs': int, 'n_steps': int, 'batch_size': int, 
               'sources': {'n_envs': str, 'n_steps': str, 'batch_size': str}}
    """
    import os
    
    # Defaults: n_envs = SYMBOLS × TIMEFRAMES for full market coverage
    # This ensures every (symbol, timeframe) pair has a dedicated environment
    from config import SYMBOLS as CFG_SYMBOLS, TIMEFRAMES as CFG_TIMEFRAMES
    default_n_envs = len(CFG_SYMBOLS) * len(CFG_TIMEFRAMES)
    
    defaults = {'n_envs': default_n_envs, 'n_steps': 512, 'batch_size': 2048}
    clamps = {
        'n_envs': (1, 256),  # Allow up to 256 envs (capped to prevent OOM)
        'n_steps': (128, 8192),
        'batch_size': (128, 65536),
    }
    
    result = {}
    sources = {}
    
    for param, default in defaults.items():
        env_key = f'RL_{param.upper()}'
        env_val = os.getenv(env_key)
        
        if env_val:
            try:
                val = int(env_val)
                min_v, max_v = clamps[param]
                # Operator requirement (Jan 2026): do NOT allow silent truncation of (symbol,tf) pairs.
                # If an env override tries to reduce n_envs below full coverage, bump it up unless explicitly allowed.
                if param == "n_envs":
                    try:
                        allow_trunc = str(os.getenv("RL_ALLOW_ENV_TRUNCATION", "")).strip().lower() in ("1", "true", "yes", "on")
                    except Exception:
                        allow_trunc = False
                    if (not allow_trunc) and val < int(default_n_envs):
                        logging.getLogger('hybrid_trainer').warning(
                            f"⚠️ {env_key}={val} would truncate pairs; bumping to full coverage {default_n_envs}. "
                            f"(set RL_ALLOW_ENV_TRUNCATION=true to allow smaller)"
                        )
                        val = int(default_n_envs)
                if val < min_v:
                    logging.getLogger('hybrid_trainer').warning(
                        f"⚠️ {env_key}={val} below min ({min_v}), clamping"
                    )
                    val = min_v
                elif val > max_v:
                    logging.getLogger('hybrid_trainer').warning(
                        f"⚠️ {env_key}={val} above max ({max_v}), clamping"
                    )
                    val = max_v
                result[param] = val
                sources[param] = 'override'
                continue
            except ValueError:
                logging.getLogger('hybrid_trainer').warning(
                    f"⚠️ Invalid {env_key} value: {env_val}"
                )
        
        # Check config
        if main_config is not None:
            config_key = env_key
            config_val = getattr(main_config, config_key, None)
            if config_val is not None and config_val > 0:
                min_v, max_v = clamps[param]
                config_val = max(min_v, min(max_v, config_val))
                if param == "n_envs":
                    try:
                        allow_trunc = str(os.getenv("RL_ALLOW_ENV_TRUNCATION", "")).strip().lower() in ("1", "true", "yes", "on")
                    except Exception:
                        allow_trunc = False
                    if (not allow_trunc) and int(config_val) < int(default_n_envs):
                        logging.getLogger('hybrid_trainer').warning(
                            f"⚠️ {env_key}={int(config_val)} (config) would truncate pairs; bumping to full coverage {default_n_envs}. "
                            f"(set RL_ALLOW_ENV_TRUNCATION=true to allow smaller)"
                        )
                        config_val = int(default_n_envs)
                result[param] = config_val
                sources[param] = 'config'
                continue
        
        result[param] = default
        sources[param] = 'default'
    
    result['sources'] = sources
    return result

# TOP-LEVEL PICKLABLE FACTORY for SubprocVecEnv workers
def _make_subproc_env(env_id: int, symbol: str, timeframe: str):
    """Top-level environment factory for SubprocVecEnv workers - PICKLABLE

    OOM FIX (2026-04-14): Uses CPUTradingEnvironment (numpy-only, zero torch)
    instead of GPUTradingEnvironment + TradingEnvironmentWrapper.
    Saves 474 MB per worker (torch import overhead).
    125 workers: 62 GB → 5 GB.
    """
    # CRITICAL: Hard-disable CUDA in workers BEFORE any imports
    # This MUST be the very first thing in the worker process
    import os
    import sys
    import faulthandler

    # Enable faulthandler to dump stack traces on crashes
    faulthandler.enable()

    print(f"🔧 [WORKER-{env_id}] Starting worker initialization, PID={os.getpid()}", flush=True)

    os.environ["CUDA_VISIBLE_DEVICES"] = ""
    os.environ["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
    os.environ["OMP_NUM_THREADS"] = "1"
    os.environ["MKL_NUM_THREADS"] = "1"
    os.environ["NUMEXPR_MAX_THREADS"] = "1"
    os.environ["TOKENIZERS_PARALLELISM"] = "false"
    # Enable debug mode for SubprocVecEnv workers to bypass Redis
    os.environ['SUBPROC_DEBUG_MODE'] = '1'

    print(f"🔧 [WORKER-{env_id}] Environment variables set, debug mode enabled", flush=True)

    import time
    from stable_baselines3.common.monitor import Monitor

    print(f"🔧 [WORKER-{env_id}] Basic imports complete", flush=True)

    try:
        # Stagger worker startup slightly to avoid Redis/socket "thundering herd"
        # during SubprocVecEnv creation (can otherwise trigger broken pipe/reset).
        # Cap increased to 8s to handle 65+ workers (0.1s × 64 = 6.4s)
        stagger_time = min(0.1 * env_id, 8.0)
        if env_id > 0:  # Only stagger non-first workers
            print(f"🔧 [WORKER-{env_id}] Sleeping {stagger_time:.2f}s to stagger startup", flush=True)
            time.sleep(stagger_time)

        # OOM FIX: Import lightweight numpy-only env (NO torch, saves 474MB/worker)
        print(f"🔧 [WORKER-{env_id}] Importing CPUTradingEnvironment (numpy-only)...", flush=True)
        from rl.cpu_env import CPUTradingEnvironment
        try:
            from config import RL_TRANSACTION_COST as _WORKER_TX_COST
        except ImportError:
            _WORKER_TX_COST = 0.0004  # Safe fallback matching config default
        print(f"🔧 [WORKER-{env_id}] Imports complete (tx_cost={_WORKER_TX_COST}, NO torch)", flush=True)

        worker_pid = os.getpid()
        logger = get_logger("worker")
        logger.info(f"🔒 [WORKER-{worker_pid}] env_id={env_id} {symbol}:{timeframe} (numpy-only, no torch)")

        # Add worker-specific Redis timeout protection
        import signal
        def worker_timeout_handler(signum, frame):
            raise TimeoutError(f"SubprocVecEnv worker {env_id} timeout during initialization")

        # Set worker initialization timeout (increased for 65+ worker startup with staggering)
        old_handler = signal.signal(signal.SIGALRM, worker_timeout_handler)
        signal.alarm(30)  # 30 second timeout for worker initialization

        try:
            # CPUTradingEnvironment is a gymnasium.Env — no wrapper needed
            cpu_env = CPUTradingEnvironment(
                symbol=symbol,
                timeframe=timeframe,
                initial_balance=10000.0,
                transaction_cost=_WORKER_TX_COST,
                max_position=1.0,
                lookback_window=10,
            )
            result = Monitor(cpu_env, filename=None, allow_early_resets=True)
        finally:
            signal.alarm(0)  # Clear alarm
            signal.signal(signal.SIGALRM, old_handler)  # Restore handler

        return result

    except Exception as e:
        print(f"Failed to create env {env_id} ({symbol}:{timeframe}): {e}")
        import traceback
        traceback.print_exc()
        return None

# Global cleanup guard to ensure idempotent shutdown
_cleanup_done = False


def cleanup_resources():
    """Best-effort cleanup for trainers and workers (idempotent)."""
    global _cleanup_done
    if _cleanup_done:
        return
    _cleanup_done = True
    try:
        # Flush logging to avoid truncated lines
        logging.shutdown()
    except Exception:
        pass
    try:
        import gc
        gc.collect()
    except Exception:
        pass


# Register cleanup function
atexit.register(cleanup_resources)

# Handle signals properly with graceful shutdown
_shutting_down = False

def is_shutting_down():
    """Check if trainer is shutting down"""
    return _shutting_down

def signal_handler(signum, frame):
    global _shutting_down
    if _shutting_down:
        print(f"\n[SHUTDOWN] Already shutting down, forcing exit...")
        import os
        os._exit(1)  # Force exit if signal received twice
    
    _shutting_down = True
    print(f"\n[SHUTDOWN] Received signal {signum}, initiating graceful shutdown...")
    print("[SHUTDOWN] Please wait for cleanup to complete...")
    # DON'T call sys.exit() here - let main loop handle cleanup gracefully
    # sys.exit() causes SystemExit which breaks pipes during thread execution

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

try:
    # Use 'spawn' only for CUDA + SB3 + IPC compatibility (required for RTX5080)
    # This must be set exactly once at process entry to avoid "received 0 items of ancdata" errors
    multiprocessing.set_start_method('spawn', force=True)
    print("[MULTIPROCESSING] Set spawn method for CUDA compatibility")
except RuntimeError:
    # Method already set - verify it's spawn
    current_method = multiprocessing.get_start_method()
    if current_method != 'spawn':
        print(f"[WARNING] Multiprocessing method is '{current_method}', CUDA processes may fail")
    else:
        print(f"[MULTIPROCESSING] Method already set to '{current_method}' (good)")
except Exception as e:
    print(f"[ERROR] Failed to set multiprocessing method: {e}")
    raise

