class RTX5080FeatureExtractor(BaseFeaturesExtractor):
    """
    CNN Feature extractor optimized for RTX 5080 (70-90% GPU utilization target)
    Fixed to properly handle canonical 1430 feature dimensions
    """
    
    def __init__(self, observation_space: spaces.Box, features_dim: int = 2048):
        super().__init__(observation_space, features_dim)
        
        # Get actual input size from observation space
        input_size = observation_space.shape[0]
        print(f"[RTX5080] Initializing with input_size={input_size} from observation_space")
        
        # Create optimal 2D representation for current input size
        # Dynamically calculate best factorization for any input size
        # Support for 1911 features and beyond
        if input_size <= 2000:
            # For 1911 features: find best rectangular representation
            # 1911 ≈ 44 × 44 = 1936, so pad to 44×44
            sqrt_size = int(math.sqrt(input_size))
            self.height = sqrt_size + 1 if sqrt_size * sqrt_size < input_size else sqrt_size
            self.width = self.height
            self.target_size = self.height * self.width
        else:
            # For larger inputs, use dynamic sizing
            import math
            sqrt_size = int(math.sqrt(input_size))
            self.height = sqrt_size + 1
            self.width = sqrt_size + 1
            self.target_size = self.height * self.width
        
        self.channels = 1
        self.input_size = input_size
        
        # Calculate padding needed to reach target size
        self.padding_size = max(0, self.target_size - input_size)
        print(f"[RTX5080] Will pad from {input_size} to {self.target_size} (padding: {self.padding_size})")
        print(f"[RTX5080] CNN input shape will be: {self.channels} x {self.height} x {self.width}")
        
        # GPU-optimized CNN layers (tuned for 70-90% utilization, 80% VRAM)
        # Dynamic architecture based on input dimensions
        self.cnn = nn.Sequential(
            # First Conv Block - Controlled GPU workload
            nn.Conv2d(1, 32, kernel_size=3, stride=1, padding=1),  # HxW -> HxW
            nn.BatchNorm2d(32),
            nn.ReLU(inplace=True),
            nn.Conv2d(32, 64, kernel_size=3, stride=2, padding=1),  # HxW -> H/2 x W/2
            nn.BatchNorm2d(64),
            nn.ReLU(inplace=True),
            
            # Second Conv Block - Balanced computation  
            nn.Conv2d(64, 128, kernel_size=3, stride=1, padding=1),  # H/2 x W/2 -> H/2 x W/2
            nn.BatchNorm2d(128),
            nn.ReLU(inplace=True),
            nn.Conv2d(128, 256, kernel_size=3, stride=2, padding=1),  # H/2 x W/2 -> H/4 x W/4
            nn.BatchNorm2d(256),
            nn.ReLU(inplace=True),
            
            # Third Conv Block - Managed GPU utilization
            nn.Conv2d(256, 512, kernel_size=3, stride=1, padding=1),  # H/4 x W/4 -> H/4 x W/4
            nn.BatchNorm2d(512),
            nn.ReLU(inplace=True),
            nn.Conv2d(512, 1024, kernel_size=3, stride=2, padding=1),  # H/4 x W/4 -> H/8 x W/8
            nn.BatchNorm2d(1024),
            nn.ReLU(inplace=True),
            
            # Global Average Pooling
            nn.AdaptiveAvgPool2d((1, 1)),
            nn.Flatten(),
        )
        
        # Feature processor with stability enhancements
        self.feature_processor = nn.Sequential(
            nn.Linear(1024, features_dim),
            nn.ReLU(inplace=True),
            nn.Dropout(0.3),
            nn.Linear(features_dim, features_dim // 2),
            nn.ReLU(inplace=True),
            nn.Linear(features_dim // 2, features_dim),
            nn.ReLU(inplace=True),
        )
        
        self._initialize_weights()
    
    def _initialize_weights(self):
        """Initialize weights for optimal GPU performance"""
        for m in self.modules():
            if isinstance(m, nn.Conv2d):
                nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
                if m.bias is not None:
                    nn.init.constant_(m.bias, 0)
            elif isinstance(m, nn.BatchNorm2d):
                nn.init.constant_(m.weight, 1)
                nn.init.constant_(m.bias, 0)
            elif isinstance(m, nn.Linear):
                nn.init.normal_(m.weight, 0, 0.01)
                nn.init.constant_(m.bias, 0)
    
    def forward(self, observations: torch.Tensor) -> torch.Tensor:
        batch_size = observations.shape[0]
        current_size = observations.shape[1]
        
        # Validate input size matches what we expect
        if current_size != self.input_size:
            print(f"[RTX5080] WARNING: Expected {self.input_size} features, got {current_size}")
        
        # Pad input to target size for CNN processing
        if self.padding_size > 0:
            padding = torch.zeros(batch_size, self.padding_size, device=observations.device, dtype=observations.dtype)
            observations = torch.cat([observations, padding], dim=1)
        elif current_size > self.target_size:
            # Truncate if input is larger than expected
            observations = observations[:, :self.target_size]
            print(f"[RTX5080] Truncated input from {current_size} to {self.target_size}")
        
        # Reshape to 2D for CNN processing
        observations = observations.view(batch_size, self.channels, self.height, self.width)
        
        # Apply CNN layers
        features = self.cnn(observations)
        
        # Apply feature processor
        final_features = self.feature_processor(features)
        
        return final_features


class RTX5080Policy(ActorCriticPolicy):
    """RTX 5080 optimized CNN policy (70-90% GPU utilization)"""
    
    def __init__(self, *args, **kwargs):
        super().__init__(
            *args,
            **kwargs,
            features_extractor_class=RTX5080FeatureExtractor,
            features_extractor_kwargs={"features_dim": 2048},
        )


class HedgeRecoveryPolicy(ActorCriticPolicy):
    """
    7-Action Hedge Recovery Policy with Categorical(7) action space.
    
    Replaces MultiDiscrete with single Categorical head.
    Adds separate continuous heads for size and leverage.
    """
    
    def __init__(self, *args, **kwargs):
        super().__init__(
            *args,
            **kwargs,
            features_extractor_class=RTX5080FeatureExtractor,
            features_extractor_kwargs={"features_dim": 2048},
        )
        
        # Override action network for 7-action categorical
        if hasattr(self, 'action_net'):
            # Replace default action head with 7-action categorical
            latent_dim_pi = self.mlp_extractor.latent_dim_pi
            self.action_net = nn.Linear(latent_dim_pi, 7)  # 7 categorical actions
            
            # Add continuous heads for size and leverage
            self.size_head = nn.Linear(latent_dim_pi, 1)
            self.leverage_head = nn.Linear(latent_dim_pi, 1)
            
            print(f"✅ HedgeRecoveryPolicy: Replaced action head with Categorical(7) + continuous heads")
    
    def forward(self, obs, deterministic: bool = False):
        """
        Forward pass with 7-action categorical + continuous outputs.
        """
        features = self.extract_features(obs)
        latent_pi, latent_vf = self.mlp_extractor(features)

        action_logits = self.action_net(latent_pi)
        size_output = self.size_head(latent_pi)
        leverage_output = self.leverage_head(latent_pi)
        values = self.value_net(latent_vf)

        distribution = self.action_dist.proba_distribution(action_logits=action_logits)
        actions = distribution.get_actions(deterministic=deterministic)
        log_prob = distribution.log_prob(actions)

        # Expose auxiliary heads for env-side decoding (option 1)
        try:
            action_probs = torch.softmax(action_logits, dim=-1).detach().cpu().numpy()
            size_cpu = size_output.detach().cpu().numpy()
            lev_cpu = leverage_output.detach().cpu().numpy()
            LATEST_POLICY_PARAMS['action_probs'] = action_probs
            LATEST_POLICY_PARAMS['size'] = size_cpu
            LATEST_POLICY_PARAMS['leverage'] = lev_cpu
        except Exception:
            pass

        return actions, values, log_prob


def create_rtx5080_policy_kwargs():
    """Create policy kwargs for RTX 5080 CNN optimization"""
    return {
        "features_extractor_class": RTX5080FeatureExtractor,
        "features_extractor_kwargs": {"features_dim": 2048},
        "net_arch": [dict(pi=[1024, 512, 256], vf=[1024, 512, 256])],
        "activation_fn": nn.ReLU,
    }


def create_tailored_policy_kwargs(timeframe: str, symbol: str = None) -> Dict:
    """H) Tailored Policy Architectures - Per-timeframe and per-asset network selection
    
    Architecture selection:
    - 1m: LSTM (temporal patterns, noisy data)
    - 5m/15m: LSTM+Attention (balanced)
    - 1h/4h: Deeper FFN (trend following)
    - Multi-TF: Attention mechanism
    
    Args:
        timeframe: Timeframe string (1m, 5m, 15m, 1h, 4h)
        symbol: Optional symbol for asset-specific tuning
    
    Returns:
        Policy kwargs dict for SB3
    """
    if timeframe == "1m":
        # 1m: LSTM for temporal patterns (noisy, fast-moving)
        return {
            "features_extractor_class": RecurrentFeatureExtractor,
            "features_extractor_kwargs": {
                "features_dim": 2048,
                "lstm_hidden_size": 256,  # Smaller for 1m (faster)
                "lstm_num_layers": 1,
                "attention_heads": 4,
                "sequence_length": 20,  # Longer sequence for 1m
                "dropout": 0.2
            },
            "net_arch": dict(pi=[512, 256], vf=[512, 256]),  # Lighter network
            "activation_fn": nn.ReLU,
        }
    elif timeframe in ["5m", "15m"]:
        # 5m/15m: LSTM+Attention (balanced)
        return {
            "features_extractor_class": RecurrentFeatureExtractor,
            "features_extractor_kwargs": {
                "features_dim": 2048,
                "lstm_hidden_size": 512,
                "lstm_num_layers": 2,
                "attention_heads": 8,
                "sequence_length": 10,
                "dropout": 0.1
            },
            "net_arch": dict(pi=[1024, 512, 256], vf=[1024, 512, 256]),
            "activation_fn": nn.ReLU,
        }
    elif timeframe in ["1h", "4h"]:
        # 1h/4h: Deeper FFN (trend following, less temporal noise)
        return {
            "features_extractor_class": RTX5080FeatureExtractor,
            "features_extractor_kwargs": {"features_dim": 2048},
            "net_arch": dict(pi=[2048, 1024, 512, 256], vf=[2048, 1024, 512, 256]),  # Deeper
            "activation_fn": nn.ReLU,
        }
    else:
        # Default: Balanced architecture
        return create_rtx5080_policy_kwargs()

