def safe_close_vecenv(vec_env, timeout: float = 5.0) -> bool:
    """
    Safely close a vectorized environment with timeout protection.
    If workers are stuck, terminate/kill them forcefully.
    
    Args:
        vec_env: Vector environment to close
        timeout: Max time to wait for graceful close
        
    Returns:
        True if closed gracefully, False if forced termination was needed
    """
    done = {"ok": False}
    
    def _close():
        try:
            vec_env.close()
            done["ok"] = True
        except Exception as e:
            get_logger("safe_close").warning(f"⚠️ Exception during vec_env.close(): {e}")
    
    # Try graceful close with timeout
    import threading
    th = threading.Thread(target=_close, daemon=True)
    th.start()
    th.join(timeout)
    
    logger = get_logger("safe_close")
    
    if done["ok"]:
        logger.info("✅ VecEnv closed gracefully")
        return True
    
    # Hard kill stuck workers
    logger.warning(f"⚠️ VecEnv close timed out after {timeout}s, forcing worker termination")
    
    # Find worker processes in SubprocVecEnv
    procs = getattr(vec_env, "processes", None) or getattr(getattr(vec_env, "venv", None), "processes", None)
    
    if procs:
        logger.info(f"🔪 Force terminating {len(procs)} stuck workers")
        
        # First attempt: terminate
        for i, p in enumerate(procs):
            try:
                if hasattr(p, 'terminate'):
                    p.terminate()
            except Exception:
                pass
        
        # Give processes a moment to exit
        import time
        time.sleep(0.2)
        
        # Second attempt: kill
        for i, p in enumerate(procs):
            try:
                if hasattr(p, 'is_alive') and p.is_alive():
                    if hasattr(p, 'kill'):
                        p.kill()
            except Exception:
                pass
        
        # Wait for processes to fully terminate
        time.sleep(0.5)
        
        # Verify termination and log any zombies
        alive_count = 0
        zombie_pids = []
        for i, p in enumerate(procs):
            try:
                if hasattr(p, 'is_alive') and p.is_alive():
                    alive_count += 1
                    pid = p.pid if hasattr(p, 'pid') else None
                    if pid:
                        zombie_pids.append(pid)
                    logger.error(f"❌ Worker {i} still alive after kill (PID: {pid or 'unknown'})")
            except Exception:
                pass
        
        if alive_count > 0:
            logger.error(f"❌ {alive_count} zombie workers detected!")
            
            # Nuclear option: kill -9 the zombie PIDs
            if zombie_pids:
                import subprocess
                logger.warning(f"☢️ Sending SIGKILL to {len(zombie_pids)} zombie workers")
                for pid in zombie_pids:
                    try:
                        subprocess.run(['kill', '-9', str(pid)], check=False, timeout=1)
                    except Exception:
                        pass
                time.sleep(0.5)
                logger.info("✅ SIGKILL sent to all zombies")
        else:
            logger.info("✅ All workers confirmed terminated")
        
        # CRITICAL: Also kill any orphaned spawn workers from previous failed cleanups
        try:
            import subprocess
            result = subprocess.run(
                ['pkill', '-9', '-f', 'multiprocessing.spawn.*hybrid_trainer'],
                capture_output=True,
                timeout=2
            )
            if result.returncode == 0:
                logger.info("🧹 Cleaned up orphaned spawn workers from previous runs")
        except Exception as e:
            logger.debug(f"Orphan cleanup check failed: {e}")
        
        # Force cleanup of worker memory
        logger.info("🧹 Running aggressive memory cleanup after worker termination...")
        cleanup_resources()
        
        logger.warning("⚠️ All workers force-terminated due to hang")
    
    return False
