def get_min_conf_for_tf(tf: str, action_category: str = "OPEN_RISK") -> float:
    """
    Get minimum confidence threshold for a specific timeframe.
    
    Returns lower thresholds for higher TFs (slower signals = more reliable at lower conf).
    Returns the global MIN_TRADING_CONFIDENCE as fallback.
    
    Args:
        tf: Timeframe string (e.g., "5m", "15m", "1h", "4h")
        action_category: Action category for context (default: OPEN_RISK)
    
    Returns:
        float: Minimum confidence threshold for this TF
    """
    try:
        from config import (
            TF_MIN_CONF_5M, TF_MIN_CONF_15M, TF_MIN_CONF_1H, TF_MIN_CONF_4H,
            MIN_TRADING_CONFIDENCE
        )
        tf_map = {
            "5m": TF_MIN_CONF_5M,
            "15m": TF_MIN_CONF_15M,
            "1h": TF_MIN_CONF_1H,
            "4h": TF_MIN_CONF_4H,
        }
        return float(tf_map.get(tf, MIN_TRADING_CONFIDENCE))
    except Exception:
        return float(MIN_TRADING_CONFIDENCE)


