        # GPU setup and validation
        self.setup_gpu()
        # --------------------------------------------------------------------
        # INFERENCE SNAPSHOT (no-pauses predictions while training)
        # --------------------------------------------------------------------
        # Running PPO backprop and PPO inference on the *same* policy concurrently is unsafe
        # (weights mutate mid-forward). To keep signals flowing during live training without
        # blocking, we maintain a lightweight inference-only snapshot policy that is refreshed
        # after each training chunk.
        self._infer_policy_active = None
        self._infer_policy_standby = None
        self._infer_policy_version = 0
        self._infer_policy_last_sync_ts = 0.0
        self._infer_policy_build_failed = False
        self._infer_policy_sync_lock = threading.Lock()

