        self.episode_rewards = []
        self.gpu_utilization_history = []
        
        # Confidence tracking for adaptive thresholds (per symbol:timeframe)
        from collections import defaultdict, deque
        self.confidence_history = defaultdict(lambda: deque(maxlen=self.config.adaptive_threshold_window))
        
        # Phase B2: Separate buffers to prevent 8-dim vs 1053-dim mismatch
        self._temporal_buffers = defaultdict(lambda: defaultdict(lambda: deque(maxlen=128)))  # Observations (1053-dim)
        self._regime_buffers = defaultdict(lambda: defaultdict(lambda: deque(maxlen=5)))  # Regime features (8-dim)
        
