    def _init_confidence_pipeline(self):
        """Initialize data-driven confidence pipeline: logging, feedback, calibration, dynamic MASA weight."""
        # Phase 2: ConfidenceLogger — logs predictions for calibration
        self._confidence_logger = None
        try:
            from rl.confidence_logger import ConfidenceLogger
            self._confidence_logger = ConfidenceLogger(self.redis, max_records=10000)
            logger.info("[CONF-PIPELINE] ConfidenceLogger initialized — predictions will be logged to rl:eval:pending")
        except Exception as e:
            logger.warning("[CONF-PIPELINE] ConfidenceLogger init failed: %s", e)

        # Phase 3: ExecutionFeedbackConsumer — tracks trade outcomes, closes feedback loop
        self._outcome_tracker = None
        self._signal_validator = None
        self._feedback_consumer = None
        try:
            from rl.trade_feedback import initialize_feedback_system
            self._outcome_tracker, self._signal_validator, self._feedback_consumer = \
                initialize_feedback_system(self.redis)
            logger.info("[CONF-PIPELINE] Feedback system initialized — trade outcomes being tracked")
        except Exception as e:
            logger.warning("[CONF-PIPELINE] Feedback system init failed: %s", e)

        # Phase 4: CalibratedConfidenceManager — temperature-scaled confidence
        self._calibration_manager = None
        try:
            from rl.calibrated_confidence import CalibratedConfidenceManager
            self._calibration_manager = CalibratedConfidenceManager(self.redis)
            logger.info("[CONF-PIPELINE] CalibratedConfidenceManager initialized")
        except Exception as e:
            logger.warning("[CONF-PIPELINE] CalibratedConfidenceManager init failed: %s", e)

        # Phase 5: Dynamic MASA weight — starts at 0.3 (moderate trust),
        # adjusted each cycle based on tracked MASA accuracy from SignalValidator
        self._dynamic_masa_weight = 0.6
        self._dynamic_masa_disagree = 0.2
        self._masa_weight_update_counter = 0
        logger.info(
            "[CONF-PIPELINE] Dynamic MASA weight initialized: blend_w=%.2f disagree_max=%.2f",
            self._dynamic_masa_weight, self._dynamic_masa_disagree,
        )

        # Phase 6: ThresholdRamper — writes adaptive threshold to Redis
        self._threshold_ramper = None
        try:
            from rl.threshold_ramper import ThresholdRamper
            self._threshold_ramper = ThresholdRamper(self.redis)
            current = self._threshold_ramper.get_current_threshold()
            logger.info("[CONF-PIPELINE] ThresholdRamper initialized — current threshold=%.2f", current)
        except Exception as e:
            logger.warning("[CONF-PIPELINE] ThresholdRamper init failed: %s", e)

    def _update_dynamic_masa_weight(self):
        """Update MASA blend weight based on tracked accuracy from SignalValidator.

        Called once per prediction cycle. Reads per-confidence-bin accuracy
        from SignalValidator and computes a reliability score for MASA:
        - High MASA accuracy (agree predictions match outcomes) => higher weight (up to 0.5)
        - Low MASA accuracy => lower weight (down to 0.1)
        - Insufficient data => hold at cold-start default (0.3)
        """
        if self._signal_validator is None:
            return
        try:
            report = self._signal_validator.get_calibration_report()
            if not report:
                return

            accuracies = []
            total_samples = 0
            for sym_data in report.values():
                cal = sym_data.get('calibration', {})
                samples = sym_data.get('samples', 0)
                total_samples += samples
                for _bin, acc in cal.items():
                    accuracies.append(acc)

            if total_samples < 20 or not accuracies:
                return

            avg_accuracy = sum(accuracies) / len(accuracies)
            new_weight = 0.1 + 0.4 * max(0.0, min(1.0, avg_accuracy))
            if avg_accuracy < 0.55:
                new_disagree = 0.0
            else:
                new_disagree = 0.15 * min(1.0, (avg_accuracy - 0.55) / 0.25)

            old_w = self._dynamic_masa_weight
            # Exponential moving average to avoid jumps
            self._dynamic_masa_weight = 0.8 * self._dynamic_masa_weight + 0.2 * new_weight
            self._dynamic_masa_disagree = 0.8 * self._dynamic_masa_disagree + 0.2 * new_disagree

            self._masa_weight_update_counter += 1
            if self._masa_weight_update_counter % 10 == 1:
                logger.info(
                    "[DYNAMIC_MASA_WEIGHT] accuracy=%.3f samples=%d | "
                    "blend_w=%.3f->%.3f disagree_max=%.3f",
                    avg_accuracy, total_samples, old_w,
                    self._dynamic_masa_weight, self._dynamic_masa_disagree,
                )
        except Exception as e:
            logger.debug("[DYNAMIC_MASA_WEIGHT] Update error: %s", e)

    def _run_threshold_ramper(self):
        """Periodically check if confidence threshold should be adjusted.

        Reads calibration metrics (ECE, accuracy) and trading performance,
        then writes updated threshold to Redis ``rl:config:threshold``.
        Also pushes fresh calibration metrics from ConfidenceLogger.
        """
        if self._threshold_ramper is None:
            return
        try:
            # Push latest calibration metrics
            if self._confidence_logger is not None:
                self._confidence_logger.push_metrics()

            result = self._threshold_ramper.auto_ramp(dry_run=False)
            status = result.get('status', 'unknown')
            if status == 'ramped':
                logger.info(
                    "[THRESHOLD_RAMP] Threshold changed: %.2f -> %.2f (reason: %s)",
                    result.get('old_threshold', 0), result.get('new_threshold', 0),
                    result.get('reason', ''),
                )
            elif status != 'conditions_not_met':
                logger.info("[THRESHOLD_RAMP] Status: %s", status)
        except Exception as e:
            logger.debug("[THRESHOLD_RAMP] Error: %s", e)

