    # ========================================================================
    # HEDGE_BUILD STATE MANAGEMENT (HybridTrainer implementation)
    # ========================================================================

    def _get_symbol_atr_pct(self, symbol: str) -> float:
        """Delegate to GPUForcedPPO's ATR lookup (which reads unified_features/NATR from Redis)."""
        ppo = getattr(self, "ppo_model", None)
        if ppo is not None and hasattr(ppo, "_get_symbol_atr_pct"):
            return ppo._get_symbol_atr_pct(symbol)
        # ppo_model not ready yet — try direct Redis as last resort
        try:
            rc = getattr(self, "redis", None) or getattr(self, "_signal_redis", None)
            if rc:
                uf = rc.hgetall(f"unified_features:{str(symbol).upper().strip()}:5m") or {}
                if uf:
                    if isinstance(list(uf.keys())[0], bytes):
                        uf = {k.decode(): v.decode() for k, v in uf.items()}
                    for k in ("ind_ta_NATR_21_5m", "ind_ta_NATR_14_5m"):
                        v = float(uf.get(k, 0) or 0)
                        if v > 0:
                            return max(0.0005, min(0.25, v / 100.0))
        except Exception:
            pass
        return 0.015
    
    def _process_trail_exit_feedback(self):
        """Process trailing exit feedback from traders to enter HEDGE_BUILD state"""
        try:
            try:
                from config import HEDGE_BUILD_ENABLED, ENABLE_PROFIT_FUNDED_TRIM
            except Exception:
                HEDGE_BUILD_ENABLED = False
                ENABLE_PROFIT_FUNDED_TRIM = False

            # If neither hedge-build nor profit-funded trim is enabled, skip.
            if not bool(HEDGE_BUILD_ENABLED) and not bool(ENABLE_PROFIT_FUNDED_TRIM):
                return
            
            # Be resilient across init variants: some paths use self.redis, others self._signal_redis
            redis_client = getattr(self, 'redis', None) or getattr(self, '_signal_redis', None)
            if not redis_client:
                # Avoid log spam: warn at most every 60s
                now_s = int(time.time())
                last_warn = int(getattr(self, '_hedge_build_no_redis_warn_ts', 0) or 0)
                if now_s - last_warn >= 60:
                    self._hedge_build_no_redis_warn_ts = now_s
                    logger.warning("[HEDGE_BUILD] No Redis client available for feedback poll")
                return
            
            stream_key = 'wma:trader:execution_feedback'
            last_id = getattr(self, '_last_trail_feedback_id', '0-0')
            
            # CRITICAL FIX: Use block=None for immediate non-blocking read
            # block=100 was causing socket timeouts in production
            try:
                entries = redis_client.xread({stream_key: last_id}, count=50, block=None)
            except (ConnectionError, TimeoutError, OSError) as conn_err:
                # Socket errors are transient - don't log every time
                return
            
            if not entries:
                return
            
            entry_count = sum(len(msgs) for _, msgs in entries)
            if entry_count > 0:
                logger.info(f"[HEDGE_BUILD] Found {entry_count} new feedback entries")
            
            import json
            for stream, messages in entries:
                for msg_id, data in messages:
                    # Handle both bytes and string msg_id
                    if isinstance(msg_id, bytes):
                        self._last_trail_feedback_id = msg_id.decode('utf-8')
                    else:
                        self._last_trail_feedback_id = str(msg_id)
                    try:
                        # Handle both bytes and string keys in data dict
                        raw_data = data.get(b'data') or data.get('data') or '{}'
                        if isinstance(raw_data, bytes):
                            raw_data = raw_data.decode('utf-8')
                        payload = json.loads(raw_data)
                        event_type = payload.get('event_type')
                        if event_type in ('TRAILING_EXIT', 'PROFIT_EXIT'):
                            symbol = payload.get('symbol')
                            side = payload.get('side')
                            account = payload.get('account_id', payload.get('account', 'unknown'))
                            # IMPORTANT: execution_feedback historically used inconsistent units for `pnl`
                            # (sometimes USD, sometimes percent). Profit-funded trim requires USD credit.
                            # Prefer explicit USD fields and treat bare `pnl` as unreliable unless it is
                            # explicitly marked as USD.
                            pnl = (
                                payload.get('realized_pnl_usd')
                                or payload.get('pnl_usd')
                                or payload.get('realized_pnl')
                                or 0
                            )
                            if symbol and side:
                                logger.info(f"HEDGE_BUILD_CONSUME | {symbol} | event={event_type} | side={side} | account={account} | pnl={pnl}")
                                if bool(HEDGE_BUILD_ENABLED):
                                    self._enter_hedge_build_state(symbol, side, event_type.lower(), account_id=str(account).strip().lower() if account else None)

                            # Profit-funded trim: when a profit exit occurs, use the realized profit as
                            # a bounded "credit" to realize a similar amount of loss by partially closing
                            # a losing leg (reduce-only). Cross-symbol is optional.
                            if bool(ENABLE_PROFIT_FUNDED_TRIM) and str(event_type) == 'PROFIT_EXIT':
                                try:
                                    from config import (
                                        PROFIT_TRIM_MIN_EVENT_CONF,
                                        PROFIT_TRIM_ALLOW_CROSS_SYMBOL,
                                        PROFIT_TRIM_ALLOW_TRIM_HEDGED_PAIRS,
                                        PROFIT_TRIM_MIN_CREDIT_USD,
                                        PROFIT_TRIM_MIN_LOSS_USD,
                                        PROFIT_TRIM_MIN_ROE_PCT,
                                        PROFIT_TRIM_MAX_TRIMS_PER_BUCKET,
                                        PROFIT_TRIM_MAX_CREDIT_USE_USD,
                                        PROFIT_TRIM_MAX_CLOSE_FRACTION,
                                    )
                                except Exception:
                                    PROFIT_TRIM_MIN_EVENT_CONF = 0.85
                                    PROFIT_TRIM_ALLOW_CROSS_SYMBOL = False
                                    PROFIT_TRIM_ALLOW_TRIM_HEDGED_PAIRS = False
                                    PROFIT_TRIM_MIN_CREDIT_USD = 10.0
                                    PROFIT_TRIM_MIN_LOSS_USD = 25.0
                                    PROFIT_TRIM_MIN_ROE_PCT = -100.0
                                    PROFIT_TRIM_MAX_TRIMS_PER_BUCKET = 1
                                    PROFIT_TRIM_MAX_CREDIT_USE_USD = 100.0
                                    PROFIT_TRIM_MAX_CLOSE_FRACTION = 0.50

                                acct = str(account or '').strip().lower()
                                if acct in ('primary', 'asjad'):
                                    try:
                                        conf = float(payload.get('confidence') or payload.get('signal_confidence') or 0.0)
                                    except Exception:
                                        conf = 0.0
                                    # Profit credit must be USD.
                                    # If only percent is available, skip crediting rather than mis-crediting.
                                    profit_usd = 0.0
                                    try:
                                        profit_usd = float(pnl or 0.0)
                                    except Exception:
                                        profit_usd = 0.0
                                    try:
                                        # Detect percent-only payloads (common legacy case: pnl==pnl_pct).
                                        has_pct = (
                                            payload.get("pnl_pct") is not None
                                            or payload.get("realized_pnl_pct") is not None
                                            or payload.get("roe_pct") is not None
                                        )
                                        # If the payload lacks explicit USD fields, treat it as percent-only.
                                        has_usd = (
                                            payload.get("realized_pnl_usd") is not None
                                            or payload.get("pnl_usd") is not None
                                            or payload.get("realized_pnl") is not None
                                        )
                                        if (not has_usd) and has_pct:
                                            profit_usd = 0.0
                                    except Exception:
                                        pass

                                    if profit_usd > 0.0 and conf >= float(PROFIT_TRIM_MIN_EVENT_CONF or 0.0):
                                        try:
                                            loop_s = float(getattr(self.config, 'PREDICTION_LOOP_SECONDS', 30) or 30)
                                        except Exception:
                                            loop_s = 30.0
                                        bucket = int(time.time() // max(1.0, loop_s))
                                        if getattr(self, '_profit_trim_bucket', None) != bucket:
                                            self._profit_trim_bucket = bucket
                                            self._profit_trim_counts = {}
                                            # carry credit across buckets (accumulates until usable)
                                            if not hasattr(self, '_profit_trim_credit_usd'):
                                                self._profit_trim_credit_usd = {}

                                        counts = getattr(self, '_profit_trim_counts', {}) or {}
                                        used = int(counts.get(acct, 0) or 0)
                                        if used >= int(PROFIT_TRIM_MAX_TRIMS_PER_BUCKET or 1):
                                            continue

                                        credit = (getattr(self, '_profit_trim_credit_usd', {}) or {}).get(acct, 0.0) or 0.0
                                        credit = float(credit) + float(profit_usd)
                                        try:
                                            self._profit_trim_credit_usd[acct] = float(credit)
                                        except Exception:
                                            pass

                                        # Credit visibility: log accumulation when profit events occur
                                        logger.info(f"[PROFIT_TRIM_CREDIT] acct={acct} | added=${profit_usd:.2f} | balance=${credit:.2f}")

                                        if float(credit) < float(PROFIT_TRIM_MIN_CREDIT_USD or 0.0):
                                            logger.debug(f"[PROFIT_TRIM_CREDIT] acct={acct} | insufficient (${credit:.2f} < ${PROFIT_TRIM_MIN_CREDIT_USD:.2f})")
                                            continue

                                        # Pull current positions for the account.
                                        positions = []
                                        try:
                                            from rl.portfolio_policy_manager import get_portfolio_policy_manager
                                            ppm = get_portfolio_policy_manager()
                                            snap = ppm.get_portfolio_snapshot(account_id=acct) if ppm else None
                                            pos_map = getattr(snap, 'positions', None) if snap else None
                                            if isinstance(pos_map, dict):
                                                for k, v in pos_map.items():
                                                    if isinstance(v, dict):
                                                        p = dict(v)
                                                        p.setdefault('symbol', str(k).split(':', 1)[0].upper())
                                                        if ':' in str(k) and 'side' not in p:
                                                            try:
                                                                p['side'] = str(k).split(':', 1)[1].upper()
                                                            except Exception:
                                                                pass
                                                        positions.append(p)
                                        except Exception:
                                            positions = []

                                        if not positions:
                                            # Fallback: Redis hash (best-effort)
                                            try:
                                                raw = redis_client.hgetall(f"portfolio:positions:{acct}") or {}
                                                for k, v in (raw or {}).items():
                                                    try:
                                                        ks = k.decode('utf-8', errors='ignore') if isinstance(k, (bytes, bytearray)) else str(k)
                                                        vs = v.decode('utf-8', errors='ignore') if isinstance(v, (bytes, bytearray)) else v
                                                        p = json.loads(vs) if isinstance(vs, str) and vs.strip().startswith('{') else {}
                                                        if not isinstance(p, dict):
                                                            p = {}
                                                        if 'symbol' not in p:
                                                            p['symbol'] = ks.split(':', 1)[0].upper() if ':' in ks else ks.upper()
                                                        if 'side' not in p and ':' in ks:
                                                            try:
                                                                p['side'] = ks.split(':', 1)[1].upper()
                                                            except Exception:
                                                                pass
                                                        positions.append(p)
                                                    except Exception:
                                                        continue
                                            except Exception:
                                                positions = []

                                        if not positions:
                                            continue

                                        # Build symbol->sides map to detect hedged pairs.
                                        sides_by_symbol = {}
                                        for p in positions:
                                            try:
                                                s = str(p.get('symbol') or '').upper().strip()
                                                sd = str(p.get('side') or p.get('positionSide') or '').upper().strip()
                                                if s and sd in ('LONG', 'SHORT'):
                                                    sides_by_symbol.setdefault(s, set()).add(sd)
                                            except Exception:
                                                continue

                                        profit_sym = str(symbol or '').upper().strip()
                                        profit_side = str(side or '').upper().strip()

                                        def _p_unrealized_usd(pp: dict) -> float:
                                            for key in (
                                                'unrealized_pnl_usd', 'unrealizedPnl', 'unRealizedProfit', 'unrealizedProfit',
                                                'pnl_unrealized_usd', 'pnl_usd', 'pnl', 'unrealized', 'unrealized_pnl'
                                            ):
                                                if key in pp:
                                                    try:
                                                        return float(pp.get(key) or 0.0)
                                                    except Exception:
                                                        return 0.0
                                            return 0.0

                                        def _p_roe_pct(pp: dict) -> float:
                                            for key in ('roe', 'roe_pct', 'pnl_pct', 'return_pct'):
                                                if key in pp:
                                                    try:
                                                        return float(pp.get(key) or 0.0)
                                                    except Exception:
                                                        return 0.0
                                            return 0.0

                                        # Candidate selection: prefer same-symbol opposite side losing leg.
                                        candidate = None
                                        cand_loss = 0.0

                                        for p in positions:
                                            s = str(p.get('symbol') or '').upper().strip()
                                            sd = str(p.get('side') or p.get('positionSide') or '').upper().strip()
                                            if not s or sd not in ('LONG', 'SHORT'):
                                                continue
                                            loss = _p_unrealized_usd(p)
                                            if loss >= -float(PROFIT_TRIM_MIN_LOSS_USD or 0.0):
                                                continue
                                            # ROE gate: only trim deeply underwater positions (≤ threshold)
                                            roe = _p_roe_pct(p)
                                            if roe > float(PROFIT_TRIM_MIN_ROE_PCT or -100.0):
                                                continue
                                            # Avoid trimming hedged pairs unless explicitly allowed.
                                            if (not bool(PROFIT_TRIM_ALLOW_TRIM_HEDGED_PAIRS)) and len(sides_by_symbol.get(s, set())) >= 2:
                                                continue
                                            if s == profit_sym and profit_side and sd != profit_side:
                                                candidate = p
                                                cand_loss = loss
                                                break

                                        if candidate is None and bool(PROFIT_TRIM_ALLOW_CROSS_SYMBOL):
                                            # Cross-symbol: pick the most negative (largest loss magnitude)
                                            for p in positions:
                                                s = str(p.get('symbol') or '').upper().strip()
                                                sd = str(p.get('side') or p.get('positionSide') or '').upper().strip()
                                                if not s or sd not in ('LONG', 'SHORT'):
                                                    continue
                                                loss = _p_unrealized_usd(p)
                                                if loss >= -float(PROFIT_TRIM_MIN_LOSS_USD or 0.0):
                                                    continue
                                                # ROE gate: only trim deeply underwater positions (≤ threshold)
                                                roe = _p_roe_pct(p)
                                                if roe > float(PROFIT_TRIM_MIN_ROE_PCT or -100.0):
                                                    continue
                                                if (not bool(PROFIT_TRIM_ALLOW_TRIM_HEDGED_PAIRS)) and len(sides_by_symbol.get(s, set())) >= 2:
                                                    continue
                                                if candidate is None or loss < cand_loss:
                                                    candidate = p
                                                    cand_loss = loss

                                        if candidate is None:
                                            continue

                                        target_sym = str(candidate.get('symbol') or '').upper().strip()
                                        target_side = str(candidate.get('side') or candidate.get('positionSide') or '').upper().strip()
                                        if not target_sym or target_side not in ('LONG', 'SHORT'):
                                            continue

                                        loss_abs = abs(float(cand_loss)) if cand_loss < 0 else 0.0
                                        if loss_abs <= 0.0:
                                            continue

                                        credit_use = min(float(credit), float(PROFIT_TRIM_MAX_CREDIT_USE_USD or credit))
                                        if credit_use < float(PROFIT_TRIM_MIN_CREDIT_USD or 0.0):
                                            continue

                                        close_frac = min(float(PROFIT_TRIM_MAX_CLOSE_FRACTION or 0.50), max(0.0, credit_use / loss_abs))
                                        if close_frac <= 0.0:
                                            continue

                                        action_name = f"PARTIAL_CLOSE_{target_side}"
                                        trim_payload = {
                                            'account_id': acct,
                                            'symbol': target_sym,
                                            'timeframe': 'multi',
                                            'action': action_name,
                                            'action_name': action_name,
                                            'side': target_side,
                                            'confidence': float(max(0.85, min(0.99, conf))),
                                            'close_fraction': float(close_frac),
                                            'close_pct': float(close_frac) * 100.0,
                                            'action_category': 'PROTECTIVE',
                                            'source': 'profit_funded_trim',
                                            'bypass_gating': True,
                                            'gating_override': True,
                                            'trim_credit_used_usd': float(credit_use),
                                            # Observability: allow end-to-end reconciliation (profit credit vs loss realized)
                                            'trim_credit_balance_usd': float(credit),
                                            'trim_loss_abs_usd': float(loss_abs),
                                            # Intended: realize approx `credit_use` loss (before fees/slippage).
                                            'trim_expected_loss_usd': float(credit_use),
                                            'trim_profit_symbol': profit_sym,
                                            'trim_profit_event_id': str(self._last_trail_feedback_id),
                                            'reason': f"PROFIT_FUNDED_TRIM credit={credit_use:.2f} from {profit_sym} (conf={conf:.2f})",
                                        }

                                        built = None
                                        try:
                                            built = self._publish_signal_payload(trim_payload, contract_required=False)
                                        except Exception:
                                            built = None

                                        if built:
                                            counts[acct] = used + 1
                                            self._profit_trim_counts = counts
                                            # Spend credit only on successful publish
                                            new_balance = max(0.0, float(credit) - float(credit_use))
                                            try:
                                                self._profit_trim_credit_usd[acct] = new_balance
                                            except Exception:
                                                pass
                                            logger.warning(
                                                f"[PROFIT_TRIM] Emitted {action_name} {target_sym} acct={acct} "
                                                f"close={close_frac*100:.2f}% using_credit=${credit_use:.2f} (loss≈${loss_abs:.2f}) | credit_balance=${new_balance:.2f}"
                                            )
                    except Exception as parse_err:
                        logger.warning(f"[HEDGE_BUILD] Failed to parse feedback: {parse_err}")
        except (ConnectionError, TimeoutError, OSError):
            pass  # Transient connection issues - silently skip
        except Exception as e:
            # Only log unexpected errors
            if "Timeout" not in str(e) and "socket" not in str(e).lower():
                logger.warning(f"[HEDGE_BUILD] Trail feedback processing error: {e}")
    
    def _enter_hedge_build_state(self, symbol: str, side: str, reason: str = "trailing_exit", account_id: str = None):
        """Enter HEDGE_BUILD state after a trailing exit"""
        try:
            from config import HEDGE_BUILD_ENABLED, HEDGE_BUILD_TTL_SECONDS
            if not HEDGE_BUILD_ENABLED:
                return
            
            redis_client = getattr(self, 'redis', None) or getattr(self, '_signal_redis', None)
            if not redis_client:
                logger.warning(f"[HEDGE_BUILD] No Redis client for {symbol}")
                return
            
            acct = (str(account_id).strip().lower() if account_id else None)
            # Critical: per-account HEDGE_BUILD keys (primary/asjad independent)
            key = f"wma:hedge_build:{acct}:{symbol}" if acct else f"wma:hedge_build:{symbol}"
            state = {
                'symbol': symbol,
                'exited_side': side,
                'reason': reason,
                'account_id': acct,
                'timestamp': time.time(),
                'ttl_seconds': HEDGE_BUILD_TTL_SECONDS
            }
            import json
            redis_client.setex(key, HEDGE_BUILD_TTL_SECONDS, json.dumps(state))

            # Backward compatibility: also write legacy symbol-only key, but gating prefers account-scoped.
            # This keeps older dashboards/monitors functional without reintroducing cross-account gating.
            try:
                legacy_key = f"wma:hedge_build:{symbol}"
                redis_client.setex(legacy_key, HEDGE_BUILD_TTL_SECONDS, json.dumps(state))
            except Exception:
                pass

            acct_tag = f" account={acct}" if acct else ""
            logger.info(f"HEDGE_BUILD_ENTER | {symbol} | exited_side={side} | reason={reason} | ttl={HEDGE_BUILD_TTL_SECONDS}s{acct_tag}")
        except Exception as e:
            logger.warning(f"[HEDGE_BUILD] Failed to enter state for {symbol}: {e}")
    
    def _is_hedge_build_active(self, symbol: str) -> bool:
        """Check if symbol is in HEDGE_BUILD state"""
        try:
            from config import HEDGE_BUILD_ENABLED
            if not HEDGE_BUILD_ENABLED:
                return False
            
            redis_client = getattr(self, 'redis', None)
            if not redis_client:
                return False
            
            key = f"wma:hedge_build:{symbol}"
            state = redis_client.get(key)
            return bool(state)
        except Exception:
            return False

    def _publish_signal_payload(self, payload: dict, *, stream: str = None, contract_required: bool = True):
        """Delegate to ppo_model's _publish_signal_payload method.
        
        This wrapper enables HybridTrainer methods to call signal publishing
        using the canonical builder in GPUForcedPPO.
        """
        if hasattr(self, 'ppo_model') and self.ppo_model is not None:
            return self.ppo_model._publish_signal_payload(payload, stream=stream, contract_required=contract_required)
        else:
            logger.warning("[PUBLISH] Cannot publish signal - ppo_model not initialized")
            return None

    def _publish_signal_unified(self, payload: dict, *, stream: str = None, contract_required: bool = True):
        """
        Unified publisher for non-GPU modules (URC / hedge builders / flash hedge / harvest).

        Goal:
        - When ORCHESTRATOR_WORKER_MODE=publish, route ALL signals through _emit_proposal()
          to the orchestrator worker for proper arbitration.
        - When ORCHESTRATOR_WORKER_MODE=shadow or disabled, use legacy publish path.

        Safety:
        - In publish mode, NO FALLBACK to direct publish.
        - In shadow mode, legacy behavior is preserved.
        """
        try:
            if not payload.get("structural_regime"):
                structural = self._get_structural_regime_context(str(payload.get("symbol") or ""))
                payload["structural_regime"] = structural.get("effective_regime")
                payload["macro_regime"] = structural.get("macro_regime")
                payload["structural_time_in_state_days"] = structural.get("time_in_state_days")
                payload["structural_metrics"] = structural.get("metrics")
                payload["risk_mode"] = structural.get("risk_mode")
        except Exception:
            pass
        try:
            from config import (
                ORCHESTRATOR_WORKER_ENABLED,
                ORCHESTRATOR_WORKER_MODE,
            )
        except ImportError:
            ORCHESTRATOR_WORKER_ENABLED = False
            ORCHESTRATOR_WORKER_MODE = "shadow"

        # ========================================================================
        # HEDGE/PROTECTIVE: route through orchestrator unless very high confidence
        # ========================================================================
        try:
            action = str(payload.get("action") or payload.get("action_name") or "").upper()
            category_hint = str(payload.get("action_category") or payload.get("category") or "").upper()
            hedge_mode = str(payload.get("hedge_mode") or "").upper()
            is_hedge = bool(
                category_hint in ("HEDGE", "PROTECTIVE")
                or payload.get("hedge_intent")
                or payload.get("ecf_signal")
                or ("HEDGE" in action)
            )
        except Exception:
            is_hedge = False

        if is_hedge:
            # Feb 2026: HEDGE_DIRECT_PUBLISH_BYPASS default is now FALSE.
            # All hedges/protective signals go through orchestrator (fast lane handles urgency).
            # Emergency bypass is the only exception: requires risk_reducing + urgency=EMERGENCY
            # AND orchestrator heartbeat stale (unavailable).
            try:
                from config import (
                    ENABLE_PER_ACCOUNT_STREAMS,
                    SIGNAL_STREAM_PER_ACCOUNT,
                    TRADING_ACCOUNTS,
                    HEDGE_DIRECT_PUBLISH_BYPASS_ENABLED,
                    HEDGE_DIRECT_PUBLISH_BYPASS_MIN_CONF,
                    ORCH_EMERGENCY_BYPASS_ENABLED,
                    ORCH_EMERGENCY_BYPASS_ORCH_STALE_MS,
                    ORCH_EMERGENCY_BYPASS_LIQ_BPS,
                    ORCH_EMERGENCY_BYPASS_MARGIN_UTIL,
                )
            except Exception:
                ENABLE_PER_ACCOUNT_STREAMS = True
                SIGNAL_STREAM_PER_ACCOUNT = {"primary": "signals:trading:primary", "asjad": "signals:trading:asjad"}
                TRADING_ACCOUNTS = ["primary", "asjad"]
                HEDGE_DIRECT_PUBLISH_BYPASS_ENABLED = False
                HEDGE_DIRECT_PUBLISH_BYPASS_MIN_CONF = 0.95
                ORCH_EMERGENCY_BYPASS_ENABLED = True
                ORCH_EMERGENCY_BYPASS_ORCH_STALE_MS = 5000
                ORCH_EMERGENCY_BYPASS_LIQ_BPS = 100.0
                ORCH_EMERGENCY_BYPASS_MARGIN_UTIL = 0.90

            # ── Emergency bypass: risk-reducing + EMERGENCY urgency + orch unavailable ──
            # Only allow when ALL conditions met:
            #   1. ORCH_EMERGENCY_BYPASS_ENABLED=true
            #   2. risk_reducing=True (CLOSE/DECREASE/PROTECTIVE only, NEVER OPEN/INCREASE)
            #   3. urgency=EMERGENCY or near-liquidation context
            #   4. Orchestrator heartbeat is stale (unavailable)
            _is_emergency_eligible = False
            try:
                if bool(ORCH_EMERGENCY_BYPASS_ENABLED):
                    _action_u_chk = str(action).upper()
                    # Hard-deny risk-add actions even if mislabeled as risk_reducing.
                    # OPEN/INCREASE/ADD/FLIP never qualify for emergency bypass.
                    _HARD_DENY_TOKENS = ("OPEN_", "INCREASE_", "ADD_", "CLOSE_AND_")
                    _is_hard_denied = any(tok in _action_u_chk for tok in _HARD_DENY_TOKENS)
                    _is_risk_reducing_chk = (
                        not _is_hard_denied
                        and (
                            bool(payload.get("risk_reducing"))
                            or any(tok in _action_u_chk for tok in ("CLOSE", "DECREASE", "EXIT", "PARTIAL_CLOSE", "REDUCE"))
                        )
                    )
                    _urgency_chk = str(payload.get("urgency") or "").upper()
                    # Emergency context requires explicit urgency=EMERGENCY label.
                    # liq_bps / margin_util alone are no longer sufficient — the payload
                    # producer must explicitly classify the urgency to prevent false positives.
                    _has_emergency_context = (_urgency_chk == "EMERGENCY")
                    # Check orchestrator liveness from Redis
                    _orch_alive = True
                    try:
                        _rc = (
                            getattr(self, "_signal_redis", None)
                            or getattr(self, "redis", None)
                            or getattr(getattr(self, "ppo_model", None), "_signal_redis", None)
                        )
                        if _rc:
                            _hb_raw = _rc.get("orchestrator:heartbeat_ms")
                            _hb_ms = int(_hb_raw.decode("utf-8") if isinstance(_hb_raw, (bytes, bytearray)) else (_hb_raw or 0))
                            _hb_age_ms = int(time.time() * 1000) - _hb_ms
                            _stale_threshold = int(ORCH_EMERGENCY_BYPASS_ORCH_STALE_MS)
                            if _hb_age_ms > _stale_threshold:
                                _orch_alive = False
                                logger.warning(
                                    "[EMERGENCY_BYPASS] Orchestrator heartbeat stale: age=%dms threshold=%dms",
                                    _hb_age_ms, _stale_threshold,
                                )
                    except Exception:
                        _orch_alive = True  # fail-safe: assume alive if check fails
                    _is_emergency_eligible = (
                        _is_risk_reducing_chk
                        and _has_emergency_context
                        and not _orch_alive
                    )
            except Exception:
                _is_emergency_eligible = False

            # direct publish is emergency-only; conf-based bypass permanently disabled
            # (all non-emergency signals must route through orchestrator)
            _conf_bypass_allowed = False

            bypass_allowed = _is_emergency_eligible
            if bypass_allowed:
                # Respect per-account scoping when present; otherwise publish to both accounts.
                requested_acct = payload.get("account_id") or payload.get("account") or payload.get("target_account_id")
                try:
                    if isinstance(requested_acct, (bytes, bytearray)):
                        requested_acct = requested_acct.decode("utf-8", errors="ignore")
                except Exception:
                    pass
                requested_acct = str(requested_acct or "").strip().lower()

                target_streams = []
                if ENABLE_PER_ACCOUNT_STREAMS and isinstance(SIGNAL_STREAM_PER_ACCOUNT, dict) and SIGNAL_STREAM_PER_ACCOUNT:
                    if requested_acct in SIGNAL_STREAM_PER_ACCOUNT:
                        target_streams = [SIGNAL_STREAM_PER_ACCOUNT[requested_acct]]
                    else:
                        for acct in TRADING_ACCOUNTS or []:
                            s = SIGNAL_STREAM_PER_ACCOUNT.get(str(acct).strip().lower())
                            if s:
                                target_streams.append(s)
                if not target_streams:
                    # Fallback to legacy/global stream if per-account routing misconfigured
                    target_streams = [stream or "signals:trading"]

                # Pair-cap clamp for direct publish (avoid trader-side CAP blocks)
                try:
                    from config import (
                        PER_ACCOUNT_PAIR_CAPS,
                        STACK_OPEN_MAX_MARGIN_USD,
                        STACK_OPEN_MAX_EQUITY_PCT,
                        TIER3_SYMBOLS,
                        TIER3_PAIR_CAP_MAX_USD,
                        MANUAL_HEDGE_PAIR_CAP_OVERRIDE_ENABLED,
                        MANUAL_HEDGE_PAIR_CAP_EQUITY_PCT,
                        MANUAL_HEDGE_PAIR_CAP_EXCLUDE_SYMBOLS,
                        POSITION_ORIGIN_KEY_PREFIX,
                    )
                except Exception:
                    PER_ACCOUNT_PAIR_CAPS = {}
                    STACK_OPEN_MAX_MARGIN_USD = 300.0
                    STACK_OPEN_MAX_EQUITY_PCT = 0.10
                    TIER3_SYMBOLS = []
                    TIER3_PAIR_CAP_MAX_USD = 200.0
                    MANUAL_HEDGE_PAIR_CAP_OVERRIDE_ENABLED = False
                    MANUAL_HEDGE_PAIR_CAP_EQUITY_PCT = 0.50
                    MANUAL_HEDGE_PAIR_CAP_EXCLUDE_SYMBOLS = ["BTCUSDT", "ETHUSDT"]
                    POSITION_ORIGIN_KEY_PREFIX = "wma:position_origin"

                try:
                    sym = str(payload.get("symbol") or "").upper().strip()
                    acct = requested_acct if requested_acct in ("primary", "asjad") else None
                    if acct and sym:
                        # Compute cap
                        acct_caps = (PER_ACCOUNT_PAIR_CAPS or {}).get(acct, {}) if isinstance(PER_ACCOUNT_PAIR_CAPS, dict) else {}
                        base_cap = float(acct_caps.get("max_margin_usd") or STACK_OPEN_MAX_MARGIN_USD or 300.0)
                        pct = float(acct_caps.get("max_equity_pct") or STACK_OPEN_MAX_EQUITY_PCT or 0.10)

                        rc = getattr(self, "_signal_redis", None) or getattr(self, "redis", None)
                        wallet = 0.0
                        eq_basis = 0.0
                        if rc is not None:
                            eq_raw = rc.get(f"portfolio:equity:{acct}")
                            eq_raw = eq_raw.decode("utf-8", errors="ignore") if isinstance(eq_raw, (bytes, bytearray)) else eq_raw
                            eqj = json.loads(eq_raw) if isinstance(eq_raw, str) and eq_raw.strip().startswith("{") else {}
                            try:
                                wallet = float(
                                    (eqj or {}).get("wallet_balance_usd")
                                    or (eqj or {}).get("wallet_balance")
                                    or (eqj or {}).get("balance")
                                    or 0.0
                                )
                            except Exception:
                                wallet = 0.0
                            try:
                                eq_basis = float((eqj or {}).get("equity_usd") or (eqj or {}).get("margin_balance_usd") or wallet or 0.0)
                            except Exception:
                                eq_basis = wallet
                        cap = max(base_cap, wallet * pct) if wallet > 0 else base_cap

                        # Tier-3 hard cap (operator request)
                        sym_is_tier3 = bool(sym and sym in set(TIER3_SYMBOLS or []))
                        if sym_is_tier3:
                            cap = min(float(cap), float(TIER3_PAIR_CAP_MAX_USD))

                        # Compute existing pair margin (LONG+SHORT)
                        existing_margin = 0.0
                        leg_margins = {"LONG": 0.0, "SHORT": 0.0}
                        if rc is not None:
                            pos_key = f"portfolio:positions:{acct}"
                            raw_long = rc.hget(pos_key, f"{sym}:LONG")
                            raw_short = rc.hget(pos_key, f"{sym}:SHORT")
                            for raw, leg_side in ((raw_long, "LONG"), (raw_short, "SHORT")):
                                if not raw:
                                    continue
                                try:
                                    s = raw.decode("utf-8", errors="ignore") if isinstance(raw, (bytes, bytearray)) else raw
                                    d = json.loads(s) if isinstance(s, str) and s.strip().startswith("{") else {}
                                    m = float(d.get("margin_used") or d.get("initialMargin") or 0.0)
                                    existing_margin += abs(m)
                                    leg_margins[leg_side] = abs(m)
                                except Exception:
                                    continue

                        # Manual override: if manual leg exceeds base cap, allow hedges up to 50% equity
                        manual_override = False
                        if bool(MANUAL_HEDGE_PAIR_CAP_OVERRIDE_ENABLED) and sym not in set(MANUAL_HEDGE_PAIR_CAP_EXCLUDE_SYMBOLS or []):
                            try:
                                for leg_side in ("LONG", "SHORT"):
                                    if float(leg_margins.get(leg_side, 0.0)) <= 0.0:
                                        continue
                                    raw_origin = rc.get(f"{POSITION_ORIGIN_KEY_PREFIX}:{acct}:{sym}:{leg_side}") if rc else None
                                    if raw_origin:
                                        raw_origin = raw_origin.decode("utf-8", errors="ignore") if isinstance(raw_origin, (bytes, bytearray)) else raw_origin
                                        try:
                                            origin_val = json.loads(raw_origin).get("origin") if isinstance(raw_origin, str) else None
                                        except Exception:
                                            origin_val = str(raw_origin)
                                        if str(origin_val or "").lower() == "manual" and float(leg_margins.get(leg_side, 0.0)) > float(cap):
                                            manual_override = True
                                            break
                            except Exception:
                                manual_override = False
                        if manual_override and eq_basis > 0:
                            cap = max(float(cap), float(eq_basis) * float(MANUAL_HEDGE_PAIR_CAP_EQUITY_PCT))

                        headroom = max(0.0, float(cap) - float(existing_margin))
                        # Determine requested margin
                        try:
                            mreq = float(payload.get("margin_usd", 0.0) or 0.0)
                        except Exception:
                            mreq = 0.0
                        if mreq <= 0.0:
                            try:
                                notional = float(payload.get("notional_usd", 0.0) or 0.0)
                            except Exception:
                                notional = 0.0
                            try:
                                lev = float(payload.get("leverage", payload.get("recommended_leverage", 10)) or 10.0)
                            except Exception:
                                lev = 10.0
                            if lev <= 0:
                                lev = 10.0
                            mreq = (notional / lev) if notional > 0 else 0.0

                        if headroom <= 0.0:
                            # No headroom: fall back to orchestrator (avoid contract violations)
                            logger.warning(
                                f"⚠️ [HEDGE_DIRECT_PUBLISH] No headroom for {acct}:{sym} cap={cap:.2f} existing={existing_margin:.2f}; routing to orchestrator"
                            )
                            source = payload.get("source") or payload.get("source_module") or "trainer_unified"
                            category = category_hint or ("PROTECTIVE" if hedge_mode == "SHIELD" else "HEDGE")
                            priority = 3 if hedge_mode == "SHIELD" else 1
                            if payload.get("ecf_signal") or "ECF" in action:
                                priority = 4
                            emitted = self._emit_proposal(
                                payload,
                                source_module=source,
                                priority=priority,
                                category=category,
                            )
                            return payload if emitted else None

                        if mreq > 0.0 and headroom > 0.0 and mreq > headroom:
                            scale = max(0.05, min(1.0, headroom / mreq))
                            payload["_pair_cap_resized"] = True
                            payload["_pair_cap_resize_scale"] = float(scale)
                            payload["_pair_cap_headroom"] = float(headroom)
                            payload["_pair_cap_existing_margin"] = float(existing_margin)
                            payload["_pair_cap_max"] = float(cap)
                            try:
                                payload["margin_usd"] = float(payload.get("margin_usd", mreq) or mreq) * scale
                            except Exception:
                                payload["margin_usd"] = float(mreq) * scale
                            try:
                                payload["notional_usd"] = float(payload.get("notional_usd", 0.0) or 0.0) * scale
                            except Exception:
                                pass
                            try:
                                payload["position_size_pct"] = float(payload.get("position_size_pct", 0.0) or 0.0) * scale
                            except Exception:
                                pass
                except Exception as clamp_err:
                    logger.debug(f"[HEDGE_DIRECT_PUBLISH] pair-cap clamp failed: {clamp_err}")

                direct_stream = ",".join(target_streams)
                payload["_orchestrator_bypass"] = True
                payload["emergency_bypass"] = 1
                _bypass_reason = "emergency_orch_stale+risk_reducing"
                payload["_orchestrator_bypass_reason"] = _bypass_reason
                logger.warning(
                    "⚡ [HEDGE_DIRECT_PUBLISH] %s %s reason=%s streams=%s",
                    payload.get("symbol"), action, _bypass_reason, direct_stream,
                )
                return self._publish_signal_payload(payload, stream=direct_stream, contract_required=contract_required)

            source = payload.get("source") or payload.get("source_module") or "trainer_unified"
            category = category_hint or ("PROTECTIVE" if hedge_mode == "SHIELD" else "HEDGE")
            priority = 1
            if hedge_mode == "SHIELD":
                priority = 3
            if payload.get("ecf_signal") or "ECF" in action:
                priority = 4
            emitted = self._emit_proposal(
                payload,
                source_module=source,
                priority=priority,
                category=category,
            )
            return payload if emitted else None
        
        # ========================================================================
        # ORCHESTRATOR WORKER MODE: Route through proposal stream
        # ========================================================================
        if ORCHESTRATOR_WORKER_ENABLED and str(ORCHESTRATOR_WORKER_MODE).lower() == "publish":
            # In publish mode, ALL signals go through orchestrator
            # Infer source and category from payload
            source = payload.get("source") or payload.get("source_module") or "trainer_unified"
            category = payload.get("action_category") or payload.get("category") or ""
            
            # Infer priority
            priority = 1  # NORMAL default
            if payload.get("fastlane") or payload.get("bypass_validation"):
                priority = 2  # HIGH
            if "SHIELD" in str(payload.get("hedge_mode") or "").upper():
                priority = 3  # CRITICAL
            if payload.get("ecf_signal") or "ECF" in str(payload.get("action") or "").upper():
                priority = 4  # IMMEDIATE
            
            emitted = self._emit_proposal(
                payload,
                source_module=source,
                priority=priority,
                category=category,
            )
            
            # Return payload if emitted successfully, None otherwise
            # NO FALLBACK - if emit fails, signal is dropped
            return payload if emitted else None
        
        # ========================================================================
        # LEGACY MODE: Use buffered pipeline or direct publish
        # ========================================================================
        try:
            from config import UNIFY_NON_GPU_PUBLISH_THROUGH_BUFFERED
        except Exception:
            UNIFY_NON_GPU_PUBLISH_THROUGH_BUFFERED = False

        # Preferred: publish via buffered pipeline (single publisher surface).
        if bool(UNIFY_NON_GPU_PUBLISH_THROUGH_BUFFERED):
            try:
                if hasattr(self, "ppo_model") and self.ppo_model is not None and hasattr(self.ppo_model, "_publish_buffered_signals"):
                    # Ensure stream override is carried (buffered publisher supports per-payload stream via SIGNAL_OUTPUT_STREAM).
                    p2 = dict(payload or {})
                    if stream:
                        p2["_override_stream"] = str(stream)
                    # _publish_buffered_signals returns count
                    n = int(self.ppo_model._publish_buffered_signals([p2]) or 0)
                    return p2 if n > 0 else None
            except Exception as e:
                logger.debug(f"[PUBLISH_UNIFIED] buffered publish failed (fallback to direct): {e}")

        # Fallback: direct publish (legacy - only in shadow mode)
        return self._publish_signal_payload(payload, stream=stream, contract_required=contract_required)

    def _emit_proposal(
        self,
        payload: dict,
        *,
        source_module: str,
        priority: int = 1,
        category: str = "",
    ) -> bool:
        """
        Emit a trade proposal to the orchestrator worker.
        
        THIS IS THE ONLY WAY MODULES SHOULD PUBLISH IN ORCHESTRATOR_WORKER_MODE=publish.
        
        NO FALLBACK TO DIRECT PUBLISH.
        
        Args:
            payload: Signal/proposal data
            source_module: Module name (e.g., "hedge_manager_v3", "urc", "dynamic_tp")
            priority: 0=LOW, 1=NORMAL, 2=HIGH, 3=CRITICAL, 4=IMMEDIATE
            category: Action category (HEDGE, RECOVERY, CLOSE_PROFIT, etc.)
        
        Returns:
            True if proposal was emitted successfully, False otherwise.
            Does NOT fall back to direct publish.
        """
        try:
            from config import (
                ORCHESTRATOR_WORKER_ENABLED,
                ORCHESTRATOR_WORKER_MODE,
                ORCHESTRATOR_UNIFIED_PROPOSAL_STREAM,
            )
        except ImportError:
            ORCHESTRATOR_WORKER_ENABLED = False
            ORCHESTRATOR_WORKER_MODE = "shadow"
            ORCHESTRATOR_UNIFIED_PROPOSAL_STREAM = "wma:proposals"
        
        # Get Redis client
        redis_client = (
            getattr(self, "_signal_redis", None)
            or getattr(self, "redis", None)
            or getattr(getattr(self, "ppo_model", None), "_signal_redis", None)
            or getattr(getattr(self, "ppo_model", None), "redis", None)
        )
        
        if redis_client is None:
            logger.error(f"[EMIT_PROPOSAL] No Redis client available - cannot emit proposal")
            return False

        # Source-side hygiene (fail-closed before proposal emission)
        try:
            from config import (
                get_action_category,
                TRAINER_SOURCE_REQUIRE_CONTEXT_FOR_OPEN_RISK,
                TRAINER_SOURCE_REQUIRE_DECISION_ID_FOR_OPEN_RISK,
                TRAINER_SOURCE_REQUIRED_TF_FIELDS,
                TRAINER_SOURCE_REQUIRED_LIQ_FIELDS,
                TRAINER_SOURCE_MISSING_CONTEXT_ACTION,
                PROBE_ALLOW_OPEN_RISK,
                TRAINER_CLAMP_PROPOSAL_CONFIDENCE,
                TRAINER_PROPOSAL_CONFIDENCE_MIN,
                TRAINER_PROPOSAL_CONFIDENCE_MAX,
                UNIVERSE_ENFORCEMENT_ENABLED,
                UNIVERSE_ENFORCE_TRAINER,
                UNIVERSE_ALLOWED_SYMBOLS,
            )
        except Exception:
            def get_action_category(action_name: str) -> str:
                return "OPEN_RISK" if str(action_name or "").upper().startswith(("OPEN_", "INCREASE_", "CLOSE_AND_", "FLIP_")) else "PROTECTIVE"
            TRAINER_SOURCE_REQUIRE_CONTEXT_FOR_OPEN_RISK = True
            TRAINER_SOURCE_REQUIRE_DECISION_ID_FOR_OPEN_RISK = True
            TRAINER_SOURCE_REQUIRED_TF_FIELDS = ["bias_dir", "timing_dir", "conflict_score", "tf_votes"]
            TRAINER_SOURCE_REQUIRED_LIQ_FIELDS = ["liquidation_long_strength", "liquidation_short_strength"]
            TRAINER_SOURCE_MISSING_CONTEXT_ACTION = "HOLD"
            PROBE_ALLOW_OPEN_RISK = False
            TRAINER_CLAMP_PROPOSAL_CONFIDENCE = True
            TRAINER_PROPOSAL_CONFIDENCE_MIN = 0.01
            TRAINER_PROPOSAL_CONFIDENCE_MAX = 0.99
            UNIVERSE_ENFORCEMENT_ENABLED = True
            UNIVERSE_ENFORCE_TRAINER = True
            UNIVERSE_ALLOWED_SYMBOLS = list(getattr(config, "SYMBOLS", []) or [])

        def _meta_get(key: str):
            """Look up a field by canonical name, then tf_-prefixed alias, in both payload and metadata."""
            md = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
            # Try canonical name first
            if payload.get(key) is not None:
                return payload.get(key)
            if md.get(key) is not None:
                return md.get(key)
            # Try tf_-prefixed alias (bias_dir → tf_bias_dir, etc.)
            try:
                aliases = getattr(config, "TRAINER_SOURCE_TF_FIELD_ALIASES", {}) or {}
                for alias in (aliases.get(key) or []):
                    if alias != key:
                        if payload.get(alias) is not None:
                            return payload.get(alias)
                        if md.get(alias) is not None:
                            return md.get(alias)
            except Exception:
                # Hardcoded fallback in case config unavailable
                tf_key = f"tf_{key}" if not key.startswith("tf_") else key
                if tf_key != key:
                    if payload.get(tf_key) is not None:
                        return payload.get(tf_key)
                    if md.get(tf_key) is not None:
                        return md.get(tf_key)
            return None

        def _has_value(v: Any) -> bool:
            if v is None:
                return False
            if isinstance(v, str):
                return bool(v.strip())
            if isinstance(v, (list, tuple, dict, set)):
                return len(v) > 0
            return True

        act_u = str(payload.get("action") or payload.get("action_name") or "").upper().strip()
        cat_u = str(payload.get("action_category") or payload.get("category") or "").upper().strip()
        sym_u = str(payload.get("symbol") or "").upper().strip()
        if not cat_u:
            cat_u = str(get_action_category(act_u) or "").upper().strip()
        is_open_risk = cat_u == "OPEN_RISK"

        # Canonical universe gate at source emission boundary.
        try:
            enforce_universe = bool(UNIVERSE_ENFORCEMENT_ENABLED) and bool(UNIVERSE_ENFORCE_TRAINER)
            allowed_syms = {
                str(s or "").upper().strip()
                for s in (UNIVERSE_ALLOWED_SYMBOLS or [])
                if str(s or "").strip()
            }
            if enforce_universe and (not sym_u or sym_u not in allowed_syms):
                logger.warning(
                    "[SOURCE_SYMBOL_DENY] blocked proposal symbol=%s source=%s action=%s reason=SYMBOL_NOT_ALLOWED",
                    sym_u,
                    str(source_module),
                    act_u,
                )
                try:
                    self._publish_exec_event(
                        code="SYMBOL_NOT_ALLOWED_AT_SOURCE",
                        account_id=str(payload.get("account_id") or "primary"),
                        symbol=sym_u,
                        action=act_u,
                        meta={
                            "source_module": str(source_module),
                            "allow_count": int(len(allowed_syms)),
                        },
                    )
                except Exception:
                    pass
                return False
        except Exception:
            pass

        # Confidence hygiene: avoid saturated display/gating values.
        try:
            if TRAINER_CLAMP_PROPOSAL_CONFIDENCE and (payload.get("confidence") is not None or payload.get("model_confidence") is not None):
                conf_raw = float(payload.get("confidence", payload.get("model_confidence", 0.0)) or 0.0)
                cmin = float(TRAINER_PROPOSAL_CONFIDENCE_MIN)
                cmax = float(TRAINER_PROPOSAL_CONFIDENCE_MAX)
                if cmax < cmin:
                    cmin, cmax = cmax, cmin
                conf_clamped = max(cmin, min(cmax, conf_raw))
                payload["raw_confidence"] = conf_raw
                payload["confidence"] = conf_clamped
                payload["model_confidence"] = conf_clamped
                if conf_clamped != conf_raw:
                    logger.info(
                        "[PROPOSAL_CONF_CLAMP] symbol=%s action=%s source=%s raw=%.6f clamped=%.6f",
                        str(payload.get("symbol") or ""),
                        act_u,
                        str(source_module),
                        conf_raw,
                        conf_clamped,
                    )
        except Exception:
            pass

        # Ensure decision_id exists for proof correlation.
        if not payload.get("decision_id"):
            sym0 = str(payload.get("symbol") or "").upper().strip() or "UNKNOWN"
            tf0 = str(payload.get("timeframe") or payload.get("tf") or "na").lower().strip() or "na"
            payload["decision_id"] = f"{int(time.time() * 1000)}-{sym0}-{tf0}-SOURCE"

        # Probe streams must not synthesize OPEN_RISK by default.
        source_u = str(source_module or "").strip().lower()
        probe_like_source = source_u.startswith("probe") or source_u.startswith("probe_") or source_u.startswith("probe-")
        if is_open_risk and probe_like_source and (not bool(PROBE_ALLOW_OPEN_RISK)):
            old_action = act_u
            hold_action = str(TRAINER_SOURCE_MISSING_CONTEXT_ACTION or "HOLD").upper().strip() or "HOLD"
            payload["source_gate_code"] = "PROBE_OPEN_RISK_DISABLED"
            payload["source_gate_reason"] = "PROBE_OPEN_RISK_DISABLED"
            payload["source_context_ok"] = False
            payload["source_open_risk_suppressed"] = True
            payload["blocked_action"] = old_action
            payload["blocked_action_category"] = "OPEN_RISK"
            payload["action"] = hold_action
            payload["action_name"] = hold_action
            payload["action_category"] = "PROTECTIVE"
            payload["category"] = "PROTECTIVE"
            payload["confidence"] = 0.01
            payload["model_confidence"] = 0.01
            try:
                self._publish_exec_event(
                    code="PROBE_OPEN_RISK_DISABLED",
                    account_id=str(payload.get("account_id") or "primary"),
                    symbol=str(payload.get("symbol") or "").upper(),
                    action=old_action,
                    meta={"source_module": source_u, "fallback_action": hold_action},
                )
            except Exception:
                pass

            act_u = str(payload.get("action") or payload.get("action_name") or "").upper().strip()
            cat_u = "PROTECTIVE"
            is_open_risk = False

        # OPEN_RISK must carry TF + liquidation context at source (fail-closed to HOLD).
        if is_open_risk and bool(TRAINER_SOURCE_REQUIRE_CONTEXT_FOR_OPEN_RISK):
            missing_fields = []
            for k in list(TRAINER_SOURCE_REQUIRED_TF_FIELDS or []):
                if not _has_value(_meta_get(str(k))):
                    missing_fields.append(str(k))
            for k in list(TRAINER_SOURCE_REQUIRED_LIQ_FIELDS or []):
                if not _has_value(_meta_get(str(k))):
                    missing_fields.append(str(k))
            if bool(TRAINER_SOURCE_REQUIRE_DECISION_ID_FOR_OPEN_RISK) and not _has_value(payload.get("decision_id")):
                missing_fields.append("decision_id")

            # PQC: Also detect "TF stack present but all-zero" (all TFs returned FLAT)
            # Gated by TF_STACK_PQC_GATE_ENABLED (default False) — prevents restart deadlock.
            if getattr(self.main_config, "TF_STACK_PQC_GATE_ENABLED", False):
                _src_tf_votes = _meta_get("tf_votes")
                _src_bias_dir = _meta_get("bias_dir")
                _src_timing_dir = _meta_get("timing_dir")
                if isinstance(_src_tf_votes, dict) and _src_tf_votes:
                    if all(int(v or 0) == 0 for v in _src_tf_votes.values()):
                        missing_fields.append("tf_votes_all_zero(TF_STACK_ALL_FLAT)")
                elif not _src_tf_votes and int(_src_bias_dir or 0) == 0 and int(_src_timing_dir or 0) == 0:
                    if "tf_votes" not in missing_fields:
                        missing_fields.append("tf_votes_empty(TF_STACK_MISSING)")

            if missing_fields:
                old_action = act_u
                hold_action = str(TRAINER_SOURCE_MISSING_CONTEXT_ACTION or "HOLD").upper().strip() or "HOLD"
                payload["source_gate_code"] = "MISSING_TF_CONTEXT_AT_SOURCE"
                payload["source_gate_reason"] = "MISSING_TF_CONTEXT_AT_SOURCE"
                payload["source_context_ok"] = False
                payload["source_missing_fields"] = missing_fields
                payload["blocked_action"] = old_action
                payload["blocked_action_category"] = "OPEN_RISK"
                payload["action"] = hold_action
                payload["action_name"] = hold_action
                payload["action_category"] = "PROTECTIVE"
                payload["category"] = "PROTECTIVE"
                payload["confidence"] = 0.01
                payload["model_confidence"] = 0.01
                logger.warning(
                    "[SOURCE_CONTEXT_GATE] blocked_open_risk symbol=%s source=%s action=%s missing=%s fallback=%s",
                    str(payload.get("symbol") or "").upper(),
                    source_u,
                    old_action,
                    ",".join(missing_fields),
                    hold_action,
                )
                try:
                    self._publish_exec_event(
                        code="MISSING_TF_CONTEXT_AT_SOURCE",
                        account_id=str(payload.get("account_id") or "primary"),
                        symbol=str(payload.get("symbol") or "").upper(),
                        action=old_action,
                        meta={
                            "source_module": source_u,
                            "missing_fields": missing_fields,
                            "fallback_action": hold_action,
                            "decision_id": str(payload.get("decision_id") or ""),
                        },
                    )
                except Exception:
                    pass

        # ---------- STALE / DEFENSIVE REGIME OPEN_RISK GUARD ----------
        # If data is stale OR regime is HIGH stress + DEFENSIVE risk mode,
        # only allow HOLD/REDUCE/PARTIAL_CLOSE/hedge — NO new entries.
        act_u2 = str(payload.get("action") or payload.get("action_name") or "").upper().strip()
        cat_u2 = str(payload.get("action_category") or payload.get("category") or "").upper().strip()
        is_open_risk2 = cat_u2 == "OPEN_RISK"
        if is_open_risk2:
            _regime_block_reason = None
            try:
                md = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
                # Check for stale orderbook (DQ watchdog flag)
                dq_source_ok = payload.get("dq_source_ok") or md.get("dq_source_ok")
                dq_ob_age = payload.get("dq_orderbook_age_ms") or md.get("dq_orderbook_age_ms")
                dq_liq_age = payload.get("dq_liqmap_age_ms") or md.get("dq_liqmap_age_ms")
                _OB_STALE_LIMIT_MS = 120_000  # 2 min
                _LIQ_STALE_LIMIT_MS = 180_000  # 3 min
                if dq_source_ok is False:
                    _regime_block_reason = "DQ_SOURCE_NOT_OK"
                elif dq_ob_age is not None and float(dq_ob_age) > _OB_STALE_LIMIT_MS:
                    _regime_block_reason = f"STALE_OB_age={int(dq_ob_age)}ms"
                elif dq_liq_age is not None and float(dq_liq_age) > _LIQ_STALE_LIMIT_MS:
                    _regime_block_reason = f"STALE_LIQMAP_age={int(dq_liq_age)}ms"

                # Check unified feature freshness (fail-closed): OPEN_RISK must not trade on stale/missing features.
                if not _regime_block_reason:
                    now_ms = int(time.time() * 1000)
                    feat_age = payload.get("features_age_ms") or md.get("features_age_ms")
                    feat_ts = payload.get("features_ts_ms") or md.get("features_ts_ms") or payload.get("feature_ts_ms") or md.get("feature_ts_ms")
                    try:
                        if feat_age is None and feat_ts:
                            feat_age = int(now_ms - int(feat_ts))
                    except Exception:
                        pass
                    # Best-effort Redis probe for unified_features ts_ms (5m) if missing.
                    try:
                        if feat_age is None and getattr(self, "redis", None):
                            sym_u = str(payload.get("symbol") or "").upper().strip()
                            if sym_u:
                                raw_ts = self.redis.hget(f"unified_features:{sym_u}:5m", "ts_ms")  # type: ignore[attr-defined]
                                if not raw_ts:
                                    raw_ts = self.redis.hget(f"unified_features:{sym_u}:5m", "timestamp")  # type: ignore[attr-defined]
                                if isinstance(raw_ts, (bytes, bytearray)):
                                    raw_ts = raw_ts.decode("utf-8", errors="ignore")
                                try:
                                    feat_ts_i = int(float(raw_ts or 0))
                                except Exception:
                                    feat_ts_i = 0
                                if feat_ts_i > 0:
                                    payload["features_ts_ms"] = feat_ts_i
                                    feat_age = int(now_ms - feat_ts_i)
                                    payload["features_age_ms"] = int(feat_age)
                    except Exception:
                        pass

                    try:
                        from config import OPEN_RISK_FEATURES_MAX_AGE_MS as _FEAT_STALE_LIMIT_MS
                        _FEAT_STALE_LIMIT_MS = int(_FEAT_STALE_LIMIT_MS)
                    except Exception:
                        _FEAT_STALE_LIMIT_MS = 120_000
                    if feat_age is None:
                        _regime_block_reason = "MISSING_FEATURE_TS"
                    else:
                        try:
                            if int(feat_age) > int(_FEAT_STALE_LIMIT_MS):
                                _regime_block_reason = f"STALE_FEATURES_age={int(feat_age)}ms"
                        except Exception:
                            pass

                # Check regime stress + defensive risk mode
                if not _regime_block_reason:
                    _r_stress = str(payload.get("regime_stress") or md.get("regime_stress") or "").upper().strip()
                    _r_risk = str(payload.get("structural_risk_mode") or md.get("structural_risk_mode") or md.get("risk_mode") or "").upper().strip()
                    if _r_stress == "HIGH" and _r_risk == "DEFENSIVE":
                        _regime_block_reason = "DEFENSIVE_HIGH_STRESS"
            except Exception:
                pass

            if _regime_block_reason:
                old_act = act_u2
                hold_act = "HOLD"
                payload["source_gate_code"] = "REGIME_STALE_BLOCK_AT_SOURCE"
                payload["source_gate_reason"] = _regime_block_reason
                payload["source_context_ok"] = False
                payload["blocked_action"] = old_act
                payload["blocked_action_category"] = "OPEN_RISK"
                payload["action"] = hold_act
                payload["action_name"] = hold_act
                payload["action_category"] = "PROTECTIVE"
                payload["category"] = "PROTECTIVE"
                payload["confidence"] = 0.01
                payload["model_confidence"] = 0.01
                logger.warning(
                    "[SOURCE_REGIME_GATE] blocked_open_risk symbol=%s action=%s reason=%s",
                    str(payload.get("symbol") or "").upper(), old_act, _regime_block_reason,
                )
                try:
                    self._publish_exec_event(
                        code="REGIME_STALE_BLOCK_AT_SOURCE",
                        account_id=str(payload.get("account_id") or "primary"),
                        symbol=str(payload.get("symbol") or "").upper(),
                        action=old_act,
                        meta={"source_module": source_u, "reason": _regime_block_reason},
                    )
                except Exception:
                    pass

        try:
            from rl.proposal_schema import TradeProposal, emit_proposal_to_stream

            # Enrich proposal with market timestamps if missing
            try:
                sym = str(payload.get("symbol") or "").strip().upper()
            except Exception:
                sym = ""
            try:
                meta = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
            except Exception:
                meta = {}
            if not payload.get("signal_id"):
                try:
                    sid = meta.get("signal_id") or meta.get("id") or meta.get("_proposal_id")
                except Exception:
                    sid = None
                if not sid:
                    try:
                        sid = payload.get("proposal_id")
                    except Exception:
                        sid = None
                if sid:
                    payload["signal_id"] = str(sid)
            if not payload.get("timeframe"):
                try:
                    tf = meta.get("timeframe") or meta.get("tf") or meta.get("interval")
                except Exception:
                    tf = None
                if tf:
                    payload["timeframe"] = str(tf)
            if sym:
                try:
                    ob_ts = int(payload.get("orderbook_ts_ms") or 0)
                except Exception:
                    ob_ts = 0
                ob_source_key = None
                if not ob_ts:
                    ob_ts = 0
                    try:
                        msnap = redis_client.hgetall(f"msnap:coinapi_wsds:{sym}") or {}
                        if msnap:
                            if isinstance(next(iter(msnap.keys())), (bytes, bytearray)):
                                msnap = {
                                    (k.decode("utf-8", errors="ignore") if isinstance(k, (bytes, bytearray)) else str(k)): (
                                        v.decode("utf-8", errors="ignore") if isinstance(v, (bytes, bytearray)) else v
                                    )
                                    for k, v in (msnap or {}).items()
                                }
                            ob_ts = int(float(msnap.get("updated_ts_ms", 0) or 0))
                            if ob_ts:
                                ob_source_key = f"msnap:coinapi_wsds:{sym}"
                    except Exception:
                        ob_ts = ob_ts or 0
                    if not ob_ts:
                        try:
                            ob_raw = redis_client.get(f"orderbook:top:{sym}")
                            if ob_raw:
                                if isinstance(ob_raw, (bytes, bytearray)):
                                    ob_raw = ob_raw.decode("utf-8", errors="ignore")
                                ob = json.loads(ob_raw) if isinstance(ob_raw, str) else ob_raw
                                if isinstance(ob, dict):
                                    ob_ts = int(
                                        ob.get("updated_ts_ms")
                                        or ob.get("ts_ms")
                                        or ob.get("timestamp")
                                        or ob.get("ts")
                                        or 0
                                    )
                                    if ob_ts:
                                        ob_source_key = f"orderbook:top:{sym}"
                        except Exception:
                            ob_ts = ob_ts or 0
                if ob_ts:
                    payload["orderbook_ts_ms"] = int(ob_ts)
                if ob_source_key:
                    payload["dq_ob_source_key"] = ob_source_key

                try:
                    lm_ts = int(payload.get("liqmap_ts_ms") or 0)
                except Exception:
                    lm_ts = 0
                liq_source_key = None
                if not lm_ts:
                    lm_ts = 0
                    try:
                        try:
                            tfs = list(getattr(config, "TIMEFRAMES", []) or [])
                        except Exception:
                            tfs = []
                        if not tfs:
                            tfs = ["5m", "15m", "1h", "4h"]
                        for tf in tfs:
                            try:
                                ts_raw = redis_client.hget(f"unified_features:{sym}:{tf}", "liquidation_updated_ts")
                                if ts_raw:
                                    if isinstance(ts_raw, (bytes, bytearray)):
                                        ts_raw = ts_raw.decode("utf-8", errors="ignore")
                                    ts_val = int(float(ts_raw) or 0)
                                    if ts_val > lm_ts:
                                        lm_ts = ts_val
                                        liq_source_key = f"unified_features:{sym}:{tf}"
                            except Exception:
                                continue
                    except Exception:
                        lm_ts = lm_ts or 0
                if lm_ts:
                    payload["liqmap_ts_ms"] = int(lm_ts)
                if liq_source_key:
                    payload["dq_liqmap_source_key"] = liq_source_key

                # DQ watchdog (rate-limited)
                try:
                    from config import (
                        DQ_WATCHDOG_ENABLED,
                        DQ_WATCHDOG_LOG_INTERVAL_SEC,
                        DQ_WATCHDOG_OB_STALE_MAJOR_MS,
                        DQ_WATCHDOG_OB_STALE_ALT_MS,
                        DQ_WATCHDOG_LIQMAP_STALE_MS,
                        DQ_WATCHDOG_LIQ_UPDATED_STALE_MS,
                    )
                except Exception:
                    DQ_WATCHDOG_ENABLED = False
                    DQ_WATCHDOG_LOG_INTERVAL_SEC = 60
                    DQ_WATCHDOG_OB_STALE_MAJOR_MS = 8000
                    DQ_WATCHDOG_OB_STALE_ALT_MS = 15000
                    DQ_WATCHDOG_LIQMAP_STALE_MS = 60000
                    DQ_WATCHDOG_LIQ_UPDATED_STALE_MS = 120000

                now_ms = int(time.time() * 1000)
                ob_age_ms = int(now_ms - ob_ts) if ob_ts else None
                liqmap_age_ms = int(now_ms - lm_ts) if lm_ts else None
                liq_updated_age_ms = liqmap_age_ms

                payload["dq_ob_age_ms"] = ob_age_ms
                payload["dq_liqmap_age_ms"] = liqmap_age_ms
                payload["dq_liq_updated_age_ms"] = liq_updated_age_ms

                if DQ_WATCHDOG_ENABLED:
                    majors = {"BTCUSDT", "ETHUSDT", "SOLUSDT", "XRPUSDT"}
                    ob_stale_limit = int(DQ_WATCHDOG_OB_STALE_MAJOR_MS if sym in majors else DQ_WATCHDOG_OB_STALE_ALT_MS)
                    ob_stale = ob_age_ms is None or ob_age_ms > ob_stale_limit
                    liqmap_stale = liqmap_age_ms is None or liqmap_age_ms > int(DQ_WATCHDOG_LIQMAP_STALE_MS)
                    liq_updated_stale = liq_updated_age_ms is None or liq_updated_age_ms > int(DQ_WATCHDOG_LIQ_UPDATED_STALE_MS)
                    if ob_stale or liqmap_stale or liq_updated_stale:
                        try:
                            if not hasattr(self, "_dq_watchdog_last_ts"):
                                self._dq_watchdog_last_ts = {}
                            last = float(self._dq_watchdog_last_ts.get(sym, 0.0) or 0.0)
                            if (time.time() - last) >= float(DQ_WATCHDOG_LOG_INTERVAL_SEC):
                                self._dq_watchdog_last_ts[sym] = time.time()
                                reasons = []
                                if ob_stale:
                                    reasons.append("STALE_OB")
                                if liqmap_stale:
                                    reasons.append("STALE_LIQMAP")
                                if liq_updated_stale:
                                    reasons.append("STALE_LIQ_UPDATED")
                                logger.warning(
                                    "[DQ_WATCHDOG] sym=%s ob_age_ms=%s liqmap_age_ms=%s liq_age_ms=%s action=SOFT_BLOCK reason=%s",
                                    sym,
                                    ob_age_ms,
                                    liqmap_age_ms,
                                    liq_updated_age_ms,
                                    ",".join(reasons) if reasons else "OK",
                                )
                        except Exception:
                            pass
            
            # Build proposal from legacy payload
            proposal = TradeProposal.from_legacy_payload(payload)

            # Finalize timestamps on proposal if still missing
            try:
                sym = str(proposal.symbol or "").strip().upper()
            except Exception:
                sym = ""
            if sym:
                try:
                    ob_ts = int(getattr(proposal, "orderbook_ts_ms", 0) or 0)
                except Exception:
                    ob_ts = 0
                if not ob_ts:
                    ob_ts = 0
                    try:
                        msnap = redis_client.hgetall(f"msnap:coinapi_wsds:{sym}") or {}
                        if msnap:
                            if isinstance(next(iter(msnap.keys())), (bytes, bytearray)):
                                msnap = {
                                    (k.decode("utf-8", errors="ignore") if isinstance(k, (bytes, bytearray)) else str(k)): (
                                        v.decode("utf-8", errors="ignore") if isinstance(v, (bytes, bytearray)) else v
                                    )
                                    for k, v in (msnap or {}).items()
                                }
                            ob_ts = int(float(msnap.get("updated_ts_ms", 0) or 0))
                    except Exception:
                        ob_ts = ob_ts or 0
                    if not ob_ts:
                        try:
                            ob_raw = redis_client.get(f"orderbook:top:{sym}")
                            if ob_raw:
                                if isinstance(ob_raw, (bytes, bytearray)):
                                    ob_raw = ob_raw.decode("utf-8", errors="ignore")
                                ob = json.loads(ob_raw) if isinstance(ob_raw, str) else ob_raw
                                if isinstance(ob, dict):
                                    ob_ts = int(
                                        ob.get("updated_ts_ms")
                                        or ob.get("ts_ms")
                                        or ob.get("timestamp")
                                        or ob.get("ts")
                                        or 0
                                    )
                        except Exception:
                            ob_ts = ob_ts or 0
                if ob_ts:
                    proposal.orderbook_ts_ms = int(ob_ts)

                try:
                    lm_ts = int(getattr(proposal, "liqmap_ts_ms", 0) or 0)
                except Exception:
                    lm_ts = 0
                if not lm_ts:
                    lm_ts = 0
                    try:
                        try:
                            tfs = list(getattr(config, "TIMEFRAMES", []) or [])
                        except Exception:
                            tfs = []
                        if not tfs:
                            tfs = ["5m", "15m", "1h", "4h"]
                        for tf in tfs:
                            try:
                                ts_raw = redis_client.hget(f"unified_features:{sym}:{tf}", "liquidation_updated_ts")
                                if ts_raw:
                                    if isinstance(ts_raw, (bytes, bytearray)):
                                        ts_raw = ts_raw.decode("utf-8", errors="ignore")
                                    ts_val = int(float(ts_raw) or 0)
                                    if ts_val > lm_ts:
                                        lm_ts = ts_val
                            except Exception:
                                continue
                    except Exception:
                        lm_ts = lm_ts or 0
                if lm_ts:
                    proposal.liqmap_ts_ms = int(lm_ts)
            
            # Override/set source and priority
            proposal.source_module = source_module
            proposal.priority = priority
            if category:
                proposal.category = category

            # Enrich with trainer alignment context before emission
            try:
                from risk.trainer_alignment import enrich_proposal_with_trainer, check_alignment
                _p_dict = proposal.to_dict() if hasattr(proposal, "to_dict") else {}
                enrich_proposal_with_trainer(redis_client, _p_dict)
                if hasattr(proposal, "metadata") and isinstance(proposal.metadata, dict):
                    for _tk, _tv in _p_dict.items():
                        if str(_tk).startswith("trainer_"):
                            proposal.metadata[_tk] = _tv
                elif hasattr(proposal, "metadata"):
                    proposal.metadata = {k: v for k, v in _p_dict.items() if str(k).startswith("trainer_")}
            except Exception:
                pass

            # ── TA DIRECTION ORACLE GATE (blocks counter-trend OPEN_RISK) ──
            # Kill switch: TA_ORACLE_GATE_ENABLED in config.py (default True)
            try:
                _ta_gate_enabled = bool(getattr(config, "TA_ORACLE_GATE_ENABLED", True))
            except Exception:
                _ta_gate_enabled = True
            _proposal_act = str(getattr(proposal, "action", "") or getattr(proposal, "action_name", "") or "").upper().strip()
            _proposal_cat = str(getattr(proposal, "action_category", "") or getattr(proposal, "category", "") or "").upper().strip()
            _proposal_is_open_risk = _proposal_cat == "OPEN_RISK" or any(
                tok in _proposal_act for tok in ("OPEN_LONG", "OPEN_SHORT", "FLIP", "INCREASE", "CLOSE_AND")
            )
            if _ta_gate_enabled and _proposal_is_open_risk:
                try:
                    from rl.ta_direction_oracle import get_ta_direction_cached, gate_action_against_ta
                    _ta_sym = str(getattr(proposal, "symbol", "") or "").upper().strip()
                    _ta_min_str = float(getattr(config, "TA_ORACLE_MIN_STRENGTH", 0.25))
                    _ta_result = get_ta_direction_cached(redis_client, _ta_sym)
                    _ta_gate = gate_action_against_ta(
                        _proposal_act, _ta_result,
                        confidence=float(getattr(proposal, "confidence", 0.5) or 0.5),
                        min_strength_to_gate=_ta_min_str,
                    )
                    # Attach TA context to proposal metadata for downstream observability
                    if hasattr(proposal, "metadata") and isinstance(proposal.metadata, dict):
                        proposal.metadata["ta_direction"] = _ta_result.get("direction", 0)
                        proposal.metadata["ta_strength"] = _ta_result.get("strength", 0.0)
                        proposal.metadata["ta_htf_bias"] = _ta_result.get("htf_bias", 0)
                        proposal.metadata["ta_gate_reason"] = _ta_gate.get("reason", "")
                        proposal.metadata["ta_gate_allowed"] = _ta_gate.get("allowed", True)
                    
                    if not _ta_gate["allowed"]:
                        # BLOCK: Counter-trend trade against strong TA signal
                        logger.warning(
                            "[TA_ORACLE_BLOCK] symbol=%s action=%s ta_dir=%s ta_str=%.3f htf=%s reason=%s",
                            _ta_sym, _proposal_act,
                            _ta_result.get("direction"), _ta_result.get("strength", 0),
                            _ta_result.get("htf_bias"), _ta_gate.get("reason"),
                        )
                        # Convert to HOLD instead of emitting counter-trend trade
                        proposal.action = "HOLD"
                        if hasattr(proposal, "action_name"):
                            proposal.action_name = "HOLD"
                        if hasattr(proposal, "action_category"):
                            proposal.action_category = "PROTECTIVE"
                        if hasattr(proposal, "category"):
                            proposal.category = "PROTECTIVE"
                        proposal.confidence = 0.01
                        if hasattr(proposal, "model_confidence"):
                            proposal.model_confidence = 0.01
                        try:
                            self._publish_exec_event(
                                code="TA_ORACLE_COUNTER_TREND_BLOCK",
                                account_id=str(getattr(proposal, "account_id", "primary") or "primary"),
                                symbol=_ta_sym,
                                action=_proposal_act,
                                meta={
                                    "ta_direction": _ta_result.get("direction", 0),
                                    "ta_strength": _ta_result.get("strength", 0),
                                    "ta_htf_bias": _ta_result.get("htf_bias", 0),
                                    "ta_details": str(_ta_result.get("per_tf", {}))[:500],
                                    "source_module": str(source_module),
                                    "gate_reason": _ta_gate.get("reason", ""),
                                },
                            )
                        except Exception:
                            pass
                    else:
                        # Allowed — apply confidence adjustment from TA alignment
                        _adj_conf = _ta_gate.get("adjusted_confidence", float(getattr(proposal, "confidence", 0.5) or 0.5))
                        proposal.confidence = _adj_conf
                        if hasattr(proposal, "model_confidence"):
                            proposal.model_confidence = _adj_conf
                        if _ta_gate.get("reason") == "TA_ALIGNED":
                            logger.info(
                                "[TA_ORACLE_ALIGNED] symbol=%s action=%s ta_dir=%s str=%.3f conf=%.3f→%.3f",
                                _ta_sym, _proposal_act, _ta_result.get("direction"),
                                _ta_result.get("strength", 0),
                                float(getattr(proposal, "confidence", 0) or 0), _adj_conf,
                            )
                except Exception as _ta_exc:
                    logger.debug(f"[TA_ORACLE] Gate check failed (allowing trade): {_ta_exc}")

            # Emit to proposal stream
            stream = ORCHESTRATOR_UNIFIED_PROPOSAL_STREAM or "wma:proposals"
            success = emit_proposal_to_stream(redis_client, proposal, stream=stream)
            
            if success:
                logger.info(
                    f"📤 [PROPOSAL] {proposal.account_id}:{proposal.symbol} {proposal.action} "
                    f"src={source_module} pri={priority} → {stream}"
                )
            else:
                logger.error(
                    f"❌ [PROPOSAL] Failed to emit: {proposal.account_id}:{proposal.symbol} "
                    f"{proposal.action} src={source_module}"
                )
            
            # NO FALLBACK - return result directly
            return success
            
        except Exception as e:
            logger.error(f"[EMIT_PROPOSAL] Error emitting proposal: {e}")
            # NO FALLBACK - return False
            return False

    def _publish_skip_event(self, payload: dict, reason_code: str, reason_detail: str):
        """Delegate to ppo_model's _publish_skip_event method."""
        if hasattr(self, 'ppo_model') and self.ppo_model is not None:
            return self.ppo_model._publish_skip_event(payload, reason_code, reason_detail)
        else:
            logger.debug(f"[SKIP_EVENT] Cannot publish - ppo_model not initialized: {reason_code}")

    def _publish_exec_event(
        self,
        *,
        code: str,
        account_id: str,
        symbol: str,
        action: str,
        meta: Optional[Dict[str, Any]] = None,
    ) -> None:
        rc = getattr(self, "_signal_redis", None) or getattr(self, "redis", None)
        if rc is None:
            return
        payload = {
            "layer": "TRAINER",
            "code": str(code or ""),
            "reason": str(code or ""),
            "account": str(account_id or ""),
            "symbol": str(symbol or ""),
            "action": str(action or ""),
            "ts_ms": int(time.time() * 1000),
        }
        if meta:
            try:
                payload["meta"] = json.dumps(meta, separators=(",", ":"))
            except Exception:
                payload["meta"] = str(meta)
        try:
            rc.xadd(
                "wma:exec_events",
                {"data": json.dumps(payload, separators=(",", ":"))},
                maxlen=int(self._exec_event_maxlen),
                approximate=True,
            )
        except Exception:
            pass

    def _maybe_emit_canary(self, *, published_count: int, cycle_count: int) -> None:
        try:
            from config import ENABLE_CANARY_SIGNALS, CANARY_INTERVAL_SEC, CANARY_ZERO_PUBLISH_CYCLES, TRADING_ACCOUNTS
        except Exception:
            ENABLE_CANARY_SIGNALS = False
            CANARY_INTERVAL_SEC = 120
            CANARY_ZERO_PUBLISH_CYCLES = 5
            TRADING_ACCOUNTS = ["primary"]

        if not ENABLE_CANARY_SIGNALS:
            return

        now = int(time.time())
        with self._canary_lock:
            if int(published_count or 0) <= 0:
                self._canary_zero_publish_cycles += 1
            else:
                self._canary_zero_publish_cycles = 0

            interval_due = bool(now - int(self._canary_last_emit_ts) >= int(CANARY_INTERVAL_SEC))
            zero_due = bool(self._canary_zero_publish_cycles >= int(CANARY_ZERO_PUBLISH_CYCLES))
            if not (interval_due or zero_due):
                return

            self._canary_last_emit_ts = now
            self._canary_zero_publish_cycles = 0

        accounts = TRADING_ACCOUNTS or ["primary"]
        for acct in accounts:
            payload = {
                "account_id": str(acct),
                "symbol": "BTCUSDT",
                "timeframe": "canary",
                "action": "CANARY",
                "action_name": "CANARY",
                "action_category": "SYSTEM",
                "category": "SYSTEM_CANARY",
                "risk_delta": 0.0,
                "margin_usd": 0.0,
                "notional_usd": 0.0,
                "leverage": 0.0,
                "confidence": 1.0,
                "trace_id": f"canary_{int(time.time() * 1000)}_{cycle_count}",
                "source": "trainer_canary",
                "producer": "trainer",
                "canary": True,
            }
            try:
                emitted = self._emit_proposal(
                    payload,
                    source_module="trainer_canary",
                    priority=0,
                    category="SYSTEM_CANARY",
                )
                if emitted:
                    logger.info(f"📡 [CANARY] Emitted proposal for account={acct}")
            except Exception:
                pass

    def _classify_action_type(self, action) -> str:
        """Delegate to ppo_model's action classifier or use fallback."""
        if hasattr(self, 'ppo_model') and self.ppo_model is not None:
            return self.ppo_model._classify_action_type(action)
        # Fallback classifier
        a = str(action or "").upper()
        if "CLOSE_AND_" in a:
            return "flip"
        # DECREASE/PARTIAL_CLOSE are position-reducing but NOT entry (don't require sizing)
        if any(tok in a for tok in ["DECREASE", "PARTIAL_CLOSE"]):
            return "decrease"
        if any(tok in a for tok in ["CLOSE", "REDUCE", "EXIT", "TAKE_PROFIT", "STOP_LOSS"]):
            return "close"
        if a in {"HOLD", "NONE", "WAIT"}:
            return "hold"
        # INCREASE requires sizing like OPEN
        if "INCREASE" in a:
            return "increase"
        return "open"

    # ── P2: Unified MIN_CONF accessors for HybridTrainer (Apr 2026 fix) ──
    # Delegate to GPUForcedPPO instance if available, else standalone fallback.
    # NOTE: No caching — always reads fresh from config to avoid stale checkpoint values.

    def _get_min_conf_entry(self) -> float:
        """Return MIN_CONF_ENTRY as a float. Delegates to ppo_model or standalone fallback."""
        if hasattr(self, 'ppo_model') and self.ppo_model is not None and hasattr(self.ppo_model, '_get_min_conf_entry'):
            return self.ppo_model._get_min_conf_entry()
        # Standalone fallback — always read fresh from config module
        try:
            import config as _cfg_mod
            val = float(getattr(_cfg_mod, "MIN_CONF_ENTRY", 0))
            if val > 0:
                return val
        except Exception:
            pass
        try:
            val = float(getattr(self.main_config, "MIN_CONF_ENTRY", 0))
            if val > 0:
                return val
        except Exception:
            pass
        try:
            from config import MIN_TRADING_CONFIDENCE
            val = float(MIN_TRADING_CONFIDENCE)
            if val > 0:
                return val
        except Exception:
            pass
        return 0.85

    def _get_min_conf_exit(self) -> float:
        """Return MIN_CONF_EXIT as a float. Delegates to ppo_model or standalone fallback."""
        if hasattr(self, 'ppo_model') and self.ppo_model is not None and hasattr(self.ppo_model, '_get_min_conf_exit'):
            return self.ppo_model._get_min_conf_exit()
        try:
            return float(getattr(self.main_config, "MIN_CONF_EXIT", 0.40))
        except Exception:
            return 0.40

    def _get_position_pnl_pct(self, position: dict) -> float:
        """
        Safely extract PnL percentage from position data.
        
        IMPORTANT: Position data may have different field names:
        - 'pnl_pct': Used by trader/Redis position storage
        - 'pnl_percentage': Legacy field (often None)
        - Can also compute from unrealized_pnl/margin
        
        Returns: PnL as percentage (e.g., -1.73 for -1.73% loss)
        """
        if not position:
            return 0.0
        
        # Try pnl_pct first (trader/Redis standard)
        pnl_pct = position.get('pnl_pct')
        if pnl_pct is not None:
            try:
                return float(pnl_pct)
            except (ValueError, TypeError):
                pass
        
        # Try pnl_percentage (legacy field)
        pnl_percentage = position.get('pnl_percentage')
        if pnl_percentage is not None:
            try:
                return float(pnl_percentage)
            except (ValueError, TypeError):
                pass
        
        # Compute from unrealized_pnl and entry/size
        try:
            unrealized_pnl = float(position.get('unrealized_pnl', 0) or 0)
            entry_price = float(position.get('entry_price', 0) or 0)
            size = float(position.get('size', 0) or 0)
            leverage = float(position.get('leverage', 1) or 1)
            
            if entry_price > 0 and size > 0:
                notional = entry_price * size
                margin = notional / leverage if leverage > 0 else notional
                if margin > 0:
                    # This gives ROI on margin (what traders care about)
                    return (unrealized_pnl / margin) * 100.0
        except (ValueError, TypeError):
            pass
        
        return 0.0

    def _build_tf_stack(self, symbol: str, tf: str, action: str, confidence: float) -> None:
        """
        Phase 1: Build multi-timeframe hierarchy stack per symbol.
        
        Populates self._tf_stack[symbol] with timeframe-specific decisions:
        - 4h: Bias only (LONG_ONLY/SHORT_ONLY/NEUTRAL)
        - 1h: Confirmation (LONG/SHORT/NEUTRAL + confidence)
        - 15m: Trigger (action intent + confidence)
        - 5m: Execution gate (PASS/DELAY/SIZE_REDUCE + reasons)
        - 1m: Protective adjustments only
        
        Args:
            symbol: Trading symbol (e.g., BTCUSDT)
            tf: Timeframe (e.g., 4h, 1h, 15m, 5m, 1m)
            action: Action name from model
            confidence: Model confidence score
        """
        from config import TF_HIERARCHY_ENABLED, TF_BIAS_TF, TF_CONFIRM_TF, TF_TRIGGER_TF, TF_EXEC_TF, TF_PROTECT_TF
        
        if not TF_HIERARCHY_ENABLED:
            return  # Skip if hierarchy disabled
        
        with self._tf_stack_lock:
            if symbol not in self._tf_stack:
                self._tf_stack[symbol] = {
                    'bias': None,
                    'confirm': None,
                    'trigger': None,
                    'exec_gate': None,
                    'protective': None
                }
            
            # Determine direction from action
            action_upper = str(action).upper()
            direction = None
            if 'LONG' in action_upper:
                direction = 'LONG'
            elif 'SHORT' in action_upper:
                direction = 'SHORT'
            elif 'HOLD' in action_upper or 'NONE' in action_upper:
                direction = 'NEUTRAL'
            
            # Route to appropriate layer based on timeframe
            if tf == TF_BIAS_TF:  # 4h
                # Bias layer: only provides direction guidance, not executable
                bias_direction = 'NEUTRAL'
                if direction == 'LONG':
                    bias_direction = 'LONG_ONLY'
                elif direction == 'SHORT':
                    bias_direction = 'SHORT_ONLY'
                
                self._tf_stack[symbol]['bias'] = {
                    'direction': bias_direction,
                    'confidence': confidence,
                    'tf': tf,
                    'timestamp': time.time()
                }
            
            elif tf == TF_CONFIRM_TF:  # 1h
                # Confirmation layer: validates/invalidates bias
                self._tf_stack[symbol]['confirm'] = {
                    'direction': direction or 'NEUTRAL',
                    'confidence': confidence,
                    'tf': tf,
                    'timestamp': time.time()
                }
            
            elif tf == TF_TRIGGER_TF:  # 15m
                # Trigger layer: generates entry/exit intent
                self._tf_stack[symbol]['trigger'] = {
                    'action': action,
                    'confidence': confidence,
                    'direction': direction,
                    'tf': tf,
                    'timestamp': time.time()
                }
            
            elif tf == TF_EXEC_TF:  # 5m
                # 2026-04-02: 5m can now BOTH gate AND generate signals
                # Check TF_ALL_GENERATE_SIGNALS config
                try:
                    from config import TF_ALL_GENERATE_SIGNALS, TF_SIGNAL_GENERATOR_TFS
                    if TF_ALL_GENERATE_SIGNALS and tf in TF_SIGNAL_GENERATOR_TFS:
                        # 5m can generate trigger signals like 15m
                        self._tf_stack[symbol]['trigger_5m'] = {
                            'action': action,
                            'confidence': confidence,
                            'direction': direction,
                            'tf': tf,
                            'timestamp': time.time()
                        }
                except Exception:
                    pass
                # Also keep execution gate role
                self._tf_stack[symbol]['exec_gate'] = {
                    'decision': 'PASS',  # Will be updated by microstructure checks
                    'reasons': [],
                    'tf': tf,
                    'timestamp': time.time()
                }
            
            elif tf == TF_PROTECT_TF:  # 1m
                # Protective layer: stop adjustments only (no entries)
                if action_upper in ['CLOSE_LONG', 'CLOSE_SHORT', 'DECREASE_LONG', 'DECREASE_SHORT', 'STOP_LOSS']:
                    if self._tf_stack[symbol]['protective'] is None:
                        self._tf_stack[symbol]['protective'] = {'adjustments': []}
                    
                    self._tf_stack[symbol]['protective']['adjustments'].append({
                        'action': action,
                        'confidence': confidence,
                        'timestamp': time.time()
                    })
                    self._tf_stack[symbol]['protective']['tf'] = tf

    def _log_tf_stack(self, symbol: str) -> None:
        """
        Phase 1B: Emit deterministic TF logs for grep-able validation.
        
        Logs the complete timeframe hierarchy stack for a symbol including:
        - TF_BIAS: 4h bias direction
        - TF_CONFIRM: 1h confirmation
        - TF_TRIGGER: 15m trigger action
        - TF_EXEC_GATE: 5m execution gate decision
        - TF_STACK: Complete summary
        
        Args:
            symbol: Trading symbol to log
        """
        from config import TF_HIERARCHY_ENABLED
        
        if not TF_HIERARCHY_ENABLED:
            return
        
        with self._tf_stack_lock:
            if symbol not in self._tf_stack:
                return
            
            stack = self._tf_stack[symbol]
            
            # Log individual layers
            if stack['bias']:
                self._log_contract(
                    'TF_BIAS',
                    symbol=symbol,
                    bias=stack['bias']['direction'],
                    conf=f"{stack['bias']['confidence']:.3f}",
                    tf=stack['bias']['tf']
                )
            
            if stack['confirm']:
                self._log_contract(
                    'TF_CONFIRM',
                    symbol=symbol,
                    direction=stack['confirm']['direction'],
                    conf=f"{stack['confirm']['confidence']:.3f}",
                    tf=stack['confirm']['tf']
                )
            
            if stack['trigger']:
                self._log_contract(
                    'TF_TRIGGER',
                    symbol=symbol,
                    action=stack['trigger']['action'],
                    conf=f"{stack['trigger']['confidence']:.3f}",
                    tf=stack['trigger']['tf']
                )
            
            if stack['exec_gate']:
                reasons_str = ','.join(stack['exec_gate']['reasons']) if stack['exec_gate']['reasons'] else 'none'
                self._log_contract(
                    'TF_EXEC_GATE',
                    symbol=symbol,
                    decision=stack['exec_gate']['decision'],
                    reasons=reasons_str,
                    tf=stack['exec_gate']['tf']
                )
            
            # Log complete stack summary
            bias_dir = stack['bias']['direction'] if stack['bias'] else 'UNKNOWN'
            confirm_dir = stack['confirm']['direction'] if stack['confirm'] else 'UNKNOWN'
            trigger_action = stack['trigger']['action'] if stack['trigger'] else 'UNKNOWN'
            exec_decision = stack['exec_gate']['decision'] if stack['exec_gate'] else 'UNKNOWN'
            
            self._log_contract(
                'TF_STACK',
                symbol=symbol,
                bias=bias_dir,
                confirm=confirm_dir,
                trigger=trigger_action,
                exec=exec_decision
            )
    
    def _is_stack_aligned(self, symbol: str, action: str = None) -> Tuple[bool, str]:
        """
        Phase 2A: Check if multi-timeframe stack is aligned for symbol.
        
        Aligned stack means:
        - 4h bias is not NEUTRAL
        - 1h confirmation matches bias direction
        - 15m trigger matches bias direction
        - 5m execution gate is PASS (not DELAY/SIZE_REDUCE)
        
        Returns:
            (is_aligned, reason_string)
            
        Examples:
            (True, "4h_LONG_ONLY+1h_LONG+15m_OPEN_LONG+5m_PASS")
            (False, "4h_NEUTRAL")
            (False, "1h_SHORT_mismatch_4h_LONG_ONLY")
        """
        from config import TF_HIERARCHY_ENABLED
        
        if not TF_HIERARCHY_ENABLED:
            return True, "hierarchy_disabled"
        
        with self._tf_stack_lock:
            if symbol not in self._tf_stack:
                return False, "no_stack_data"
            
            stack = self._tf_stack[symbol]
            
            # Check 4h bias exists and is directional
            if not stack['bias']:
                return False, "no_bias"
            
            bias_dir = stack['bias']['direction']
            if bias_dir == 'NEUTRAL':
                return False, "4h_NEUTRAL"
            
            # Extract expected direction from bias
            # LONG_ONLY -> expect LONG, SHORT_ONLY -> expect SHORT
            expected_dir = bias_dir.replace('_ONLY', '')  # LONG_ONLY -> LONG
            
            # Check 1h confirmation
            if not stack['confirm']:
                return False, "no_confirm"
            
            confirm_dir = stack['confirm']['direction']
            if confirm_dir != expected_dir:
                return False, f"1h_{confirm_dir}_mismatch_4h_{bias_dir}"
            
            # Check 15m trigger
            if not stack['trigger']:
                return False, "no_trigger"
            
            trigger_action = stack['trigger']['action']
            trigger_dir = stack['trigger'].get('direction', 'NEUTRAL')
            if trigger_dir != expected_dir:
                return False, f"15m_{trigger_dir}_mismatch_4h_{bias_dir}"
            
            # Check 5m execution gate
            if not stack['exec_gate']:
                return False, "no_exec_gate"
            
            exec_decision = stack['exec_gate']['decision']
            if exec_decision not in ('PASS', 'SIZE_REDUCE'):
                return False, f"5m_{exec_decision}"
            
            # All layers aligned
            alignment_signature = f"4h_{bias_dir}+1h_{confirm_dir}+15m_{trigger_action}+5m_{exec_decision}"
            return True, alignment_signature

    def _get_market_context(self, symbol: str) -> dict:
        """Collect multi-source market context for adaptive confidence and 5m execution gating."""
        ctx = {
            'source_count': 0,
            'spread_pct': 0.0,
            'spoof_score': 0.0,
            'fast_move_score': 0.0,
            'churn_score': 0.0,
            'quality_score': 0.0,
            'false_move_score': 0.0,
            'imbalance': 0.0,
            'ret_5m': 0.0,
            'ret_15m': 0.0,
            'ret_1h': 0.0,
            'funding_rate': 0.0,
            'basis_pct': 0.0,
            'liq_long': 0.0,
            'liq_short': 0.0,
            'source': 'none',
        }

        redis_client = getattr(self, 'redis', None) or getattr(self, '_signal_redis', None)
        if not redis_client or not symbol:
            return ctx

        def _decode_hash(raw):
            out = {}
            try:
                for k, v in (raw or {}).items():
                    ks = k.decode('utf-8') if isinstance(k, (bytes, bytearray)) else str(k)
                    vs = v.decode('utf-8') if isinstance(v, (bytes, bytearray)) else v
                    out[ks] = vs
            except Exception:
                return {}
            return out

        def _f(mapping, *keys, default=0.0):
            for key in keys:
                try:
                    if key in mapping and mapping.get(key) not in (None, ''):
                        return float(mapping.get(key))
                except Exception:
                    continue
            return float(default)

        try:
            from rl.microstructure_source_router import get_source_router
            snap = get_source_router(redis_client).get_snapshot_or_default(symbol)
            if snap:
                ctx['source'] = str(getattr(snap, 'source', 'none') or 'none')
                ctx['spread_pct'] = float(getattr(snap, 'spread', 0.0) or 0.0) / 10000.0
                ctx['spoof_score'] = max(ctx['spoof_score'], float(getattr(snap, 'spoof_score', 0.0) or 0.0))
                ctx['fast_move_score'] = max(
                    ctx['fast_move_score'],
                    float(getattr(snap, 'fast_move_score', 0.0) or 0.0),
                    float(getattr(snap, 'fast_move_max_5m', 0.0) or 0.0),
                )
                ctx['churn_score'] = max(ctx['churn_score'], float(getattr(snap, 'churn_score', 0.0) or 0.0))
                ctx['quality_score'] = max(ctx['quality_score'], float(getattr(snap, 'src_quality_score', 0.0) or 0.0))
                ctx['false_move_score'] = max(ctx['false_move_score'], float(getattr(snap, 'p_false_move', 0.0) or 0.0))
                ctx['imbalance'] = float(getattr(snap, 'imbalance_5', 0.0) or 0.0)
                if getattr(snap, 'source', None) and getattr(snap, 'source', None) != 'none':
                    ctx['source_count'] += 1
        except Exception:
            pass

        for tf in ('5m', '15m', '1h'):
            try:
                feat = _decode_hash(redis_client.hgetall(f'unified_features:{symbol}:{tf}'))
            except Exception:
                feat = {}
            if not feat:
                continue
            ctx['source_count'] += 1
            ctx['spoof_score'] = max(ctx['spoof_score'], _f(feat, 'depth_spoof_score', 'micro_spoof_score', 'spoof_score'))
            ctx['fast_move_score'] = max(ctx['fast_move_score'], _f(feat, 'depth_fast_move_score', 'micro_fast_move_score', 'fast_move_score', 'fast_move_max_5m'))
            ctx['churn_score'] = max(ctx['churn_score'], _f(feat, 'depth_churn_score', 'micro_churn_score', 'churn_score'))
            ctx['quality_score'] = max(ctx['quality_score'], _f(feat, 'depth_quality_score', 'micro_quality_score', 'src_quality_score'))
            ctx['false_move_score'] = max(ctx['false_move_score'], _f(feat, 'p_false_move', 'micro_p_false_move'))
            ctx['spread_pct'] = max(
                ctx['spread_pct'],
                _f(feat, 'spread_pct', 'micro_spread', 'ob_spread', default=0.0),
                _f(feat, 'spread_bps', default=0.0) / 10000.0,
            )
            if tf == '5m':
                ctx['ret_5m'] = _f(feat, 'ret_5m', 'return_5m', default=ctx['ret_5m'])
                ctx['funding_rate'] = _f(feat, 'funding_rate', default=ctx['funding_rate'])
                ctx['basis_pct'] = _f(feat, 'basis_pct', default=ctx['basis_pct'])
            elif tf == '15m':
                ctx['ret_15m'] = _f(feat, 'ret_15m', 'return_15m', default=ctx['ret_15m'])
            elif tf == '1h':
                ctx['ret_1h'] = _f(feat, 'ret_1h', 'return_1h', default=ctx['ret_1h'])
            ctx['liq_long'] = max(ctx['liq_long'], _f(feat, 'liquidation_long_strength', 'liquidation_long_usd', default=0.0))
            ctx['liq_short'] = max(ctx['liq_short'], _f(feat, 'liquidation_short_strength', 'liquidation_short_usd', default=0.0))
            imb_val = _f(feat, 'depth_imbalance_5', 'micro_imbalance_5', 'ob_imbalance', default=ctx['imbalance'])
            if abs(imb_val) > abs(ctx['imbalance']):
                ctx['imbalance'] = imb_val

        return ctx

    def _compute_contextual_conf_threshold(self, symbol: str, action_name: str, is_aligned: bool, alignment_reason: str) -> Tuple[float, dict]:
        import config

        base_threshold = float(
            getattr(config, 'TF_ENTRY_MIN_CONF_ALIGNED', 0.35)
            if is_aligned else getattr(config, 'TF_ENTRY_MIN_CONF_UNALIGNED', 0.50)
        )
        ctx = self._get_market_context(symbol)

        if not getattr(config, 'CONTEXTUAL_CONF_DYNAMIC_ENABLED', True):
            return base_threshold, {'base': base_threshold, 'adjustment': 0.0, 'alignment_reason': alignment_reason, **ctx}

        quality = max(0.0, min(1.0, float(ctx.get('quality_score', 0.0) or 0.0)))
        spoof = max(0.0, min(1.0, float(ctx.get('spoof_score', 0.0) or 0.0)))
        fast = max(0.0, min(1.0, float(ctx.get('fast_move_score', 0.0) or 0.0)))
        churn = max(0.0, min(1.0, float(ctx.get('churn_score', 0.0) or 0.0)))
        false_move = max(0.0, min(1.0, float(ctx.get('false_move_score', 0.0) or 0.0)))
        trend_strength = min(1.0, max(abs(float(ctx.get('ret_15m', 0.0) or 0.0)), abs(float(ctx.get('ret_1h', 0.0) or 0.0))) * 4.0)
        liq_total = abs(float(ctx.get('liq_long', 0.0) or 0.0)) + abs(float(ctx.get('liq_short', 0.0) or 0.0))
        liq_imbalance = abs(float(ctx.get('liq_long', 0.0) or 0.0) - float(ctx.get('liq_short', 0.0) or 0.0)) / max(liq_total, 1.0)
        funding_basis = min(1.0, abs(float(ctx.get('funding_rate', 0.0) or 0.0)) * 50.0 + abs(float(ctx.get('basis_pct', 0.0) or 0.0)) * 4.0)

        relief = min(
            float(getattr(config, 'CONTEXTUAL_CONF_MAX_RELIEF', 0.08) or 0.08),
            (0.45 * quality) + (0.30 * trend_strength) + (0.10 * (1.0 - liq_imbalance if liq_total > 0 else 0.0)),
        )
        penalty = min(
            float(getattr(config, 'CONTEXTUAL_CONF_MAX_PENALTY', 0.12) or 0.12),
            (0.40 * spoof) + (0.20 * fast) + (0.15 * churn) + (0.15 * false_move) + (0.10 * funding_basis) + (0.10 * liq_imbalance),
        )

        adjustment = penalty - (relief if is_aligned else (relief * 0.25))
        threshold = max(0.25, min(0.97, base_threshold + adjustment))
        return threshold, {
            'base': round(base_threshold, 4),
            'adjustment': round(adjustment, 4),
            'alignment_reason': alignment_reason,
            **ctx,
        }

    # ============================================================================
    # PHASE 4: HOURLY BUDGETS & COOLDOWNS ENFORCEMENT
    # ============================================================================
    
    def _check_cooldown(self, symbol: str, category: str) -> Tuple[bool, str]:
        """Check if symbol is on cooldown for given category (OPEN_RISK only)."""
        import config
        if not getattr(config, 'BUDGETS_ENABLED', True):
            return False, ""
        
        # Only OPEN_RISK has cooldowns
        if category != 'OPEN_RISK':
            return False, ""
        
        cooldown_key = f"cooldown:open_risk:{symbol}"
        
        try:
            ttl = 0
            if self._signal_redis:
                # Check Redis for cooldown key
                ttl = self._signal_redis.ttl(cooldown_key)
            else:
                # Fallback to in-memory cache
                expiry_ts = self._cooldown_cache.get(cooldown_key, 0)
                now_ms = int(time.time() * 1000)
                if expiry_ts > now_ms:
                    ttl = int((expiry_ts - now_ms) / 1000)
            
            if ttl > 0:
                return True, f"COOLDOWN_BLOCK (OPEN_RISK on {symbol} cooling for {ttl}s)"
                    
        except Exception as e:
            logger.warning(f"⚠️ Cooldown check failed for {symbol}/{category}: {e}")
        
        return False, ""
    
    def _check_budget(self, symbol: str, category: str) -> Tuple[bool, str]:
        """Check if hourly budget exceeded for given category/symbol.
        
        Returns:
            (is_over_budget, reason_code)
        """
        import config
        if not getattr(config, 'BUDGETS_ENABLED', True):
            return False, ""
        
        # PROTECTIVE is unlimited
        if category == 'PROTECTIVE':
            return False, ""
        
        now_ms = int(time.time() * 1000)
        
        try:
            # Check per-symbol budget
            per_symbol_key = f"budget:{category.lower()}:{symbol}"
            per_symbol_max = getattr(config, f"{category}_PER_SYMBOL_MAX_PER_HOUR", 0)
            
            if per_symbol_max > 0:
                if self._signal_redis:
                    per_symbol_count = int(self._signal_redis.get(per_symbol_key) or 0)
                else:
                    per_symbol_count = self._budget_counters.get(per_symbol_key, 0)
                
                if per_symbol_count >= per_symbol_max:
                    return True, f"BUDGET_BLOCK ({category} per-symbol budget {per_symbol_count}/{per_symbol_max} exceeded for {symbol})"
            
            # Check global budget
            global_key = f"budget:{category.lower()}:global"
            global_max = getattr(config, f"{category}_GLOBAL_MAX_PER_HOUR", 0)
            
            if global_max > 0:
                if self._signal_redis:
                    global_count = int(self._signal_redis.get(global_key) or 0)
                else:
                    global_count = self._budget_counters.get(global_key, 0)
                
                if global_count >= global_max:
                    return True, f"BUDGET_BLOCK ({category} global budget {global_count}/{global_max} exceeded)"
        
        except Exception as e:
            logger.warning(f"⚠️ Budget check failed for {symbol}/{category}: {e}")
        
        return False, ""
    
    def _increment_budget_counter(self, symbol: str, category: str):
        """Increment Redis budget counters with 3600s TTL after signal published."""
        import config
        if not getattr(config, 'BUDGETS_ENABLED', True):
            return
        
        if category == 'PROTECTIVE':
            return  # Never count PROTECTIVE
        
        try:
            per_symbol_key = f"budget:{category.lower()}:{symbol}"
            global_key = f"budget:{category.lower()}:global"
            
            if self._signal_redis:
                # Increment with 3600s TTL (rolling hourly window)
                pipe = self._signal_redis.pipeline()
                pipe.incr(per_symbol_key)
                pipe.expire(per_symbol_key, 3600)
                pipe.incr(global_key)
                pipe.expire(global_key, 3600)
                pipe.execute()
            else:
                # Fallback to in-memory
                self._budget_counters[per_symbol_key] = self._budget_counters.get(per_symbol_key, 0) + 1
                self._budget_counters[global_key] = self._budget_counters.get(global_key, 0) + 1
        
        except Exception as e:
            logger.warning(f"⚠️ Failed to increment budget for {symbol}/{category}: {e}")
    
    def _set_cooldown(self, symbol: str, category: str):
        """Set cooldown key in Redis after OPEN_RISK signal published."""
        import config
        if not getattr(config, 'BUDGETS_ENABLED', True):
            return
        
        if category != 'OPEN_RISK':
            return
        
        cooldown_seconds = getattr(config, 'OPEN_RISK_PER_SYMBOL_COOLDOWN_SECONDS', 900)
        if cooldown_seconds <= 0:
            return
        
        cooldown_key = f"cooldown:open_risk:{symbol}"
        
        try:
            if self._signal_redis:
                self._signal_redis.setex(cooldown_key, cooldown_seconds, "1")
            else:
                # Fallback to in-memory
                now_ms = int(time.time() * 1000)
                expiry_ms = now_ms + (cooldown_seconds * 1000)
                self._cooldown_cache[cooldown_key] = expiry_ms
        
        except Exception as e:
            logger.warning(f"⚠️ Failed to set cooldown for {symbol}/{category}: {e}")

    # ============================================================================
    # PHASE 5: HEDGE_BUILD STATE MANAGEMENT
    # ============================================================================
    
    def _consume_execution_feedback(self):
        """Consume execution feedback stream from traders (profit exits trigger HEDGE_BUILD)."""
        import config
        if not getattr(config, 'HEDGE_FIRST_ENABLED', True):
            return
        
        if not self._signal_redis:
            return
        
        try:
            # Read from execution feedback stream
            feedback_stream = "execution:feedback"
            messages = self._signal_redis.xread({feedback_stream: '0-0'}, count=100, block=0)
            
            for stream, entries in messages:
                for msg_id, data in entries:
                    event_type = data.get(b'event_type', b'').decode('utf-8')
                    
                    if event_type == 'PROFIT_EXIT':
                        symbol = data.get(b'symbol', b'').decode('utf-8')
                        side = data.get(b'side', b'').decode('utf-8')
                        pnl = float(data.get(b'pnl', 0))
                        
                        if symbol:
                            self._enter_hedge_build(symbol, f"profit_exit_{side.lower()}_pnl_{pnl:.2f}")
                            
                    # Acknowledge message
                    self._signal_redis.xdel(feedback_stream, msg_id)
        
        except Exception as e:
            logger.debug(f"[EXEC_FEEDBACK] Consumption error: {e}")
    
    def _enter_hedge_build(self, symbol: str, reason: str):
        """Enter HEDGE_BUILD state for symbol (blocks flips, allows gradual hedges)."""
        import config
        ttl_sec = getattr(config, 'HEDGE_BUILD_TTL_SECONDS', 600)
        now_ms = int(time.time() * 1000)
        expiry_ms = now_ms + (ttl_sec * 1000)
        
        with self._hedge_build_lock:
            self._hedge_build_state[symbol] = {
                'active': True,
                'expiry_ts': expiry_ms,
                'reason': reason,
                'entered_at': now_ms
            }
        
        logger.info(f"[HEDGE_BUILD_ENTER] {symbol} | reason={reason} | ttl={ttl_sec}s")

        # Persist to Redis as well (canonical HEDGE_BUILD signal for gating + dashboards)
        try:
            redis_client = getattr(self, 'redis', None) or getattr(self, '_signal_redis', None)
            if redis_client:
                import json
                key = f"wma:hedge_build:{symbol}"
                state = {
                    'symbol': symbol,
                    'exited_side': 'UNKNOWN',
                    'reason': reason,
                    'timestamp': time.time(),
                    'ttl_seconds': int(ttl_sec),
                }
                redis_client.setex(key, int(ttl_sec), json.dumps(state))
        except Exception:
            pass
    
    def _is_hedge_build_active(self, symbol: str, account_id: str = None) -> Tuple[bool, str]:
        """Check if symbol is in HEDGE_BUILD state.
        
        Returns:
            (is_active, reason)
        """
        import config
        if not getattr(config, 'HEDGE_FIRST_ENABLED', True):
            return False, ""

        if not getattr(config, 'HEDGE_BUILD_ENABLED', True):
            return False, ""

        # Canonical: Redis-backed key set by _enter_hedge_build_state (triggered via trader feedback)
        try:
            redis_client = getattr(self, 'redis', None) or getattr(self, '_signal_redis', None)
            if redis_client:
                acct = (str(account_id).strip().lower() if account_id else None)

                # Prefer account-scoped state (prevents primary/asjad cross-contamination)
                keys = []
                if acct in ("primary", "asjad"):
                    keys.append(f"wma:hedge_build:{acct}:{symbol}")

                # Backward compat fallback
                keys.append(f"wma:hedge_build:{symbol}")

                raw = None
                state = None
                for key in keys:
                    raw = redis_client.get(key)
                    if raw:
                        try:
                            import json
                            if isinstance(raw, bytes):
                                raw = raw.decode('utf-8')
                            state = json.loads(raw)
                        except Exception:
                            state = None
                        if raw:
                            break

                if raw:
                    try:
                        return True, str(state.get('reason') or state.get('event_type') or 'feedback')
                    except Exception:
                        return True, "feedback"
        except Exception:
            pass
        
        now_ms = int(time.time() * 1000)
        
        with self._hedge_build_lock:
            state = self._hedge_build_state.get(symbol)
            
            if not state or not state.get('active'):
                return False, ""
            
            # Check if expired
            if now_ms > state['expiry_ts']:
                # Expire state
                state['active'] = False
                elapsed_sec = (now_ms - state['entered_at']) / 1000
                logger.info(f"[HEDGE_BUILD_EXIT] {symbol} | reason=ttl_expired | elapsed={elapsed_sec:.1f}s")
                return False, ""
            
            # Defensive: older in-memory states may omit 'reason'
            try:
                return True, str(state.get('reason') or state.get('event_type') or 'hedge_build')
            except Exception:
                return True, "hedge_build"
    
    def _check_hedge_build_block(self, symbol: str, action: str, action_category: str, confidence: float, account_id: str = None) -> Tuple[bool, str]:
        """Phase 5: Check if action should be blocked during HEDGE_BUILD window.
        
        During HEDGE_BUILD (after trailing exit), we want to:
        - Allow PROTECTIVE always
        - Convert OPEN_RISK to HEDGE (not block it!)
        - Block FLIPs unless very high confidence
        - Allow HEDGE with size limits
        
        Returns:
            (should_block, reason)
            Special: reason="CONVERT_TO_HEDGE" means action should be converted, not blocked
        """
        import config
        is_active, hb_reason = self._is_hedge_build_active(symbol, account_id=account_id)
        
        if not is_active:
            return False, ""
        
        # PROTECTIVE always allowed
        if action_category == 'PROTECTIVE':
            return False, ""
        
        # Block all FLIPs during HEDGE_BUILD
        # NOTE: In some multiprocess worker contexts we have seen sporadic
        # AttributeError for _is_flip_action due to stale class load / partial init.
        # Make this path fail-safe (never crash the trainer).
        _flip_fn = getattr(self, "_is_flip_action", None)
        is_flip = bool(_flip_fn(action)) if callable(_flip_fn) else ("FLIP" in str(action or "").upper())
        if is_flip:
            # Exception: Very high confidence + HTF alignment can override
            flip_min_conf = getattr(config, 'HEDGE_BUILD_FLIP_MIN_CONF', 0.97)
            require_alignment = getattr(config, 'HEDGE_BUILD_REQUIRE_ALIGNMENT', True)
            
            if confidence >= flip_min_conf:
                if require_alignment:
                    is_aligned, align_sig = self._is_stack_aligned(symbol, action)
                    if is_aligned:
                        logger.info(f"[HEDGE_BUILD_ACTIVE] {symbol} FLIP allowed: conf={confidence:.3f}>={flip_min_conf} + aligned={align_sig}")
                        return False, ""
                else:
                    logger.info(f"[HEDGE_BUILD_ACTIVE] {symbol} FLIP allowed: conf={confidence:.3f}>={flip_min_conf}")
                    return False, ""
            
            return True, f"HEDGE_BUILD_FLIP_BLOCK (conf={confidence:.3f} < {flip_min_conf} or not aligned)"
        
        # CRITICAL FIX: During HEDGE_BUILD, convert OPEN_RISK to HEDGE instead of blocking
        # This enables building hedge positions after trailing exits
        if action_category == 'OPEN_RISK':
            # SAFETY (Jan 2026):
            # Do NOT convert OPEN_RISK to OPEN_HEDGE_* when the symbol is flat.
            # That conversion creates "hedge-from-flat" proposals which traders correctly reject
            # (HEDGE_FROM_FLAT_BLOCK) and it starves real OPEN_RISK entries.
            try:
                if account_id:
                    pos_now = self.get_all_positions_for_symbol(symbol, account_id=str(account_id).strip().lower())
                else:
                    pos_now = self.get_all_positions_for_symbol(symbol)
            except Exception:
                pos_now = None
            if not pos_now and getattr(config, 'HEDGE_BUILD_BLOCK_FLAT_REENTRY', True):
                logger.info(f"[HEDGE_BUILD_ACTIVE] {symbol} OPEN_RISK blocked | flat_reentry | reason={hb_reason}")
                return True, "HEDGE_BUILD_REENTRY_BLOCK (flat_symbol)"
            if not pos_now:
                logger.info(f"[HEDGE_BUILD_CONVERT_SKIP] {symbol} | flat symbol → keep OPEN_RISK (no hedge conversion) | reason={hb_reason}")
                return False, ""

            # Signal to caller that this should be converted to HEDGE, not blocked
            logger.info(f"[HEDGE_BUILD_CONVERT] {symbol} | {action} OPEN_RISK -> HEDGE | reason={hb_reason}")
            return False, "CONVERT_TO_HEDGE"

        # Recovery adds are risk-increasing and should not occur during HEDGE_BUILD cooldown.
        if action_category == 'RECOVERY':
            return True, f"HEDGE_BUILD_RECOVERY_BLOCK ({hb_reason})"
        
        # HEDGE allowed with size limits
        if action_category == 'HEDGE':
            # Check size limit
            max_add_pct = getattr(config, 'HEDGE_BUILD_MAX_ADD_PCT', 0.05)
            logger.info(f"[HEDGE_BUILD_ACTIVE] {symbol} HEDGE allowed (max_add={max_add_pct*100:.1f}%)")
            return False, ""
        
        return False, ""
    
    # ============================================================================
    # PHASE 6: MICROSTRUCTURE EXECUTION GATE
    # ============================================================================
    
    def _exec_gate_decision(self, symbol: str, action_category: str) -> Tuple[str, str]:
        """Phase 6: Microstructure-based execution gate decision.
        
        Returns:
            (decision, reason) where decision in {PASS, DELAY, SIZE_REDUCE}
        """
        import config
        if not getattr(config, 'EXEC_GATE_ENABLED', True):
            return 'PASS', ''
        
        # Respect MICROSTRUCTURE_OVERLAY_MODE: only gate when explicitly enabled
        overlay_mode = str(getattr(config, 'MICROSTRUCTURE_OVERLAY_MODE', 'gating') or 'gating').lower()
        if overlay_mode != 'gating':
            return 'PASS', 'exec_gate_disabled'
        
        # Fail-closed: HEDGE/PROTECTIVE always bypass microstructure gate
        if action_category in ('HEDGE', 'PROTECTIVE'):
            return 'PASS', 'MICROSTRUCTURE_BYPASS'
        
        try:
            if not self._signal_redis:
                no_data_action = str(getattr(config, 'EXEC_GATE_NO_DATA_ACTION', 'DELAY')).upper()
                return (no_data_action if no_data_action in ('PASS', 'DELAY') else 'DELAY'), 'MICROSTRUCTURE_FAIL_CLOSED (no_redis)'

            ctx = self._get_market_context(symbol)
            source_count = int(ctx.get('source_count', 0) or 0)
            if source_count < int(getattr(config, 'EXEC_GATE_MIN_SOURCE_COUNT', 2) or 2):
                no_data_action = str(getattr(config, 'EXEC_GATE_NO_DATA_ACTION', 'DELAY')).upper()
                if no_data_action == 'PASS':
                    return 'PASS', f"MICROSTRUCTURE_NO_DATA_PASS (sources={source_count})"
                return 'DELAY', f"MICROSTRUCTURE_FAIL_CLOSED (sources={source_count})"

            spread_pct = max(0.0, float(ctx.get('spread_pct', 0.0) or 0.0))
            spoof_score = max(0.0, min(1.0, float(ctx.get('spoof_score', 0.0) or 0.0)))
            fast_move = max(0.0, min(1.0, float(ctx.get('fast_move_score', 0.0) or 0.0)))
            churn_score = max(0.0, min(1.0, float(ctx.get('churn_score', 0.0) or 0.0)))
            quality_score = max(0.0, min(1.0, float(ctx.get('quality_score', 0.0) or 0.0)))
            false_move = max(0.0, min(1.0, float(ctx.get('false_move_score', 0.0) or 0.0)))
            liq_total = abs(float(ctx.get('liq_long', 0.0) or 0.0)) + abs(float(ctx.get('liq_short', 0.0) or 0.0))
            liq_imbalance = abs(float(ctx.get('liq_long', 0.0) or 0.0) - float(ctx.get('liq_short', 0.0) or 0.0)) / max(liq_total, 1.0)
            regime_vol = min(1.0, max(abs(float(ctx.get('ret_5m', 0.0) or 0.0)), abs(float(ctx.get('ret_15m', 0.0) or 0.0)) * 0.8, abs(float(ctx.get('ret_1h', 0.0) or 0.0)) * 0.5) * 5.0)

            dyn_spread_limit = float(getattr(config, 'EXEC_GATE_MAX_SPREAD_PCT', 0.03) or 0.03)
            if getattr(config, 'EXEC_GATE_DYNAMIC_ENABLED', True):
                dyn_spread_limit *= max(0.65, min(2.5, 0.85 + (regime_vol * 0.9) + (quality_score * 0.5) - (spoof_score * 0.25)))

            spread_pressure = min(1.0, spread_pct / max(dyn_spread_limit, 1e-6))
            quality_penalty = 1.0 - quality_score
            risk_score = (
                0.26 * spoof_score +
                0.22 * fast_move +
                0.14 * churn_score +
                0.12 * false_move +
                0.12 * spread_pressure +
                0.08 * quality_penalty +
                0.06 * liq_imbalance
            )

            if quality_score < float(getattr(config, 'EXEC_GATE_MIN_QUALITY', 0.35) or 0.35):
                return 'DELAY', f"MICROSTRUCTURE_FAIL_CLOSED (quality={quality_score:.2f})"
            if false_move > float(getattr(config, 'EXEC_GATE_MAX_FALSE_MOVE', 0.65) or 0.65) and spoof_score > 0.45:
                return 'DELAY', f"false_move_spoof (false={false_move:.2f} spoof={spoof_score:.2f})"
            if liq_imbalance > float(getattr(config, 'EXEC_GATE_MAX_LIQ_IMBALANCE', 0.75) or 0.75) and fast_move > 0.45:
                return 'DELAY', f"liq_imbalance_fast_move (liq_imb={liq_imbalance:.2f} fast={fast_move:.2f})"
            if spread_pct > dyn_spread_limit and spoof_score > 0.45:
                return 'DELAY', f"spread_spoof (spread={spread_pct:.4f}>{dyn_spread_limit:.4f} spoof={spoof_score:.2f})"
            if risk_score >= float(getattr(config, 'EXEC_GATE_RISK_DELAY_THRESHOLD', 0.82) or 0.82):
                return 'DELAY', f"risk_score_high ({risk_score:.2f})"
            if risk_score >= float(getattr(config, 'EXEC_GATE_RISK_SIZE_REDUCE_THRESHOLD', 0.58) or 0.58):
                return 'SIZE_REDUCE', f"risk_score_reduce ({risk_score:.2f})"

            return 'PASS', (
                f"healthy src={ctx.get('source', 'none')} sources={source_count} quality={quality_score:.2f} "
                f"spoof={spoof_score:.2f} fast={fast_move:.2f} spread={spread_pct:.4f}"
            )
        
        except Exception as e:
            logger.debug(f"[EXEC_GATE] Error checking {symbol}: {e}")
            # Fail-closed: delay on error for OPEN_RISK
            return 'DELAY', f'MICROSTRUCTURE_FAIL_CLOSED (error: {str(e)[:50]})'
    
    # ============================================================================
    # PHASE 7: PERFORMANCE METRICS TRACKING
    # ============================================================================
    
    def _track_trade_execution(self, symbol: str, side: str, qty: float, price: float, pnl: float = 0, 
                               notional_usd: float = 0, fee_usd: float = 0):
        """Track trade execution for performance metrics and fee tracking.
        
        Args:
            symbol: Trading pair symbol
            side: LONG or SHORT
            qty: Position quantity
            price: Entry/exit price  
            pnl: Realized PnL (if closing)
            notional_usd: Trade notional value in USD (for fee estimation if fee_usd not provided)
            fee_usd: Actual fee paid (if known from exchange)
        """
        import config
        if not getattr(config, 'PERF_TRACKING_ENABLED', True):
            return
        
        import time
        now_ts = int(time.time())
        
        # Calculate estimated fee if not provided
        if fee_usd <= 0 and notional_usd > 0:
            fee_rate = getattr(config, 'TAKER_FEE_PCT', 0.05) / 100
            fee_usd = notional_usd * fee_rate
        
        with self._perf_metrics_lock:
            self._perf_metrics['trades_today'] += 1
            self._perf_metrics['trade_count'] += 1
            
            # FEE TRACKING: Add fee to hourly total
            if fee_usd > 0:
                self._perf_metrics['fees_today'] += fee_usd
                logger.debug(f"[FEE_TRACKED] {symbol} {side}: fee=${fee_usd:.4f} | hourly_total=${self._perf_metrics['fees_today']:.2f}")
            
            # Track trade history for churn detection
            self._perf_metrics['trade_history'].append({
                'symbol': symbol,
                'ts': now_ts,
                'side': side,
                'qty': qty,
                'price': price,
                'pnl': pnl,
                'fee_usd': fee_usd
            })
            
            # Check for churn (reopen within window)
            churn_window = getattr(config, 'PERF_CHURN_WINDOW_MINUTES', 20) * 60
            for prev_trade in reversed(self._perf_metrics['trade_history'][:-1]):
                if prev_trade['symbol'] != symbol:
                    continue
                
                time_diff = now_ts - prev_trade['ts']
                if time_diff > churn_window:
                    break
                
                # Opposite side within window = churn
                if prev_trade['side'] != side and time_diff < churn_window:
                    self._perf_metrics['churn_count'] += 1
                    logger.warning(f"[CHURN_DETECTED] {symbol} {side} within {time_diff}s of opposite {prev_trade['side']}")
                    break
            
            # Cleanup old history (keep last 1000 trades)
            if len(self._perf_metrics['trade_history']) > 1000:
                self._perf_metrics['trade_history'] = self._perf_metrics['trade_history'][-1000:]
    
    def _emit_perf_summary(self):
        """Emit hourly performance summary."""
        import config
        if not getattr(config, 'PERF_TRACKING_ENABLED', True):
            return
        
        import time
        now_ts = int(time.time())
        interval = getattr(config, 'PERF_SUMMARY_INTERVAL_SECONDS', 3600)
        
        with self._perf_metrics_lock:
            elapsed = now_ts - self._perf_metrics['last_summary_ts']
            
            if elapsed < interval:
                return
            
            # Calculate metrics
            trades = self._perf_metrics['trades_today']
            fees = self._perf_metrics['fees_today']
            total_trades = self._perf_metrics['trade_count']
            churn_count = self._perf_metrics['churn_count']
            churn_rate = (churn_count / total_trades * 100) if total_trades > 0 else 0
            
            logger.info(f"[PERF_SUMMARY] trades={trades} | fees=${fees:.2f} | churn_rate={churn_rate:.1f}% | total={total_trades}")
            
            # Reset hourly counters
            self._perf_metrics['trades_today'] = 0
            self._perf_metrics['fees_today'] = 0.0
            self._perf_metrics['last_summary_ts'] = now_ts
        
        # ========================================================================
        # SIGNAL STATE MANAGER STATS: Log deduplication effectiveness
        # ========================================================================
        try:
            from rl.signal_state_manager import get_signal_state_manager
            state_manager = get_signal_state_manager(getattr(self, '_signal_redis', None))
            stats = state_manager.get_stats()
            
            logger.info(
                f"[SIGNAL_STATE_SUMMARY] "
                f"allowed={stats.get('signals_allowed', 0)} | "
                f"blocked={stats.get('signals_blocked', 0)} | "
                f"block_rate={stats.get('block_rate_pct', 0):.1f}% | "
                f"by_pending={stats.get('blocked_by_pending', 0)} | "
                f"by_cooldown={stats.get('blocked_by_cooldown', 0)} | "
                f"by_duplicate={stats.get('blocked_by_duplicate', 0)} | "
                f"override_price={stats.get('overridden_by_price', 0)} | "
                f"override_pnl={stats.get('overridden_by_pnl', 0)} | "
                f"override_position={stats.get('overridden_by_position', 0)}"
            )
        except ImportError:
            pass  # SignalStateManager not available
        except Exception as ssm_err:
            logger.debug(f"[SIGNAL_STATE_SUMMARY] Non-critical error: {ssm_err}")

    def _check_risk_gates(self, symbol: str, action: str, position_size: float, leverage: float) -> Tuple[bool, str]:
        """I) Risk Gates - Hard constraints that block publishing/execution
        
        Returns:
            (should_block, reason_code)
        """
        def _gate_log(gate: str, status: str, reason: str, meta: dict = None) -> None:
            try:
                logger.info(
                    "GATE_DECISION | gate=%s | status=%s | symbol=%s | action=%s | reason=%s | meta=%s",
                    gate,
                    status,
                    symbol,
                    action,
                    reason,
                    meta or {},
                )
            except Exception:
                pass

        # Operator requirement: HEDGE actions must bypass all gating/blocks.
        try:
            a_u = str(action or "").upper()
            if a_u.startswith(("OPEN_HEDGE_", "ADD_HEDGE_", "SCALE_HEDGE", "UNWIND_HEDGE")):
                reason = "HEDGE_BYPASS_RISK_GATES"
                _gate_log("HEDGE_BYPASS", "PASS", reason)
                return False, reason
        except Exception:
            pass

        # MANAGE bypass: CLOSE / REDUCE / TP / SL / DELEVERAGE must NEVER be blocked by
        # open-risk gates (margin cap, drawdown, concentration, liquidity).
        # These actions reduce existing exposure — gating them when margin is high is
        # counterproductive.  CLOSE_AND_* (flip) is excluded because it opens new exposure.
        try:
            _MANAGE_TOKENS = (
                "CLOSE", "REDUCE", "DECREASE", "TAKE_PROFIT", "STOP_LOSS",
                "PARTIAL_CLOSE", "DELEVERAGE", "BUDGET_TRIM", "TRAIL", "EXIT",
            )
            # Detect ALL flip patterns (opens new exposure — must NOT bypass risk gates)
            _is_flip = (
                a_u.startswith("CLOSE_AND_")
                or "FLIP" in a_u
                or ("CLOSE_LONG" in a_u and "OPEN_SHORT" in a_u)
                or ("CLOSE_SHORT" in a_u and "OPEN_LONG" in a_u)
            )
            if any(tok in a_u for tok in _MANAGE_TOKENS) and not _is_flip:
                reason = "MANAGE_BYPASS_RISK_GATES"
                _gate_log("MANAGE_BYPASS", "PASS", reason)
                return False, reason
        except Exception:
            pass

        # I.1) Margin Safety Buffer
        # IMPORTANT (Jan 2026 operator): this must NOT use combined trainer_cached utilization
        # when running multi-account. If no account_id is specified yet, treat the gate as
        # "pass if ANY account has room", because routing happens later.
        try:
            from config import MAX_MARGIN_UTIL_ABSOLUTE_PCT as _ABS
            abs_cap = float(_ABS)
        except Exception:
            abs_cap = 90.0
        abs_cap = max(50.0, min(99.0, float(abs_cap)))
        warn_cap = max(40.0, float(abs_cap) - 10.0)

        margin_util = None
        util_src = "trainer_cached"
        util_by_acct = {}
        try:
            from config import ENABLE_PER_ACCOUNT_STREAMS, SIGNAL_STREAM_PER_ACCOUNT, TRADING_ACCOUNTS
        except Exception:
            ENABLE_PER_ACCOUNT_STREAMS = False
            SIGNAL_STREAM_PER_ACCOUNT = {}
            TRADING_ACCOUNTS = ["primary", "asjad"]

        if bool(ENABLE_PER_ACCOUNT_STREAMS) and hasattr(self, "_get_portfolio_state"):
            try:
                accounts = []
                if isinstance(SIGNAL_STREAM_PER_ACCOUNT, dict) and SIGNAL_STREAM_PER_ACCOUNT:
                    accounts = list(SIGNAL_STREAM_PER_ACCOUNT.keys())
                else:
                    accounts = list(TRADING_ACCOUNTS or ["primary", "asjad"])

                for aid in [str(a).strip().lower() for a in accounts if a]:
                    if aid not in ("primary", "asjad"):
                        continue
                    try:
                        st = self._get_portfolio_state(account_id=aid) or {}
                        util = float(
                            st.get("margin_utilization_pct", st.get("margin_utilization", st.get("margin_ratio", 0.0)))
                            or 0.0
                        )
                    except Exception:
                        util = 0.0
                    util_by_acct[aid] = util

                if util_by_acct:
                    # routing later can pick the best account → use best util for gating
                    margin_util = float(min(util_by_acct.values()))
                    util_src = f"per_account_best all={util_by_acct}"
            except Exception:
                margin_util = None

        if margin_util is None:
            margin_util = float(self._margin_metrics.get('margin_utilization', 0.0) or 0.0)

        if float(margin_util) >= float(abs_cap):
            reason = f"RISK_GATE_MARGIN (utilization {float(margin_util):.1f}% >= {abs_cap:.0f}% [{util_src}])"
            _gate_log("MARGIN", "BLOCK", reason, {"margin_util": float(margin_util), "abs_cap": abs_cap, "warn_cap": warn_cap, "util_src": util_src})
            return True, reason
        elif float(margin_util) >= float(warn_cap):
            logger.warning(
                f"⚠️ [RISK] High margin utilization: {float(margin_util):.1f}% (warn>={warn_cap:.0f} cap={abs_cap:.0f}) [{util_src}] - reducing position size"
            )
            reason = "WARNING_HIGH_MARGIN"
            _gate_log("MARGIN", "WARN", reason, {"margin_util": float(margin_util), "abs_cap": abs_cap, "warn_cap": warn_cap, "util_src": util_src})
            return False, reason
        
        # I.2) Drawdown Circuit Breaker
        action_u = str(action or "").upper().strip()
        is_recovery_action = any(tok in action_u for tok in [
            "HEDGE",
            "REPAIR",
            "DEFENSE",
            "PROTECTIVE",
            "PARTIAL_CLOSE",
            "STOP_LOSS",
            "TAKE_PROFIT",
        ])
        # Drawdown gate: configurable thresholds (avoid hardcoded blocking)
        _dd_block_pct = 50.0
        _dd_warn_pct = 25.0
        try:
            _dd_block_pct = float(getattr(config, "TRAINER_DD_BLOCK_PCT", 50.0))
            _dd_warn_pct = float(getattr(config, "TRAINER_DD_WARN_PCT", 25.0))
        except Exception:
            pass
        if self._current_drawdown_pct > _dd_block_pct and not is_recovery_action:
            reason = "RISK_GATE_DRAWDOWN (drawdown {:.1f}% > {:.0f}%)".format(self._current_drawdown_pct, _dd_block_pct)
            _gate_log("DRAWDOWN", "BLOCK", reason, {"drawdown_pct": float(self._current_drawdown_pct)})
            return True, reason
        elif self._current_drawdown_pct > _dd_warn_pct:
            # Reduce leverage by 50%
            logger.warning(f"⚠️ [RISK] High drawdown: {self._current_drawdown_pct:.1f}% - reducing leverage")
            reason = "WARNING_HIGH_DRAWDOWN"
            _gate_log("DRAWDOWN", "WARN", reason, {"drawdown_pct": float(self._current_drawdown_pct)})
            return False, reason
        # I.3) Portfolio Concentration Caps - Correlation-based concentration limits
        # BYPASS: Protective/close/hedge/manage actions must NOT be blocked by concentration
        # — you must always be able to manage (close, hedge, reduce) existing positions.
        _action_upper = str(action).upper()
        _is_risk_reducing = any(tok in _action_upper for tok in [
            "CLOSE", "REDUCE", "HEDGE", "HOLD", "SET_TAKE_PROFIT", "SET_STOP",
            "PARTIAL", "EXIT", "PROTECTIVE", "DCA",
        ])
        if _is_risk_reducing:
            _gate_log("CONCENTRATION", "BYPASS", f"risk-reducing action {action}")
        else:
            concentration_result = self._check_portfolio_concentration(symbol, action, position_size)
            if concentration_result['should_block']:
                reason = f"RISK_GATE_CONCENTRATION ({concentration_result['reason']})"
                _gate_log("CONCENTRATION", "BLOCK", reason)
                return True, reason
            elif concentration_result['should_warn']:
                logger.warning(f"⚠️ [RISK] High concentration: {concentration_result['reason']} - reducing position size")
                reason = f"WARNING_HIGH_CONCENTRATION ({concentration_result['reason']})"
                _gate_log("CONCENTRATION", "WARN", reason)
                return False, reason
        
        # I.4) Slippage & Liquidity Gates - Order book depth/spread check
        liquidity_result = self._check_liquidity_gates(symbol)
        try:
            self._last_liquidity_gate_result[symbol] = dict(liquidity_result or {})
        except Exception:
            pass
        if liquidity_result['should_block']:
            try:
                from config import LIQUIDITY_SOFT_BLOCK_ENABLED
            except Exception:
                LIQUIDITY_SOFT_BLOCK_ENABLED = False
            liq_meta = {
                "spread_pct": liquidity_result.get("spread_pct"),
                "depth_usd": liquidity_result.get("depth_usd"),
                "orderbook_ts_ms": liquidity_result.get("orderbook_ts_ms"),
                "min_depth_usd": liquidity_result.get("min_depth_usd"),
                "warn_depth_usd": liquidity_result.get("warn_depth_usd"),
                "max_spread_pct": liquidity_result.get("max_spread_pct"),
                "warn_spread_pct": liquidity_result.get("warn_spread_pct"),
                "liq_tier": liquidity_result.get("liq_tier"),
                "regime_stress": liquidity_result.get("regime_stress"),
                "regime_structure": liquidity_result.get("regime_structure"),
                "structural_regime": liquidity_result.get("structural_regime"),
            }
            if LIQUIDITY_SOFT_BLOCK_ENABLED:
                reason = f"LIQUIDITY_SOFT_BLOCK ({liquidity_result['reason']})"
                _gate_log("LIQUIDITY", "WARN", reason, liq_meta)
                return False, reason
            reason = f"RISK_GATE_LIQUIDITY ({liquidity_result['reason']})"
            _gate_log("LIQUIDITY", "BLOCK", reason, liq_meta)
            return True, reason
        elif liquidity_result['should_warn']:
            logger.warning(f"⚠️ [RISK] Low liquidity: {liquidity_result['reason']} - reducing position size")
            reason = f"WARNING_LOW_LIQUIDITY ({liquidity_result['reason']})"
            _gate_log(
                "LIQUIDITY",
                "WARN",
                reason,
                {
                    "spread_pct": liquidity_result.get("spread_pct"),
                    "depth_usd": liquidity_result.get("depth_usd"),
                    "orderbook_ts_ms": liquidity_result.get("orderbook_ts_ms"),
                    "min_depth_usd": liquidity_result.get("min_depth_usd"),
                    "warn_depth_usd": liquidity_result.get("warn_depth_usd"),
                    "max_spread_pct": liquidity_result.get("max_spread_pct"),
                    "warn_spread_pct": liquidity_result.get("warn_spread_pct"),
                    "liq_tier": liquidity_result.get("liq_tier"),
                    "regime_stress": liquidity_result.get("regime_stress"),
                    "regime_structure": liquidity_result.get("regime_structure"),
                    "structural_regime": liquidity_result.get("structural_regime"),
                },
            )
            return False, reason

        # I.5) Structural regime gate (slow-memory, downside-aware)
        try:
            from config import STRUCT_REGIME_BLOCK_RISK_ADD, STRUCT_REGIME_BEAR_DAMAGE_ALLOW_SHORTS
            from risk.assertions import is_risk_add_action
            action_u = str(action or "").upper()
            is_risk_add = bool(is_risk_add_action(action_u))
            if is_risk_add:
                structural = self._get_structural_regime_context(symbol)
                effective = str(structural.get("effective_regime") or "NORMAL").upper()
                if effective in [s.strip().upper() for s in (STRUCT_REGIME_BLOCK_RISK_ADD or []) if s.strip()]:
                    reason = f"RISK_GATE_STRUCT_REGIME ({effective})"
                    _gate_log("STRUCT_REGIME", "BLOCK", reason, {"effective": effective})
                    return True, reason
                if effective == "BEAR_DAMAGE":
                    allow_shorts = bool(STRUCT_REGIME_BEAR_DAMAGE_ALLOW_SHORTS)
                    if allow_shorts and "SHORT" in action_u:
                        pass
                    else:
                        reason = f"RISK_GATE_STRUCT_REGIME ({effective})"
                        _gate_log("STRUCT_REGIME", "BLOCK", reason, {"effective": effective})
                        return True, reason
        except Exception:
            pass

        _gate_log("RISK_GATES", "PASS", "PASSED")
        return False, "PASSED"
    
    def _check_portfolio_concentration(self, symbol: str, action: str, position_size: float) -> Dict[str, Any]:
        """I.3) Portfolio Concentration Caps - Prevent stacking correlated exposure
        
        Feb 2026 REWRITE: Use MARGIN-based concentration (gross_margin/equity)
        instead of notional/equity which always trips with 50-75× leverage.
        
        Returns:
            {
                'should_block': bool,
                'should_warn': bool,
                'reason': str,
            }
        """
        try:
            # Load config thresholds
            try:
                import config as _cfg
                use_margin = getattr(_cfg, "CONCENTRATION_USE_MARGIN", True)
                gross_margin_max = float(getattr(_cfg, "CONCENTRATION_GROSS_MARGIN_MAX_PCT", 95.0))
                gross_margin_warn = float(getattr(_cfg, "CONCENTRATION_GROSS_MARGIN_WARN_PCT", 80.0))
                net_delta_max = float(getattr(_cfg, "CONCENTRATION_NET_DELTA_MAX_PCT", 60.0))
                single_sym_margin_max = float(getattr(_cfg, "CONCENTRATION_SINGLE_SYMBOL_MARGIN_MAX_PCT", 40.0))
            except Exception:
                use_margin = True
                gross_margin_max = 95.0
                gross_margin_warn = 80.0
                net_delta_max = 60.0
                single_sym_margin_max = 40.0

            # Get current equity
            current_equity = getattr(self, "_real_balance", 0.0) or 0.0
            if current_equity <= 0:
                return {'should_block': False, 'should_warn': False, 'reason': 'No equity data'}

            # ── Use unified position loader for hedge-aware data ──
            try:
                from utils.unified_position_loader import load_all_positions
                rc = self._signal_redis if getattr(self, "_signal_redis", None) else get_redis()
                all_pos = load_all_positions(rc, account_id="primary")
            except Exception as _upl_err:
                logger.debug("CONCENTRATION: unified loader unavailable (%s), fallback", _upl_err)
                all_pos = {}

            if not all_pos:
                return {'should_block': False, 'should_warn': False, 'reason': 'No positions loaded'}

            # Define correlation groups
            correlation_groups = {
                'majors': ['BTCUSDT', 'ETHUSDT'],
                'alt_layer1': ['SOLUSDT', 'AVAXUSDT', 'ADAUSDT'],
                'meme': ['DOGEUSDT', '1000SHIBUSDT', 'WIFUSDT'],
                'defi': ['LINKUSDT', 'UNIUSDT'],
                'payment': ['XRPUSDT', 'LTCUSDT'],
            }

            # Find which group the new symbol belongs to
            symbol_group = None
            for group_name, group_symbols in correlation_groups.items():
                if symbol in group_symbols:
                    symbol_group = group_name
                    break

            if symbol_group is None:
                return {'should_block': False, 'should_warn': False, 'reason': f'Unknown symbol group for {symbol}'}

            # ── A) Margin-based concentration (recommended) ──
            if use_margin:
                # Sum gross margin for all positions in this correlation group
                group_margin = 0.0
                group_positions = []
                group_net_notional = 0.0
                for pos_symbol, pos_rec in all_pos.items():
                    if pos_symbol in correlation_groups.get(symbol_group, []):
                        gm = float(pos_rec.get("gross_margin", 0) or 0)
                        nn = float(pos_rec.get("net_notional", 0) or 0)
                        group_margin += gm
                        group_net_notional += nn
                        if gm > 0:
                            group_positions.append(pos_symbol)

                group_margin_pct = (group_margin / current_equity) * 100 if current_equity > 0 else 0
                group_net_delta_pct = (abs(group_net_notional) / current_equity) * 100 if current_equity > 0 else 0

                # Block: gross margin util > cap
                if group_margin_pct > gross_margin_max:
                    return {
                        'should_block': True,
                        'should_warn': False,
                        'reason': f'Group {symbol_group} margin {group_margin_pct:.1f}% > {gross_margin_max:.0f}% (positions: {group_positions})'
                    }

                # Block: net delta directional risk > cap
                if group_net_delta_pct > net_delta_max:
                    return {
                        'should_block': True,
                        'should_warn': False,
                        'reason': f'Group {symbol_group} net delta {group_net_delta_pct:.1f}% > {net_delta_max:.0f}% (positions: {group_positions})'
                    }

                # Warn: approaching margin cap
                if group_margin_pct > gross_margin_warn:
                    return {
                        'should_block': False,
                        'should_warn': True,
                        'reason': f'Group {symbol_group} margin {group_margin_pct:.1f}% > {gross_margin_warn:.0f}% (positions: {group_positions})'
                    }

                # Single-symbol margin cap
                sym_rec = all_pos.get(symbol, {})
                sym_margin_pct = (float(sym_rec.get("gross_margin", 0) or 0) / current_equity) * 100 if current_equity > 0 else 0
                if sym_margin_pct > single_sym_margin_max:
                    return {
                        'should_block': True,
                        'should_warn': False,
                        'reason': f'Single symbol {symbol} margin {sym_margin_pct:.1f}% > {single_sym_margin_max:.0f}%'
                    }

                return {'should_block': False, 'should_warn': False, 'reason': 'Margin concentration within limits'}

            # ── B) Legacy notional-based (if CONCENTRATION_USE_MARGIN=false) ──
            group_exposure = 0.0
            group_positions = []
            for pos_symbol, pos_rec in all_pos.items():
                if pos_symbol in correlation_groups.get(symbol_group, []):
                    pos_notional = abs(float(pos_rec.get('gross_notional', 0) or 0))
                    group_exposure += pos_notional
                    if pos_notional > 0:
                        group_positions.append(pos_symbol)

            new_position_notional = position_size * current_equity
            new_group_exposure = group_exposure + new_position_notional
            group_exposure_pct = (new_group_exposure / current_equity) * 100 if current_equity > 0 else 0

            MAX_GROUP_EXPOSURE_PCT = 40.0
            WARNING_GROUP_EXPOSURE_PCT = 30.0

            if group_exposure_pct > MAX_GROUP_EXPOSURE_PCT:
                return {
                    'should_block': True,
                    'should_warn': False,
                    'reason': f'Group {symbol_group} exposure {group_exposure_pct:.1f}% > {MAX_GROUP_EXPOSURE_PCT}% (positions: {group_positions})'
                }
            elif group_exposure_pct > WARNING_GROUP_EXPOSURE_PCT:
                return {
                    'should_block': False,
                    'should_warn': True,
                    'reason': f'Group {symbol_group} exposure {group_exposure_pct:.1f}% > {WARNING_GROUP_EXPOSURE_PCT}% (positions: {group_positions})'
                }

            return {'should_block': False, 'should_warn': False, 'reason': 'Concentration within limits'}

        except Exception as e:
            logger.debug(f"Portfolio concentration check error: {e}")
            return {'should_block': False, 'should_warn': False, 'reason': f'Error: {str(e)}'}
    
    def _check_liquidity_gates(self, symbol: str) -> Dict[str, Any]:
        """I.4) Slippage & Liquidity Gates - Monitor spread and order book depth
        
        Returns:
            {
                'should_block': bool,
                'should_warn': bool,
                'reason': str,
                'spread_pct': float (optional),
                'depth_usd': float (optional)
            }
        """
        try:
            # Get order book data from Redis - prefer fresh CoinAPI WSDS msnap
            ob_data = None
            import json

            msnap_data = self.redis.hgetall(f"msnap:coinapi_wsds:{symbol}") or {}
            orderbook_ts_ms = None
            if msnap_data:
                try:
                    now_ms = int(time.time() * 1000)
                    updated_ts_ms = int(float(msnap_data.get("updated_ts_ms", 0) or 0))
                    orderbook_ts_ms = updated_ts_ms or None
                    msnap_age_ms = now_ms - updated_ts_ms if updated_ts_ms else None
                except Exception:
                    msnap_age_ms = None

                # Treat CoinAPI WSDS as primary if it is updating in real time
                if msnap_age_ms is None or msnap_age_ms <= 2000:
                    # Convert msnap format to orderbook format
                    best_bid = float(msnap_data.get('best_bid_px', 0) or 0)
                    best_ask = float(msnap_data.get('best_ask_px', 0) or 0)
                    # Convert size-based depth to notional using mid if available
                    mid = (best_bid + best_ask) / 2 if best_bid > 0 and best_ask > 0 else 0.0
                    try:
                        spread_bps = ((best_ask - best_bid) / mid) * 10000 if mid > 0 else 0.0
                    except Exception:
                        spread_bps = 0.0
                    bid_sum_5 = float(msnap_data.get('book_bid_sum_5', 0) or 0)
                    ask_sum_5 = float(msnap_data.get('book_ask_sum_5', 0) or 0)
                    bid_depth = bid_sum_5 * mid if mid > 0 else 0.0
                    ask_depth = ask_sum_5 * mid if mid > 0 else 0.0
                    ob = {
                        'bid': best_bid,
                        'ask': best_ask,
                        'spread_bps': spread_bps,
                        'mid_px': mid,
                        'bid_depth': bid_depth,
                        'ask_depth': ask_depth,
                        'total_depth': bid_depth + ask_depth,
                        'source': 'coinapi_wsds'
                    }
                else:
                    # CoinAPI WSDS stale -> fall back to orderbook:top/orderbook
                    msnap_data = {}

            if not msnap_data:
                # Try different key patterns (orderbook:top:, orderbook:)
                for key_pattern in [f"orderbook:top:{symbol}", f"orderbook:{symbol}"]:
                    ob_data = self.redis.get(key_pattern)
                    if ob_data:
                        break

                if not ob_data:
                    # No order book data - allow but warn
                    return {
                        'should_block': False,
                        'should_warn': True,
                        'reason': f'No order book data for {symbol}'
                    }
                ob = json.loads(ob_data) if isinstance(ob_data, str) else ob_data
                try:
                    orderbook_ts_ms = int(ob.get("ts_ms") or ob.get("timestamp") or 0) or orderbook_ts_ms
                except Exception:
                    pass
            
            # Extract metrics - handle different data formats
            best_bid = float(ob.get('bid', ob.get('best_bid', 0)) or 0.0)
            best_ask = float(ob.get('ask', ob.get('best_ask', 0)) or 0.0)
            mid_price = float(ob.get('mid_px', 0) or 0.0)
            if mid_price <= 0 and best_bid > 0 and best_ask > 0:
                mid_price = (best_bid + best_ask) / 2

            spread_bps = float(ob.get('spread_bps', 0.0) or 0.0)
            if spread_bps <= 0 and best_bid > 0 and best_ask > 0 and mid_price > 0:
                spread_bps = ((best_ask - best_bid) / mid_price) * 10000

            if spread_bps <= 0:
                spread_pct = float(ob.get('spread_pct', 0.0) or 0.0)
                if spread_pct <= 0 and ob.get('spread') and mid_price > 0:
                    spread_pct = (float(ob.get('spread', 0) or 0.0) / mid_price) * 100
                spread_bps = float(spread_pct) * 100

            spread_pct = float(spread_bps) / 100.0
            
            bid_depth = ob.get('bid_depth', 0.0)  # USD depth on bid side
            ask_depth = ob.get('ask_depth', 0.0)  # USD depth on ask side
            total_depth = ob.get('total_depth', bid_depth + ask_depth)
            
            # If no depth data, assume sufficient (major pairs like BTC/ETH always have depth)
            if total_depth == 0 and symbol in ['BTCUSDT', 'ETHUSDT', 'SOLUSDT', 'XRPUSDT']:
                total_depth = 1000000  # Assume $1M depth for major pairs

            stress = ""
            structure = ""
            effective = ""

            # Throttled raw book diagnostics for pinpointing feed/math issues
            try:
                if not hasattr(self, "_last_liquidity_raw_log_ts"):
                    self._last_liquidity_raw_log_ts = {}
                now_ts = time.time()
                last_ts = float(self._last_liquidity_raw_log_ts.get(symbol, 0.0) or 0.0)
                age_ms = None
                if orderbook_ts_ms:
                    try:
                        age_ms = int(time.time() * 1000) - int(orderbook_ts_ms)
                    except Exception:
                        age_ms = None
                should_log = (
                    symbol in {'BTCUSDT', 'ETHUSDT', 'SOLUSDT', 'XRPUSDT'}
                    or spread_bps > 100
                    or total_depth < 50000
                )
                if should_log and (now_ts - last_ts) >= 30.0:
                    self._last_liquidity_raw_log_ts[symbol] = now_ts
                    logger.info(
                        "LIQUIDITY_RAW | symbol=%s | source=%s | bid=%s | ask=%s | mid=%s | spread_bps=%.3f | depth_usd=%.2f | age_ms=%s",
                        symbol,
                        ob.get('source'),
                        best_bid,
                        best_ask,
                        mid_price,
                        spread_bps,
                        total_depth,
                        age_ms,
                    )
            except Exception:
                pass

            # Hard sanity checks for book data quality (avoid misclassifying bad data as illiquid)
            majors = {'BTCUSDT', 'ETHUSDT', 'SOLUSDT', 'XRPUSDT'}
            if best_bid <= 0 or best_ask <= 0 or best_bid >= best_ask:
                return {
                    'should_block': True,
                    'should_warn': False,
                    'reason': f'BAD_BOOK_DATA (bid={best_bid} ask={best_ask})',
                    'spread_pct': spread_pct,
                    'depth_usd': total_depth,
                    'orderbook_ts_ms': orderbook_ts_ms,
                    'regime_stress': stress,
                    'regime_structure': structure,
                    'structural_regime': effective,
                }

            if symbol in majors and spread_bps > 200:
                return {
                    'should_block': True,
                    'should_warn': False,
                    'reason': f'BAD_BOOK_DATA (spread_bps {spread_bps:.1f} > 200)',
                    'spread_pct': spread_pct,
                    'depth_usd': total_depth,
                    'orderbook_ts_ms': orderbook_ts_ms,
                    'regime_stress': stress,
                    'regime_structure': structure,
                    'structural_regime': effective,
                }
            
            # Liquidity thresholds (tiered + regime-scaled)
            try:
                from config import (
                    LIQUIDITY_HARD_MIN_DEPTH_USD,
                    LIQUIDITY_MIN_DEPTH_USD_MAJOR,
                    LIQUIDITY_WARN_DEPTH_USD_MAJOR,
                    LIQUIDITY_MIN_DEPTH_USD_LARGE,
                    LIQUIDITY_WARN_DEPTH_USD_LARGE,
                    LIQUIDITY_MIN_DEPTH_USD_MID,
                    LIQUIDITY_WARN_DEPTH_USD_MID,
                    LIQUIDITY_MIN_DEPTH_USD_SMALL,
                    LIQUIDITY_WARN_DEPTH_USD_SMALL,
                    TIER3_SYMBOLS,
                )
            except Exception:
                LIQUIDITY_HARD_MIN_DEPTH_USD = 10000.0
                LIQUIDITY_MIN_DEPTH_USD_MAJOR = 250000.0
                LIQUIDITY_WARN_DEPTH_USD_MAJOR = 500000.0
                LIQUIDITY_MIN_DEPTH_USD_LARGE = 100000.0
                LIQUIDITY_WARN_DEPTH_USD_LARGE = 250000.0
                LIQUIDITY_MIN_DEPTH_USD_MID = 50000.0
                LIQUIDITY_WARN_DEPTH_USD_MID = 100000.0
                LIQUIDITY_MIN_DEPTH_USD_SMALL = 10000.0
                LIQUIDITY_WARN_DEPTH_USD_SMALL = 75000.0
                TIER3_SYMBOLS = []

            majors = {'BTCUSDT', 'ETHUSDT', 'SOLUSDT', 'XRPUSDT'}
            tier = "MID"
            if symbol in majors:
                tier = "MAJOR"
            elif str(symbol or "").upper().startswith("1000"):
                tier = "SMALL"
            elif symbol in (TIER3_SYMBOLS or []):
                tier = "SMALL"

            if tier == "MAJOR":
                MIN_DEPTH_USD = float(LIQUIDITY_MIN_DEPTH_USD_MAJOR)
                WARNING_DEPTH_USD = float(LIQUIDITY_WARN_DEPTH_USD_MAJOR)
            elif tier == "LARGE":
                MIN_DEPTH_USD = float(LIQUIDITY_MIN_DEPTH_USD_LARGE)
                WARNING_DEPTH_USD = float(LIQUIDITY_WARN_DEPTH_USD_LARGE)
            elif tier == "SMALL":
                MIN_DEPTH_USD = float(LIQUIDITY_MIN_DEPTH_USD_SMALL)
                WARNING_DEPTH_USD = float(LIQUIDITY_WARN_DEPTH_USD_SMALL)
            else:
                MIN_DEPTH_USD = float(LIQUIDITY_MIN_DEPTH_USD_MID)
                WARNING_DEPTH_USD = float(LIQUIDITY_WARN_DEPTH_USD_MID)

            MAX_SPREAD_PCT = 0.5  # Max 0.5% spread
            WARNING_SPREAD_PCT = 0.3  # Warn above 0.3% spread

            depth_mult = 1.0
            spread_mult = 1.0
            try:
                axes = (self._last_regime_axes.get(symbol, {}) or {})
            except Exception:
                axes = {}
            stress = str(axes.get("stress") or "").upper()
            structure = str(axes.get("structure") or "").upper()

            if stress in ("HIGH", "PANIC", "ELEVATED", "CRISIS"):
                depth_mult *= 0.6
                spread_mult *= 1.6
            elif stress in ("MEDIUM", "MODERATE"):
                depth_mult *= 0.8
                spread_mult *= 1.3

            if "TREND" in structure:
                depth_mult *= 1.1
                spread_mult *= 0.9
            elif "RANGE" in structure or "CHOP" in structure:
                depth_mult *= 0.9
                spread_mult *= 1.1

            try:
                structural = self._get_structural_regime_context(symbol)
                effective = str(structural.get("effective_regime") or "").upper()
                if effective in ("CAPITULATION", "POST_CRASH"):
                    depth_mult *= 0.5
                    spread_mult *= 1.7
                elif effective in ("BEAR_DAMAGE",):
                    depth_mult *= 0.7
                    spread_mult *= 1.4
                elif effective in ("RECOVERY",):
                    depth_mult *= 0.85
                    spread_mult *= 1.2
            except Exception:
                effective = ""

            hard_min_depth = max(float(LIQUIDITY_HARD_MIN_DEPTH_USD), 0.0)
            min_depth = max(hard_min_depth, MIN_DEPTH_USD * depth_mult)
            warn_depth = max(min_depth, WARNING_DEPTH_USD * depth_mult)
            max_spread = max(0.05, min(5.0, MAX_SPREAD_PCT * spread_mult))
            warn_spread = max(0.03, min(max_spread, WARNING_SPREAD_PCT * spread_mult))

            try:
                from config import (
                    LIQUIDITY_BORDERLINE_SMALL_RELAX_ENABLED,
                    LIQUIDITY_BORDERLINE_SMALL_HARD_FLOOR_USD,
                )
            except Exception:
                LIQUIDITY_BORDERLINE_SMALL_RELAX_ENABLED = False
                LIQUIDITY_BORDERLINE_SMALL_HARD_FLOOR_USD = 6000.0
            
            # Check depth
            _small_floor = max(1500.0, float(LIQUIDITY_BORDERLINE_SMALL_HARD_FLOOR_USD))
            if (
                tier == "SMALL"
                and bool(LIQUIDITY_BORDERLINE_SMALL_RELAX_ENABLED)
                and total_depth >= _small_floor
                and total_depth < hard_min_depth
                and spread_pct <= warn_spread
            ):
                return {
                    'should_block': False,
                    'should_warn': True,
                    'reason': (
                        f'BORDERLINE_DEPTH_SMALL tier={tier} depth ${total_depth:.0f} '
                        f'in [{_small_floor:.0f}, {hard_min_depth:.0f}) — size downgrade path'
                    ),
                    'spread_pct': spread_pct,
                    'depth_usd': total_depth,
                    'orderbook_ts_ms': orderbook_ts_ms,
                    'min_depth_usd': min_depth,
                    'warn_depth_usd': warn_depth,
                    'max_spread_pct': max_spread,
                    'warn_spread_pct': warn_spread,
                    'liq_tier': tier,
                    'regime_stress': stress,
                    'regime_structure': structure,
                    'structural_regime': effective,
                    'liquidity_borderline_downsize': True,
                }
            if total_depth < hard_min_depth:
                return {
                    'should_block': True,
                    'should_warn': False,
                    'reason': f'Low liquidity: depth ${total_depth:.0f} < ${hard_min_depth:.0f}',
                    'spread_pct': spread_pct,
                    'depth_usd': total_depth,
                    'orderbook_ts_ms': orderbook_ts_ms,
                    'min_depth_usd': min_depth,
                    'warn_depth_usd': warn_depth,
                    'max_spread_pct': max_spread,
                    'warn_spread_pct': warn_spread,
                    'liq_tier': tier,
                    'regime_stress': stress,
                    'regime_structure': structure,
                    'structural_regime': effective,
                }
            elif total_depth < min_depth:
                return {
                    'should_block': False,
                    'should_warn': True,
                    'reason': f'Low liquidity: depth ${total_depth:.0f} < ${min_depth:.0f}',
                    'spread_pct': spread_pct,
                    'depth_usd': total_depth,
                    'orderbook_ts_ms': orderbook_ts_ms,
                    'min_depth_usd': min_depth,
                    'warn_depth_usd': warn_depth,
                    'max_spread_pct': max_spread,
                    'warn_spread_pct': warn_spread,
                    'liq_tier': tier,
                    'regime_stress': stress,
                    'regime_structure': structure,
                    'structural_regime': effective,
                }
            elif total_depth < warn_depth:
                return {
                    'should_block': False,
                    'should_warn': True,
                    'reason': f'Reduced liquidity: depth ${total_depth:.0f} < ${warn_depth:.0f}',
                    'spread_pct': spread_pct,
                    'depth_usd': total_depth,
                    'orderbook_ts_ms': orderbook_ts_ms,
                    'min_depth_usd': min_depth,
                    'warn_depth_usd': warn_depth,
                    'max_spread_pct': max_spread,
                    'warn_spread_pct': warn_spread,
                    'liq_tier': tier,
                    'regime_stress': stress,
                    'regime_structure': structure,
                    'structural_regime': effective,
                }
            
            # Check spread
            if spread_pct > max_spread:
                return {
                    'should_block': True,
                    'should_warn': False,
                    'reason': f'Wide spread: {spread_pct:.3f}% > {max_spread:.3f}%',
                    'spread_pct': spread_pct,
                    'depth_usd': total_depth,
                    'orderbook_ts_ms': orderbook_ts_ms,
                    'min_depth_usd': min_depth,
                    'warn_depth_usd': warn_depth,
                    'max_spread_pct': max_spread,
                    'warn_spread_pct': warn_spread,
                    'liq_tier': tier,
                    'regime_stress': stress,
                    'regime_structure': structure,
                    'structural_regime': effective,
                }
            elif spread_pct > warn_spread:
                return {
                    'should_block': False,
                    'should_warn': True,
                    'reason': f'Elevated spread: {spread_pct:.3f}% > {warn_spread:.3f}%',
                    'spread_pct': spread_pct,
                    'depth_usd': total_depth,
                    'orderbook_ts_ms': orderbook_ts_ms,
                    'min_depth_usd': min_depth,
                    'warn_depth_usd': warn_depth,
                    'max_spread_pct': max_spread,
                    'warn_spread_pct': warn_spread,
                    'liq_tier': tier,
                    'regime_stress': stress,
                    'regime_structure': structure,
                    'structural_regime': effective,
                }
            
            return {
                'should_block': False,
                'should_warn': False,
                'reason': 'Liquidity within limits',
                'spread_pct': spread_pct,
                'depth_usd': total_depth,
                'orderbook_ts_ms': orderbook_ts_ms,
                'min_depth_usd': min_depth,
                'warn_depth_usd': warn_depth,
                'max_spread_pct': max_spread,
                'warn_spread_pct': warn_spread,
                'liq_tier': tier,
                'regime_stress': stress,
                'regime_structure': structure,
                'structural_regime': effective,
            }
            
        except Exception as e:
            logger.debug(f"Liquidity gate check error: {e}")
            return {
                'should_block': False,
                'should_warn': True,
                'reason': f'Error checking liquidity: {str(e)}'
            }
    
    def _get_all_positions(self) -> Dict[str, Dict]:
        """Get all current positions (trader + Binance)"""
        try:
            # Get trader-reported positions from Redis (executors)
            trader_positions = self.sync_trader_positions()
            
            # Merge with Binance positions (Binance overrides)
            all_positions = dict(trader_positions) if trader_positions else {}
            all_positions.update(self._real_positions)
            
            return all_positions
        except Exception as e:
            logger.debug(f"Error getting all positions: {e}")
            return self._real_positions or {}
    
    def _get_binance_positions(self) -> Dict[str, Dict]:
        """Get Binance positions for position-aware governance.
        
        Returns dict mapping symbol -> position data with at minimum 'positionAmt' field.
        Uses _get_all_positions() internally for consistency.
        """
        try:
            all_pos = self._get_all_positions() or {}
            # Convert to format expected by budget/cooldown checks
            result = {}
            for symbol, pos_data in all_pos.items():
                if isinstance(pos_data, dict):
                    # Already in dict format
                    result[symbol] = pos_data
                else:
                    # Wrap in dict
                    result[symbol] = {'positionAmt': pos_data}
            return result
        except Exception as e:
            logger.debug(f"[_get_binance_positions] Error: {e}")
            return {}
    
    def _apply_liquidation_aware_hedge(self, symbol: str, position: Dict, liquidation_distance: float,
                                      liquidation_buffer: float, all_positions: Dict) -> Optional[Dict]:
        """L.2) Liquidation-Aware Hedging - Automatic hedge logic when approaching liquidation
        
        Strategy:
        1. If position is < 2% from liquidation: Open opposite position in correlated asset
        2. If position is < 5% from liquidation: Reduce size and open partial hedge
        3. Use correlation matrix to find best hedge asset
        
        Returns:
            Dict with action/reason if hedge should be applied, None otherwise
        """
        try:
            current_side = position.get('side', 'LONG')
            opposite_side = 'SHORT' if current_side == 'LONG' else 'LONG'
            
            # Define correlation groups for hedge selection
            correlation_groups = {
                'majors': ['BTCUSDT', 'ETHUSDT'],
                'alt_layer1': ['SOLUSDT', 'AVAXUSDT', 'ADAUSDT'],
                'meme': ['DOGEUSDT', '1000SHIBUSDT', 'WIFUSDT'],
                'defi': ['LINKUSDT', 'UNIUSDT'],
            }
            
            # Find correlated symbols (same group, different symbol)
            symbol_group = None
            for group_name, symbols in correlation_groups.items():
                if symbol in symbols:
                    symbol_group = group_name
                    break
            
            if symbol_group is None:
                # No correlation group - use same symbol for hedge
                hedge_symbol = symbol
            else:
                # Find best hedge symbol (correlated but not same)
                hedge_candidates = [s for s in correlation_groups[symbol_group] if s != symbol]
                if hedge_candidates:
                    # Use first available candidate (could be enhanced with correlation score)
                    hedge_symbol = hedge_candidates[0]
                else:
                    hedge_symbol = symbol  # Fallback to same symbol
            
            # Determine hedge size based on liquidation distance
            position_notional = abs(position.get('notional', 0) or 0)
            
            if liquidation_distance < 2.0:  # Critical: < 2% from liquidation
                # Emergency: Open full opposite position in correlated asset
                hedge_size_pct = 1.0  # 100% hedge
                hedge_reason = f'CRITICAL: {liquidation_distance:.1f}% from liquidation - opening full {opposite_side} hedge in {hedge_symbol}'
                action_type = 'EMERGENCY_HEDGE'
            elif liquidation_distance < 5.0:  # Warning: < 5% from liquidation
                # Partial hedge: Open 50% opposite position
                hedge_size_pct = 0.5  # 50% hedge
                hedge_reason = f'WARNING: {liquidation_distance:.1f}% from liquidation - opening partial {opposite_side} hedge in {hedge_symbol}'
                action_type = 'PARTIAL_HEDGE'
            else:
                # Not close enough to trigger automatic hedge
                return None
            
            # Check if hedge already exists
            hedge_exists = False
            for pos_symbol, pos_data in all_positions.items():
                if pos_symbol == hedge_symbol and pos_data.get('side') == opposite_side:
                    hedge_exists = True
                    break
            
            if hedge_exists:
                # Hedge already exists - reduce current position size instead
                reduce_pct = 0.5 if liquidation_distance < 2.0 else 0.3
                return {
                    'action': f'REDUCE_{current_side}',
                    'reason': f'🚨 {action_type}: {liquidation_distance:.1f}% from liquidation - reducing {current_side} by {reduce_pct*100:.0f}% (hedge already active)',
                    'reduce_pct': reduce_pct,
                    'liquidation_distance': liquidation_distance
                }
            else:
                # Open new hedge position
                hedge_notional = position_notional * hedge_size_pct
                return {
                    'action': f'OPEN_{opposite_side}',
                    'symbol': hedge_symbol,  # Use correlated symbol for hedge
                    'reason': f'🚨 {action_type}: {liquidation_distance:.1f}% from liquidation - opening {opposite_side} hedge in {hedge_symbol} (${hedge_notional:.0f}, {hedge_size_pct*100:.0f}% of position)',
                    'hedge_size_pct': hedge_size_pct,
                    'hedge_notional': hedge_notional,
                    'liquidation_distance': liquidation_distance,
                    'correlation_group': symbol_group
                }
                
        except Exception as e:
            logger.debug(f"Liquidation-aware hedge error: {e}")
            return None
    
    def _check_rebalancing_needed(self, symbol: str, portfolio: Dict, market_state: Dict) -> Dict[str, Any]:
        """L.1) Dynamic Rebalancing - Event-driven portfolio rebalancing
        
        Triggers:
        1. Position growth exceeds target allocation
        2. Correlation shifts detected
        3. MASA risk signals indicate rebalancing needed
        4. Market regime change
        
        Returns:
            {
                'should_rebalance': bool,
                'reason': str,
                'rebalance_actions': list (optional)
            }
        """
        try:
            all_positions = self._get_all_positions()
            if not all_positions:
                return {'should_rebalance': False, 'reason': 'No positions to rebalance'}
            
            current_equity = portfolio.get('total_balance', 0)
            if current_equity <= 0:
                return {'should_rebalance': False, 'reason': 'Invalid equity'}
            
            # Check position size vs target allocation
            symbol_position = all_positions.get(symbol)
            if symbol_position:
                position_notional = abs(symbol_position.get('notional', 0) or 0)
                position_pct = (position_notional / current_equity) * 100 if current_equity > 0 else 0
                
                # Target allocation per symbol (max 15% per symbol)
                MAX_SYMBOL_ALLOCATION = 15.0
                if position_pct > MAX_SYMBOL_ALLOCATION:
                    return {
                        'should_rebalance': True,
                        'reason': f'{symbol} allocation {position_pct:.1f}% > {MAX_SYMBOL_ALLOCATION}% - reduce size',
                        'rebalance_actions': [{'symbol': symbol, 'action': 'REDUCE', 'target_pct': MAX_SYMBOL_ALLOCATION}]
                    }
            
            # Check for correlation shifts (simplified - would use actual correlation matrix)
            # If multiple correlated positions exceed group limit, suggest rebalancing
            correlation_groups = {
                'majors': ['BTCUSDT', 'ETHUSDT'],
                'alt_layer1': ['SOLUSDT', 'AVAXUSDT', 'ADAUSDT'],
            }
            
            for group_name, symbols in correlation_groups.items():
                if symbol in symbols:
                    group_exposure = sum(
                        abs(all_positions.get(s, {}).get('notional', 0) or 0)
                        for s in symbols
                    )
                    group_pct = (group_exposure / current_equity) * 100 if current_equity > 0 else 0
                    
                    MAX_GROUP_ALLOCATION = 30.0  # Max 30% per correlation group
                    if group_pct > MAX_GROUP_ALLOCATION:
                        return {
                            'should_rebalance': True,
                            'reason': f'Group {group_name} allocation {group_pct:.1f}% > {MAX_GROUP_ALLOCATION}% - rebalance needed',
                            'rebalance_actions': [{'group': group_name, 'action': 'REDUCE_GROUP', 'target_pct': MAX_GROUP_ALLOCATION}]
                        }
            
            # Check market regime change (would trigger rebalancing)
            regime = market_state.get('market_regime', 'normal')
            if regime in ['trending_bullish', 'trending_bearish']:
                # Trending markets: Rebalance to favor trending positions
                return {
                    'should_rebalance': False,  # Not blocking, but could adjust
                    'reason': f'Market regime: {regime} - consider rebalancing to trend'
                }
            
            return {'should_rebalance': False, 'reason': 'No rebalancing needed'}
            
        except Exception as e:
            logger.debug(f"Rebalancing check error: {e}")
            return {'should_rebalance': False, 'reason': f'Error: {str(e)}'}
    
    def _check_margin_allocation(self, symbol: str, portfolio: Dict, confidence: float) -> Dict[str, Any]:
        """L.3) Optimal Margin Utilization - Dynamic margin allocation
        
        Strategy:
        1. Keep 20% buffer for opportunities
        2. Reallocate from underperforming to trending assets
        3. Allocate more margin to high-confidence signals
        
        Returns:
            {
                'should_adjust': bool,
                'reason': str,
                'recommended_allocation': float (optional)
            }
        """
        try:
            current_equity = portfolio.get('total_balance', 0)
            margin_used = portfolio.get('total_margin_used', 0)
            margin_utilization = portfolio.get('margin_utilization_pct', 0)
            
            if current_equity <= 0:
                return {'should_adjust': False, 'reason': 'Invalid equity'}
            
            # Target margin utilization (80% max, keep 20% buffer)
            TARGET_MAX_UTILIZATION = 80.0
            IDEAL_UTILIZATION = 70.0  # Ideal utilization level
            
            # Check if we're over-utilized
            if margin_utilization > TARGET_MAX_UTILIZATION:
                return {
                    'should_adjust': True,
                    'reason': f'Margin utilization {margin_utilization:.1f}% > {TARGET_MAX_UTILIZATION}% - reduce exposure',
                    'recommended_allocation': IDEAL_UTILIZATION
                }
            
            # Check if we have room for high-confidence signals
            available_margin = current_equity - margin_used
            available_pct = (available_margin / current_equity) * 100 if current_equity > 0 else 0
            
            # High confidence signals (95%+) can use more margin
            if confidence >= 0.95 and available_pct < 20.0:
                return {
                    'should_adjust': True,
                    'reason': f'High confidence signal ({confidence:.1%}) but only {available_pct:.1f}% margin available - consider closing underperformers',
                    'recommended_allocation': min(IDEAL_UTILIZATION, margin_utilization + 10.0)
                }
            
            # Check for underperforming positions that could be closed to free margin
            all_positions = self._get_all_positions()
            underperformers = []
            for pos_symbol, pos_data in all_positions.items():
                pnl_pct = pos_data.get('pnl_percentage', 0)
                duration_hours = pos_data.get('duration_hours', 0)
                # Underperforming: negative PnL and held > 4 hours
                if pnl_pct < -2.0 and duration_hours > 4:
                    underperformers.append({
                        'symbol': pos_symbol,
                        'pnl_pct': pnl_pct,
                        'notional': abs(pos_data.get('notional', 0) or 0)
                    })
            
            if underperformers and available_pct < 15.0:
                total_underperformer_margin = sum(p['notional'] for p in underperformers)
                freed_pct = (total_underperformer_margin / current_equity) * 100 if current_equity > 0 else 0
                return {
                    'should_adjust': True,
                    'reason': f'Low margin availability ({available_pct:.1f}%) - {len(underperformers)} underperforming positions could free {freed_pct:.1f}%',
                    'recommended_allocation': margin_utilization - freed_pct,
                    'underperformers': underperformers
                }
            
            return {'should_adjust': False, 'reason': 'Margin allocation optimal'}
            
        except Exception as e:
            logger.debug(f"Margin allocation check error: {e}")
            return {'should_adjust': False, 'reason': f'Error: {str(e)}'}
    
    def _check_and_adjust_gpu_scaling(self, gpu_stats: Dict) -> None:
        """B.2) GPU Auto-Scaling - Auto-tune n_envs when GPU underutilized (safe mode only)
        
        Strategy:
        - Monitor GPU utilization after training loops
        - If GPU < 50% utilized for 3+ consecutive loops, increase n_envs
        - If GPU > 90% utilized, decrease n_envs
        - Only in safe mode (ENABLE_AUTO_GPU_SCALE=1)
        """
        try:
            enable_auto_scale = os.getenv("ENABLE_AUTO_GPU_SCALE", "0") == "1"
            if not enable_auto_scale:
                return  # Feature disabled
            
            # Only adjust in training mode, not predict mode
            if not hasattr(self, 'ppo_model') or self.ppo_model is None:
                return  # Not in training mode
            
            gpu_util = gpu_stats.get('gpu_util', 0.0) if isinstance(gpu_stats, dict) else 0.0
            vram_util = gpu_stats.get('vram_util', 0.0) if isinstance(gpu_stats, dict) else 0.0
            
            # Initialize tracking
            if not hasattr(self, '_gpu_scaling_history'):
                self._gpu_scaling_history = []
            
            # Record current utilization
            self._gpu_scaling_history.append({
                'gpu_util': gpu_util,
                'vram_util': vram_util,
                'n_envs': self.config.n_envs
            })
            
            # Keep only last 5 loops
            if len(self._gpu_scaling_history) > 5:
                self._gpu_scaling_history.pop(0)
            
            # Need at least 3 data points
            if len(self._gpu_scaling_history) < 3:
                return
            
            # Calculate average GPU utilization over last 3 loops
            avg_gpu_util = sum(h['gpu_util'] for h in self._gpu_scaling_history[-3:]) / 3
            avg_vram_util = sum(h['vram_util'] for h in self._gpu_scaling_history[-3:]) / 3
            
            # Thresholds
            LOW_UTILIZATION = 0.50  # Below 50% = underutilized
            HIGH_UTILIZATION = 0.90  # Above 90% = overutilized
            MAX_VRAM_UTIL = 0.85  # Don't scale up if VRAM > 85%
            MIN_ENVS = 8  # Minimum environments
            MAX_ENVS = 64  # Maximum environments (safety limit)
            
            current_n_envs = self.config.n_envs
            
            # Check if we should scale up (GPU underutilized, VRAM has room)
            if avg_gpu_util < LOW_UTILIZATION and avg_vram_util < MAX_VRAM_UTIL:
                if current_n_envs < MAX_ENVS:
                    # Scale up by 25% (rounded)
                    new_n_envs = min(MAX_ENVS, int(current_n_envs * 1.25))
                    if new_n_envs > current_n_envs:
                        logger.info(f"📈 [GPU-SCALE] GPU underutilized ({avg_gpu_util*100:.1f}%) - scaling up: {current_n_envs} → {new_n_envs} envs")
                        self.config.n_envs = new_n_envs
                        # Note: Will take effect on next training loop (vec_env recreation)
                        logger.warning(f"⚠️ [GPU-SCALE] New n_envs={new_n_envs} will apply on next training loop")
            
            # Check if we should scale down (GPU overutilized or VRAM high)
            elif avg_gpu_util > HIGH_UTILIZATION or avg_vram_util > MAX_VRAM_UTIL:
                if current_n_envs > MIN_ENVS:
                    # Scale down by 20% (rounded)
                    new_n_envs = max(MIN_ENVS, int(current_n_envs * 0.8))
                    if new_n_envs < current_n_envs:
                        logger.warning(f"📉 [GPU-SCALE] GPU overutilized ({avg_gpu_util*100:.1f}%) or VRAM high ({avg_vram_util*100:.1f}%) - scaling down: {current_n_envs} → {new_n_envs} envs")
                        self.config.n_envs = new_n_envs
                        logger.warning(f"⚠️ [GPU-SCALE] New n_envs={new_n_envs} will apply on next training loop")
            
        except Exception as e:
            logger.debug(f"GPU auto-scaling check error: {e}")
    
    def _update_drawdown_tracking(self):
        """Update drawdown tracking"""
        try:
            # Get current equity
            current_equity = self._real_balance + sum(
                pos.get('unrealized_pnl', 0) for pos in self._real_positions.values()
            )
            
            # Update peak
            if current_equity > self._equity_peak:
                self._equity_peak = current_equity
            
            # Calculate drawdown
            if self._equity_peak > 0:
                self._current_drawdown_pct = ((self._equity_peak - current_equity) / self._equity_peak) * 100
            else:
                self._current_drawdown_pct = 0.0
                
        except Exception as e:
            logger.debug(f"Drawdown tracking error: {e}")
    
