    def _calculate_liquidity_aware_size(self, symbol: str, base_size: float) -> float:
        """J.2) Liquidity-Aware Position Sizing"""
        try:
            # Get order book depth from Redis
            ob_key = f"orderbook:{symbol}"
            ob_data = self.redis.get(ob_key)
            if ob_data:
                import json
                ob = json.loads(ob_data) if isinstance(ob_data, str) else ob_data
                depth = ob.get('total_depth', 100000)
                spread = ob.get('spread_pct', 0.001)
                
                # Reduce size if low liquidity
                if depth < 50000:  # Less than $50k depth
                    return base_size * 0.5
                if spread > 0.003:  # Spread > 0.3%
                    return base_size * 0.7
            return base_size
        except:
            return base_size
    
    def _calculate_performance_based_size(self, symbol: str, base_size: float) -> float:
        """J.3) Performance-Based Position Sizing (Kelly criterion style)"""
        try:
            # Track win rate and avg win/loss
            if not hasattr(self, '_trade_performance'):
                self._trade_performance = {}
            
            perf = self._trade_performance.get(symbol, {'wins': 0, 'losses': 0, 'total_win': 0, 'total_loss': 0})
            
            if perf['wins'] + perf['losses'] > 0:
                win_rate = perf['wins'] / (perf['wins'] + perf['losses'])
                avg_win = perf['total_win'] / perf['wins'] if perf['wins'] > 0 else 1.0
                avg_loss = abs(perf['total_loss'] / perf['losses']) if perf['losses'] > 0 else 1.0
                
                # Kelly fraction
                kelly = (win_rate * avg_win - (1 - win_rate) * avg_loss) / avg_win if avg_win > 0 else 0.0
                kelly = max(0.0, min(0.02, kelly))  # Clamp to 2% max
                
                # Adjust base size
                return base_size * (1 + kelly * 10)  # Scale Kelly
            return base_size
        except:
            return base_size
    
    # K) Adaptive Stop Methods
    def _calculate_volatility_based_stop(self, symbol: str, entry_price: float, side: str) -> float:
        """K.1) Volatility-Based Stop-Loss"""
        try:
            # Get volatility from features (simplified - would use ATR)
            volatility = 0.01  # Default 1%
            # Widen baseline stop to avoid noise; ensure minimum effective vol
            effective_vol = max(volatility, 0.015)
            
            if effective_vol < 0.02:  # Low volatility
                stop_multiplier = 3.0
            elif effective_vol < 0.04:  # Medium volatility
                stop_multiplier = 4.0
            else:  # High volatility
                stop_multiplier = 5.0
            
            if side == 'LONG':
                stop_price = entry_price * (1 - effective_vol * stop_multiplier)
            else:  # SHORT
                stop_price = entry_price * (1 + effective_vol * stop_multiplier)
            
            logger.debug(
                f"[STOP] {symbol} side={side} vol={effective_vol:.3f}x{stop_multiplier:.1f} -> stop={stop_price:.4f}"
            )
            return stop_price
        except:
            return entry_price * 0.95 if side == 'LONG' else entry_price * 1.05
    
    def _update_trailing_stop(self, symbol: str, current_price: float, entry_price: float,
                             side: str, current_stop: float) -> float:
        """K.2) Trailing Stop Mechanism with K.3) Liquidity-Aware Exits
        
        DYNAMIC TRAILING based on:
        - ATR (Average True Range) - wider trail in volatile markets
        - Liquidity depth - wider trail in thin markets
        - Profit level - tighter trail as profit increases
        """
        try:
            # K.3) Check liquidity and adjust stop width accordingly
            liquidity_adjustment = self._get_liquidity_stop_adjustment(symbol)
            
            # DYNAMIC: Get ATR-based volatility for this symbol
            atr_pct = self._get_symbol_atr_pct(symbol)
            
            # DYNAMIC activation threshold: 2x ATR minimum profit before trailing
            # In volatile markets (ATR 3%), need 6% profit before trailing
            # In calm markets (ATR 0.5%), need 1% profit before trailing
            # Minimum 1.5%, Maximum 8% to prevent extreme values
            activate_at = max(0.015, min(0.08, atr_pct * 2.0))
            
            if side == 'LONG' and current_price > entry_price:
                # Trail upward
                profit_pct = (current_price - entry_price) / entry_price
                if profit_pct >= activate_at:
                    # DYNAMIC trail width: 1.5x ATR, adjusted for liquidity
                    # This means trail distance adapts to current volatility
                    base_trail_pct = max(0.005, min(0.03, atr_pct * 1.5))
                    
                    # Tighten trail as profit grows (lock in more gains)
                    if profit_pct > 0.10:  # >10% profit - tighter trail
                        base_trail_pct *= 0.7
                    elif profit_pct > 0.06:  # >6% profit - slightly tighter
                        base_trail_pct *= 0.85
                    
                    trail_pct = base_trail_pct * liquidity_adjustment
                    new_stop = current_price * (1 - trail_pct)
                    updated_stop = max(current_stop, new_stop)  # Never move stop down
                    logger.info(
                        f"[TRAIL_DYNAMIC] {symbol} LONG | profit={profit_pct*100:.1f}% | "
                        f"ATR={atr_pct*100:.2f}% | activate_at={activate_at*100:.1f}% | "
                        f"trail={trail_pct*100:.2f}% | stop={updated_stop:.4f}"
                    )
                    return updated_stop
            elif side == 'SHORT' and current_price < entry_price:
                # Trail downward
                profit_pct = (entry_price - current_price) / entry_price
                if profit_pct >= activate_at:
                    # DYNAMIC trail width: 1.5x ATR, adjusted for liquidity
                    base_trail_pct = max(0.005, min(0.03, atr_pct * 1.5))
                    
                    # Tighten trail as profit grows
                    if profit_pct > 0.10:
                        base_trail_pct *= 0.7
                    elif profit_pct > 0.06:
                        base_trail_pct *= 0.85
                    
                    trail_pct = base_trail_pct * liquidity_adjustment
                    new_stop = current_price * (1 + trail_pct)
                    adjusted_stop = min(current_stop, new_stop) if current_stop > 0 else new_stop
                    
                    # K.4) Apply multi-signal stop adjustment
                    adjusted_stop = self._adjust_stop_with_multi_signals(symbol, adjusted_stop, entry_price, side, current_price)
                    logger.info(
                        f"[TRAIL_DYNAMIC] {symbol} SHORT | profit={profit_pct*100:.1f}% | "
                        f"ATR={atr_pct*100:.2f}% | activate_at={activate_at*100:.1f}% | "
                        f"trail={trail_pct*100:.2f}% | stop={adjusted_stop:.4f}"
                    )
                    return adjusted_stop
            
            return current_stop
        except Exception as e:
            logger.debug(f"[TRAIL_DYNAMIC] Error for {symbol}: {e}")
            return current_stop
    
    def _get_symbol_atr_pct(self, symbol: str) -> float:
        """Get ATR as percentage of price for dynamic trailing calculations.
        
        Returns typical volatility for this symbol to size trails appropriately.
        """
        try:
            symbol = str(symbol or "").upper().strip()
            if not symbol:
                return 0.015
            redis_client = getattr(self, 'redis', None) or getattr(self, '_signal_redis', None)
            if not redis_client:
                return 0.015  # Default 1.5% if no Redis
            
            # Try to get ATR from msnap or TA data
            msnap_key = f"msnap:coinapi_wsds:{symbol}"
            msnap_data = redis_client.hgetall(msnap_key)
            
            if msnap_data:
                # Decode if bytes
                if isinstance(list(msnap_data.keys())[0], bytes):
                    msnap_data = {k.decode(): v.decode() for k, v in msnap_data.items()}
                
                # Try to get ATR from msnap
                atr_pct = float(msnap_data.get('atr_pct', 0) or 0)
                if atr_pct > 0:
                    return atr_pct

            # Preferred (2026): unified_features contains normalized ATR% (NATR).
            try:
                uf_key = f"unified_features:{symbol}:5m"
                uf = redis_client.hgetall(uf_key) or {}
                if uf:
                    if isinstance(list(uf.keys())[0], bytes):
                        uf = {k.decode(): v.decode() for k, v in uf.items()}
                    _atr_pct = float(uf.get("atr_pct", 0) or 0)
                    if _atr_pct > 0:
                        return _atr_pct
                    for k in (
                        "ind_ta_NATR_21_5m",
                        f"ind_ind_{symbol}_ta_NATR_21_5m",
                        "ind_ta_NATR_14_5m",
                        f"ind_ind_{symbol}_ta_NATR_14_5m",
                    ):
                        try:
                            v = float(uf.get(k, 0) or 0)
                            if v > 0:
                                return max(0.0005, min(0.25, v / 100.0))
                        except Exception:
                            continue
            except Exception:
                pass
            
            # Fallback: Try TA features
            ta_key = f"ta:features:{symbol}:5m"
            ta_data = redis_client.hgetall(ta_key)
            if ta_data:
                if isinstance(list(ta_data.keys())[0], bytes):
                    ta_data = {k.decode(): v.decode() for k, v in ta_data.items()}
                
                atr_14 = float(ta_data.get('ta_ATR_14_5m', 0) or 0)
                price = float(ta_data.get('close', ta_data.get('price', 0)) or 0)
                
                if atr_14 > 0 and price > 0:
                    return atr_14 / price
            
            # Symbol-specific defaults based on typical volatility
            if 'BTC' in symbol:
                return 0.012  # BTC typically 1.2% ATR
            elif 'ETH' in symbol:
                return 0.015  # ETH typically 1.5% ATR
            elif 'SOL' in symbol or 'AVAX' in symbol:
                return 0.025  # Alts typically 2.5% ATR
            else:
                return 0.02  # Default 2% for other alts
                
        except Exception:
            return 0.015  # Safe default
    
    def _get_liquidity_stop_adjustment(self, symbol: str) -> float:
        """K.3) Liquidity-Aware Exits - Widen stops in low-liquidity conditions
        
        Returns:
            float: Multiplier for stop width (1.0 = normal, >1.0 = wider stops)
        """
        try:
            # Get order book data
            ob_key = f"orderbook:{symbol}"
            ob_data = self.redis.get(ob_key)
            
            if not ob_data:
                # No data - use conservative wider stops
                return 1.5
            
            import json
            ob = json.loads(ob_data) if isinstance(ob_data, str) else ob_data
            
            total_depth = ob.get('total_depth', 0.0)
            spread_pct = ob.get('spread_pct', 0.0)
            
            # Liquidity thresholds
            LOW_LIQUIDITY_DEPTH = 100000.0  # Below $100k = low liquidity
            VERY_LOW_LIQUIDITY_DEPTH = 50000.0  # Below $50k = very low
            WIDE_SPREAD = 0.3  # Above 0.3% = wide spread
            
            # Adjust multiplier based on liquidity
            if total_depth < VERY_LOW_LIQUIDITY_DEPTH or spread_pct > WIDE_SPREAD:
                # Very low liquidity - widen stops by 2x
                return 2.0
            elif total_depth < LOW_LIQUIDITY_DEPTH:
                # Low liquidity - widen stops by 1.5x
                return 1.5
            else:
                # Normal liquidity
                return 1.0
                
        except Exception as e:
            logger.debug(f"Liquidity stop adjustment error: {e}")
            return 1.0  # Default to normal
    
    def _compute_liquidation_proximity(self, symbol: str, position: dict) -> Dict[str, Any]:
        """D) Compute liquidation proximity for a position
        
        Returns:
            {
                'distance_pct': float,  # Distance to liquidation as %
                'risk_bucket': str,      # SAFE, WARNING, DANGER
                'liquidation_price': float
            }
        """
        try:
            if not position or position.get('quantity', 0) == 0:
                return {'distance_pct': None, 'risk_bucket': 'NONE', 'liquidation_price': None}
            
            # Get current price
            current_price = self._get_price(symbol)
            if not current_price or current_price <= 0:
                return {'distance_pct': None, 'risk_bucket': 'UNKNOWN', 'liquidation_price': None}
            
            # Get position details
            side = position.get('side', 'LONG')
            entry_price = position.get('entry_price', current_price)
            leverage = position.get('leverage', 1.0)
            quantity = abs(position.get('quantity', 0))

            # Prefer Binance-provided liquidationPrice (cross/multi-asset aware) if present.
            liquidation_price = 0.0
            try:
                liquidation_price = float(position.get('liquidation_price') or position.get('liquidationPrice') or 0.0)
            except Exception:
                liquidation_price = 0.0

            if liquidation_price <= 0 or current_price <= 0:
                # Do not guess liquidation in cross/multi-asset mode; report unknown.
                return {'distance_pct': None, 'risk_bucket': 'UNKNOWN', 'liquidation_price': None}

            side_u = str(side or "LONG").upper()
            if side_u == 'LONG':
                distance_pct = ((current_price - liquidation_price) / current_price) * 100
            else:  # SHORT
                distance_pct = ((liquidation_price - current_price) / current_price) * 100
            
            # Risk bucket
            if distance_pct > 5.0:
                risk_bucket = 'SAFE'
            elif distance_pct > 2.0:
                risk_bucket = 'WARNING'
            else:
                risk_bucket = 'DANGER'
            
            return {
                'distance_pct': round(distance_pct, 2),
                'risk_bucket': risk_bucket,
                'liquidation_price': round(liquidation_price, 2)
            }
            
        except Exception as e:
            logger.debug(f"Liquidation proximity calculation error: {e}")
            return {'distance_pct': None, 'risk_bucket': 'ERROR', 'liquidation_price': None}
    
    def _update_drawdown_tracking(self):
        """Update drawdown tracking"""
        try:
            # Get current equity
            current_equity = self._real_balance + sum(
                pos.get('unrealized_pnl', 0) for pos in self._real_positions.values()
            )
            
            # Update peak
            if current_equity > self._equity_peak:
                self._equity_peak = current_equity
            
            # Calculate drawdown
            if self._equity_peak > 0:
                self._current_drawdown_pct = ((self._equity_peak - current_equity) / self._equity_peak) * 100
            else:
                self._current_drawdown_pct = 0.0
                
        except Exception as e:
            logger.debug(f"Drawdown tracking error: {e}")
    
    def _blend_masa_ppo_logits(self, ppo_logits, masa_logits, masa_weight=None, return_tensor=True, symbol=None):
        """Blend PPO and MASA logits with NaN/inf safety and regime-aware dynamic weights.
        
        When symbol is provided and REGIME_BLEND_ENABLED, adjusts MASA weight based on
        the market regime computed by _compute_regime_axes():
          - TREND_UP / TREND_DOWN → 'trending' → MASA weight × REGIME_BLEND_TRENDING_MULT (1.2x)
          - CHOP + HIGH stress   → 'volatile' → MASA weight × REGIME_BLEND_VOLATILE_MULT (0.7x)
          - PANIC                → 'crisis'   → MASA weight × REGIME_BLEND_CRISIS_MULT (0.5x)
          - NORMAL / UNKNOWN     → 'normal'   → MASA weight unchanged
        """
        if masa_weight is None:
            masa_weight = getattr(self.config, 'masa_weight', 0.3)

        def _safe_tensor(x, like=None):
            if isinstance(x, torch.Tensor):
                t = x
            else:
                target_device = like.device if isinstance(like, torch.Tensor) else None
                t = torch.tensor(x, dtype=torch.float32, device=target_device)
            if isinstance(like, torch.Tensor) and isinstance(t, torch.Tensor) and t.device != like.device:
                t = t.to(like.device)
            t = torch.nan_to_num(t, nan=0.0, posinf=5.0, neginf=-5.0)
            return t.clamp(-5.0, 5.0)

        ppo_t = _safe_tensor(ppo_logits)
        masa_t = _safe_tensor(masa_logits, like=ppo_t)

        # ── G.1) Regime-Aware Dynamic Blending ──
        # Map regime axes (from _compute_regime_axes) → blending category → MASA multiplier.
        # When symbol is None (training batch path), defaults to 'normal' (no regime adjustment).
        regime = 'normal'
        regime_label = 'NORMAL'
        try:
            from config import REGIME_BLEND_ENABLED
            if REGIME_BLEND_ENABLED and symbol and hasattr(self, '_last_regime_axes'):
                axes = self._last_regime_axes.get(symbol)
                if axes and isinstance(axes, dict):
                    regime_label = str(axes.get('label') or 'NORMAL').upper()
                    stress = str(axes.get('stress') or 'LOW').upper()

                    if regime_label in ('TREND_UP', 'TREND_DOWN'):
                        regime = 'trending'
                    elif regime_label == 'PANIC':
                        regime = 'crisis'
                    elif regime_label == 'CHOP' and stress == 'HIGH':
                        regime = 'volatile'
                    elif regime_label == 'CHOP':
                        regime = 'volatile'  # CHOP with any stress → volatile (conservative)
                    else:
                        regime = 'normal'
        except Exception:
            regime = 'normal'

        adjusted_masa_weight = float(masa_weight)
        try:
            from config import REGIME_BLEND_ENABLED, REGIME_BLEND_TRENDING_MULT, REGIME_BLEND_VOLATILE_MULT, REGIME_BLEND_CRISIS_MULT
            if REGIME_BLEND_ENABLED:
                if regime == 'trending':
                    adjusted_masa_weight *= float(REGIME_BLEND_TRENDING_MULT)
                elif regime == 'volatile':
                    adjusted_masa_weight *= float(REGIME_BLEND_VOLATILE_MULT)
                elif regime == 'crisis':
                    adjusted_masa_weight *= float(REGIME_BLEND_CRISIS_MULT)
        except Exception:
            pass
        adjusted_masa_weight = max(0.0, min(0.9, adjusted_masa_weight))

        # Avoid Python-side GPU sync; compute a tensor mask for "MASA active".
        if masa_t.ndim >= 2:
            _reduce_dims = tuple(range(1, masa_t.ndim))
            _finite_all = torch.isfinite(masa_t).all(dim=_reduce_dims, keepdim=True)
            _max_abs = masa_t.abs().amax(dim=_reduce_dims, keepdim=True)
            masa_active = _finite_all & (_max_abs > 1e-6)
        elif masa_t.ndim == 1:
            masa_active = torch.isfinite(masa_t).all() & (masa_t.abs().max() > 1e-6)
        else:
            masa_active = torch.isfinite(masa_t) & (masa_t.abs() > 1e-6)

        w = torch.as_tensor(adjusted_masa_weight, device=ppo_t.device, dtype=ppo_t.dtype)
        w_eff = w * masa_active.to(dtype=ppo_t.dtype)
        alpha_t = 1.0 - w_eff
        alpha = 1.0 - adjusted_masa_weight  # float for logs only
        tau = 1.0  # Temperature scaling

        blended = (alpha_t * ppo_t + w_eff * masa_t) / tau

        # Telemetry: log regime-adjusted blending (periodic, not every call)
        try:
            if symbol and regime != 'normal':
                logger.info(f"[REGIME_BLEND] {symbol}: regime={regime} label={regime_label} masa_w={adjusted_masa_weight:.3f} ppo_w={alpha:.3f}")
            elif logger.isEnabledFor(logging.DEBUG):
                logger.debug(f"MASA blending: α={alpha:.3f}, τ={tau}, masa_weight={adjusted_masa_weight:.3f}, regime={regime}")
        except Exception:
            pass

        # Redis telemetry (optional, when ENABLE_BLEND_TELEMETRY=1)
        try:
            if os.getenv("ENABLE_BLEND_TELEMETRY", "0") == "1" and symbol:
                redis_client = getattr(self, '_signal_redis', None) or getattr(self, 'redis', None)
                if redis_client:
                    import json as _json_blend
                    telemetry = {
                        'ppo_weight': float(alpha),
                        'masa_weight': float(adjusted_masa_weight),
                        'regime': regime,
                        'regime_label': regime_label,
                        'symbol': symbol,
                        'timestamp': int(time.time() * 1000)
                    }
                    redis_client.setex(f'rl:blend_telemetry:{symbol}', 60, _json_blend.dumps(telemetry))
        except Exception:
            pass

        if not return_tensor and isinstance(blended, torch.Tensor):
            return blended.item() if blended.numel() == 1 else float(blended.mean())

        return blended
    
    def _log_contract(self, event: str, **fields):
        """
        Phase 0: Structured logger wrapper for profitability governance proof logs.
        Provides consistent formatting for grep-able contract events without changing existing logs.
        
        Args:
            event: Event type (e.g., 'TF_STACK', 'ACTION_AGGREGATION', 'BUDGET_BLOCK')
            **fields: Additional key-value pairs for structured logging
        """
        field_str = " | ".join(f"{k}={v}" for k, v in fields.items())
        log_msg = f"[{event}] | {field_str}" if field_str else f"[{event}]"
        logger.info(log_msg)
    
    def setup_gpu(self):
        """Setup and validate GPU environment"""
        # TODO: use CONTINUOUS chunks and never close env; keep your progress/fps prints
        # TODO: force sm_120 support (PTX fallback if needed); log CC
        if not torch.cuda.is_available():
            logger.error("❌ CUDA not available! Training will be suboptimal on CPU")
            self.config.device = 'cpu'
            self._device = torch.device('cpu')  # FIX: Set _device for MASA safe forward
            return
        
        # FIX: Initialize _device early for MASA and other GPU operations
        self._device = torch.device('cuda')
        
        device_name = torch.cuda.get_device_name()
        compute_capability = torch.cuda.get_device_capability(0)
        logger.info(f"🚀 GPU detected: {device_name}")
        logger.info(f"CUDA available={torch.cuda.is_available()} device={device_name} cc={compute_capability}")
        
        # Validate sm_120 (RTX 5080 Blackwell) support
        if compute_capability == (12, 0):
            logger.info("🎉 RTX 5080 SM 120 (Blackwell) detected and supported!")
        elif compute_capability[0] >= 12:
            logger.info(f"🚀 Blackwell architecture detected: sm_{compute_capability[0]}{compute_capability[1]}")
        else:
            logger.warning(f"⚠️ Older GPU architecture: sm_{compute_capability[0]}{compute_capability[1]}")
        
        # RTX 5080 specific optimizations
        if "RTX 5080" in device_name:
            logger.info("🔥 RTX 5080 detected - applying aggressive optimizations")
            setup_gpu_memory_optimization()
        
        # Validate GPU memory
        total_memory = torch.cuda.get_device_properties(0).total_memory / 1e9
        logger.info(f"📊 Total GPU memory: {total_memory:.1f} GB")
        
        # P1-7: GPU OPTIMIZATION - Use configured n_envs for maximum GPU utilization
        # RTX 5080 has 16GB VRAM - can handle 64+ environments efficiently
        if total_memory >= 15.0:
            # High-end GPU (RTX 4090, 5080, etc.) - maximize utilization
            logger.info("🚀 High-end GPU detected (>=15GB) - using full n_envs for GPU saturation")
            logger.info(f"   n_envs: {self.config.n_envs}, batch_size: {self.config.batch_size}")
            logger.info(f"   Samples per rollout: {self.config.n_envs * self.config.n_steps:,}")
        elif total_memory >= 8.0:
            # Mid-range GPU - moderate optimization
            logger.info("📊 Mid-range GPU (8-15GB) - using balanced settings")
            self.config.n_envs = min(self.config.n_envs, 48)  # Cap at 48 envs
            self.config.batch_size = min(self.config.batch_size, 1024)  # Cap batch
        else:
            # Low-end GPU - conservative settings (keep user n_envs setting)
            logger.warning("⚠️ Limited GPU memory (<8GB) - using conservative batch size")
            # Don't override n_envs - respect user/CLI settings for debugging
            self.config.batch_size = min(self.config.batch_size, 512)  # Cap batch
        
        logger.info(f"🔥 GPU Training Config: {self.config.n_envs} envs × {self.config.n_steps} steps = {self.config.n_envs * self.config.n_steps:,} samples/rollout")

        # ── Always-on batch geometry audit (runs every startup path) ──
        _rs = int(self.config.n_envs) * int(self.config.n_steps)
        _bs = int(self.config.batch_size)
        if _rs > 0 and _bs > 0 and _rs % _bs != 0:
            # Auto-fix: find largest clean divisor <= requested batch_size, floor 128
            _best = 128
            for _d in range(_bs, 127, -1):
                if _rs % _d == 0:
                    _best = _d
                    break
            logger.warning(f"[BATCH-GUARD] rollout={_rs} bs {_bs}->{_best} (clean divisor)")
            self.config.batch_size = _best
            _bs = _best
        _nmb = _rs // _bs if _bs > 0 else 0
        logger.info(f"[BATCH-GUARD_OK] rollout={_rs} bs={_bs} minibatches={_nmb}")
    
