    def detect_market_maker_patterns(self, symbol: str, prices: List[float], volumes: List[float]) -> Dict[str, Any]:
        """Detect market maker manipulation patterns"""
        patterns = []
        manipulation_score = 0.0
        
        try:
            if len(prices) < 10:
                return {'patterns': patterns, 'manipulation_score': 0.0}
            
            # Pattern 1: Fake pump then dump (or vice versa)
            price_changes = [(prices[i] - prices[i+1]) / prices[i+1] * 100 for i in range(len(prices)-1)]
            
            # Look for sudden reversal patterns
            for i in range(len(price_changes) - 3):
                move1 = price_changes[i]
                move2 = price_changes[i+1]
                move3 = price_changes[i+2]
                
                # Strong move followed by immediate reversal
                if abs(move1) > 1.0 and abs(move2) > 1.0 and move1 * move2 < 0:  # Opposite directions
                    patterns.append({
                        'type': 'fake_breakout',
                        'confidence': min(1.0, (abs(move1) + abs(move2)) / 4.0),
                        'seconds_ago': i,
                        'description': f'Fake {"pump" if move1 > 0 else "dump"} then reversal'
                    })
                    manipulation_score += 0.3
            
            # Pattern 2: Volume/Price divergence (high volume, small price moves = accumulation/distribution)
            for i in range(min(5, len(volumes)-1)):
                vol_ratio = volumes[i] / volumes[i+1] if volumes[i+1] > 0 else 1.0
                price_move = abs(price_changes[i]) if i < len(price_changes) else 0
                
                if vol_ratio > 3.0 and price_move < 0.5:  # High volume, small move
                    patterns.append({
                        'type': 'accumulation_distribution',
                        'confidence': min(1.0, vol_ratio / 5.0),
                        'seconds_ago': i,
                        'description': 'High volume, low price movement (MM activity)'
                    })
                    manipulation_score += 0.2
            
            # Pattern 3: Repeated small moves in same direction (algo grinding)
            same_direction_count = 0
            for i in range(min(8, len(price_changes))):
                if i > 0 and price_changes[i] * price_changes[i-1] > 0:  # Same direction
                    same_direction_count += 1
                else:
                    break
            
            if same_direction_count >= 5:  # 5+ consecutive moves in same direction
                patterns.append({
                    'type': 'algo_grinding',
                    'confidence': min(1.0, same_direction_count / 8.0),
                    'seconds_ago': 0,
                    'description': f'Algorithmic grinding ({same_direction_count} consecutive moves)'
                })
                manipulation_score += 0.25
            
            manipulation_score = min(1.0, manipulation_score)
            
        except Exception as e:
            logger.debug(f"MM pattern detection error: {e}")
        
        return {'patterns': patterns, 'manipulation_score': manipulation_score}
    
    def detect_fake_breakouts(self, symbol: str, prices: List[float]) -> float:
        """Detect probability of fake breakouts"""
        try:
            if len(prices) < 15:
                return 0.0
            
            # Look for recent breakout followed by quick reversal
            price_changes = [(prices[i] - prices[i+1]) / prices[i+1] * 100 for i in range(len(prices)-1)]
            
            fake_breakout_score = 0.0
            
            # Check for strong move followed by reversal
            for i in range(min(10, len(price_changes) - 2)):
                current_move = price_changes[i]
                next_moves = price_changes[i+1:i+4]  # Next 3 moves
                
                if abs(current_move) > 1.5:  # Strong initial move
                    reversal_strength = sum([-m for m in next_moves if m * current_move < 0])  # Opposite moves
                    
                    if reversal_strength > abs(current_move) * 0.6:  # 60% retracement
                        fake_breakout_score += 0.4
            
            # Check volatility without direction (high vol = more fake breakouts)
            volatility = np.std(price_changes[:10]) if len(price_changes) >= 10 else 0
            if volatility > 1.0:  # High volatility increases fake breakout risk
                fake_breakout_score += min(0.3, volatility / 5.0)
            
            return min(1.0, fake_breakout_score)
            
        except Exception as e:
            logger.debug(f"Fake breakout detection error: {e}")
            return 0.0
    
    def calculate_scalp_opportunity(self, rapid_moves: List[Dict], volume_surge: float, acceleration: float) -> float:
        """Calculate scalping opportunity score (0-10)"""
        try:
            score = 0.0
            
            # Score based on rapid moves
            for move in rapid_moves:
                move_pct = abs(move['move_pct'])
                if move_pct >= 3.0:      # 3%+ move
                    score += 4.0
                elif move_pct >= 2.0:    # 2%+ move
                    score += 3.0
                elif move_pct >= 1.5:    # 1.5%+ move
                    score += 2.0
                elif move_pct >= 1.0:    # 1%+ move
                    score += 1.0
            
            # Volume surge bonus
            if volume_surge > 3.0:       # 3x volume surge
                score += 2.0
            elif volume_surge > 2.0:     # 2x volume surge
                score += 1.0
            
            # Acceleration bonus
            if acceleration > 1.0:       # High acceleration
                score += 1.5
            elif acceleration > 0.5:     # Medium acceleration
                score += 0.5
            
            return min(10.0, score)
            
        except Exception as e:
            logger.debug(f"Scalp opportunity calculation error: {e}")
            return 0.0
    
    def _analyze_liquidation_levels(self, symbol: str, current_price: float, redis_client) -> Dict[str, Any]:
        """Analyze liquidation levels for squeeze/cascade detection (AI TA 12-25-2025)
        
        Reads liquidation data from Redis (populated by live_binance_liquidations.py)
        to identify nearby liquidation clusters that could trigger cascades.
        
        Args:
            symbol: Trading symbol (e.g., BTCUSDT)
            current_price: Current market price
            redis_client: Redis connection
            
        Returns:
            dict with liquidation level analysis
        """
        try:
            result = {
                'near_liq_cluster': False,
                'cluster_distance_pct': 100.0,  # Far by default
                'cluster_size_usd': 0,
                'cascade_risk': 0.0,
                'liq_levels_above': [],
                'liq_levels_below': []
            }
            
            if not redis_client or current_price <= 0:
                return result
            
            # Get recent liquidation data from Redis
            # Format: binance:force:stats:{timeframe}
            liq_stats_key = f"binance:force:stats:5m"
            liq_data = redis_client.hgetall(liq_stats_key)
            
            # Also check CoinAnk liquidation features if available
            coinank_key = f"features:coinank:liquidations:{symbol}:Binance:5m:latest"
            coinank_data = redis_client.get(coinank_key)
            
            # Aggregate liquidation info
            total_liq_volume = 0
            liq_above_price = []
            liq_below_price = []
            
            if liq_data:
                for key, value in liq_data.items():
                    try:
                        key_str = key.decode() if isinstance(key, bytes) else key
                        if symbol in key_str:
                            liq_info = json.loads(value) if isinstance(value, (bytes, str)) else value
                            liq_price = float(liq_info.get('price', 0))
                            liq_qty = float(liq_info.get('quantity', 0))
                            liq_side = liq_info.get('side', '')
                            
                            if liq_price > 0 and liq_qty > 0:
                                liq_usd = liq_price * liq_qty
                                total_liq_volume += liq_usd
                                
                                if liq_price > current_price:
                                    liq_above_price.append({'price': liq_price, 'usd': liq_usd, 'side': liq_side})
                                else:
                                    liq_below_price.append({'price': liq_price, 'usd': liq_usd, 'side': liq_side})
                    except:
                        continue
            
            # Check CoinAnk data for richer liquidation zones
            if coinank_data:
                try:
                    ck_data = json.loads(coinank_data) if isinstance(coinank_data, (bytes, str)) else coinank_data
                    # CoinAnk provides liq_long_usd, liq_short_usd for aggregated liquidation levels
                    liq_long = float(ck_data.get('liq_long_usd', 0))
                    liq_short = float(ck_data.get('liq_short_usd', 0))
                    total_liq_volume += liq_long + liq_short
                except:
                    pass
            
            # Calculate cluster proximity
            if liq_above_price:
                nearest_above = min(liq_above_price, key=lambda x: x['price'])
                dist_above_pct = (nearest_above['price'] - current_price) / current_price * 100
                if dist_above_pct < 2.0:  # Within 2% above
                    result['near_liq_cluster'] = True
                    result['cluster_distance_pct'] = min(result['cluster_distance_pct'], dist_above_pct)
                result['liq_levels_above'] = liq_above_price[:5]  # Top 5
            
            if liq_below_price:
                nearest_below = max(liq_below_price, key=lambda x: x['price'])
                dist_below_pct = (current_price - nearest_below['price']) / current_price * 100
                if dist_below_pct < 2.0:  # Within 2% below
                    result['near_liq_cluster'] = True
                    result['cluster_distance_pct'] = min(result['cluster_distance_pct'], dist_below_pct)
                result['liq_levels_below'] = liq_below_price[:5]  # Top 5
            
            result['cluster_size_usd'] = total_liq_volume
            
            # Cascade risk = proximity * volume
            # High risk if large liq volume is close to current price
            if result['near_liq_cluster'] and total_liq_volume > 100000:  # $100k+ liquidations nearby
                result['cascade_risk'] = min(1.0, (2.0 - result['cluster_distance_pct']) / 2.0 * (total_liq_volume / 1000000))
            
            return result
            
        except Exception as e:
            logger.debug(f"Liquidation level analysis error for {symbol}: {e}")
            return {
                'near_liq_cluster': False,
                'cluster_distance_pct': 100.0,
                'cluster_size_usd': 0,
                'cascade_risk': 0.0
            }
    
    # NOTE: Duplicate validate_margin_for_trade removed (Dec 25, 2025)
    # The canonical version is at line ~6815 with signature:
    #   validate_margin_for_trade(self, symbol: str, side: str, leverage: int, position_size_pct: float)
