    def _validate_margin_for_trade_legacy(self, symbol: str, leverage: int, position_pct: float) -> Dict[str, Any]:
        """DEPRECATED: Legacy wrapper - use validate_margin_for_trade(symbol, side, leverage, position_size_pct)"""
        logger.debug(f"[MARGIN_VALIDATOR] _validate_margin_for_trade_legacy called - forwarding to canonical method")
