                        logger.warning(f"✅ {symbol} FULL CLOSE SIGNAL: {predicted_action} at {adjusted_confidence:.3f} >= {min_close_confidence:.2f} | pos={current_side} gross={current_pnl_pct:+.1f}% net={net_pnl_pct:+.1f}%")
                        
                        # Determine action based on predicted direction
