    def _get_coinank_analysis(self, feature_data: dict, symbol: str) -> str:
        """Get specific Coinank insights"""
        try:
            insights = []
            
            # Liquidations
            liq_long = float(
                feature_data.get('coinank_liquidations_long')
                or feature_data.get('coinank_liquidation_history_data_0_longTurnover')
                or 0
            )
            liq_short = float(
                feature_data.get('coinank_liquidations_short')
                or feature_data.get('coinank_liquidation_history_data_0_shortTurnover')
                or 0
            )
            total_liq = liq_long + liq_short
            
            if total_liq > 1000000:  # $1M+ liquidations
                if liq_long > liq_short * 2:
                    insights.append(f"High long liquidations ${liq_long/1e6:.1f}M (bearish pressure)")
                elif liq_short > liq_long * 2:
                    insights.append(f"High short liquidations ${liq_short/1e6:.1f}M (bullish pressure)")
                else:
                    insights.append(f"Balanced liquidations ${total_liq/1e6:.1f}M")
            
            # Open Interest
            oi_change = float(feature_data.get('coinank_oi_change_pct') or feature_data.get('open_interest_change') or 0)
            if oi_change == 0:
                try:
                    oi_open = float(feature_data.get('coinank_openInterest_kline_data_0_open') or 0)
                    oi_close = float(feature_data.get('coinank_openInterest_kline_data_0_close') or 0)
                    if oi_open > 0 and oi_close > 0:
                        oi_change = ((oi_close - oi_open) / oi_open) * 100.0
                except Exception:
                    pass
            if abs(oi_change) > 3:
                direction = "growing" if oi_change > 0 else "declining"
                insights.append(f"OI {direction} {abs(oi_change):.1f}%")
            
            # Funding Rate
            funding_raw = float(
                feature_data.get('coinank_funding_rate')
                or feature_data.get('coinank_fundingRate_indicator_data_0_fundingRate')
                or feature_data.get('coinank_fundingRate_indicator_data_0_fr')
                or feature_data.get('coinank_fundingRate_kline_data_0_close')
                or feature_data.get('coinank_fundingRate_kline_data_0_open')
                or 0
            )
            funding = funding_raw * 10000  # Convert to basis points
            if abs(funding) > 10:  # 0.1% funding
                bias = "long-heavy" if funding > 0 else "short-heavy"
                insights.append(f"Funding {bias} ({funding:.0f}bp)")
            
            return " | ".join(insights) if insights else "Neutral metrics"
            
        except Exception as e:
            return "Data processing"
    
