    def _extract_coinank_insights(self, feature_data: dict, symbol: str) -> str:
        """Extract insights from Coinank data"""
        try:
            insights = []
            
            # Liquidations analysis
            liq_long = float(
                feature_data.get('coinank_liquidations_long')
                or feature_data.get('coinank_liquidation_history_data_0_longTurnover')
                or 0
            )
            liq_short = float(
                feature_data.get('coinank_liquidations_short')
                or feature_data.get('coinank_liquidation_history_data_0_shortTurnover')
                or 0
            )
            if liq_long > liq_short * 1.5:
                insights.append("High long liquidations detected")
            elif liq_short > liq_long * 1.5:
                insights.append("High short liquidations detected")
            
            # Open Interest analysis
            oi_change = float(feature_data.get('coinank_oi_change_pct') or feature_data.get('open_interest_change') or 0)
            if oi_change == 0:
                try:
                    oi_open = float(feature_data.get('coinank_openInterest_kline_data_0_open') or 0)
                    oi_close = float(feature_data.get('coinank_openInterest_kline_data_0_close') or 0)
                    if oi_open > 0 and oi_close > 0:
                        oi_change = ((oi_close - oi_open) / oi_open) * 100.0
                except Exception:
                    pass
            if abs(oi_change) > 5:
                direction = "increasing" if oi_change > 0 else "decreasing"
                insights.append(f"Open interest {direction} {abs(oi_change):.1f}%")
            
            # Funding rate analysis
            funding = float(
                feature_data.get('coinank_funding_rate')
                or feature_data.get('coinank_fundingRate_indicator_data_0_fundingRate')
                or feature_data.get('coinank_fundingRate_indicator_data_0_fr')
                or feature_data.get('coinank_fundingRate_kline_data_0_close')
                or 0
            )
            if abs(funding) > 0.01:  # 1% funding
                bias = "bullish bias" if funding < 0 else "bearish bias"
                insights.append(f"Funding shows {bias}")
            
            # Long/Short ratio analysis
            ls_ratio = float(
                feature_data.get('coinank_long_short_ratio')
                or feature_data.get('coinank_ls_global_account_ratio_longShortRatio_mean')
                or feature_data.get('coinank_ls_global_account_ratio_longShortRatio_first')
                or feature_data.get('coinank_ls_toptrader_accounts_longShortRatio_mean')
                or feature_data.get('coinank_ls_toptrader_accounts_longShortRatio_first')
                or 1
            )
            if ls_ratio > 1.2:
                insights.append("Traders favor long positions")
            elif ls_ratio < 0.8:
                insights.append("Traders favor short positions")
            
            return "Coinank: " + ", ".join(insights) if insights else ""
            
        except Exception as e:
            logger.debug(f"Coinank analysis error: {e}")
            return ""
    
