    def _analyze_feature_importance(self, symbol: str, tf: str) -> tuple:
        """Analyze which features are most important for current decision"""
        try:
            # Get current features from Redis
            feature_key = f"wma:features:live:{symbol}:{tf}"
            if not hasattr(self, '_signal_redis'):
                return [], {}
            
            feature_data = self._signal_redis.hgetall(feature_key)
            if not feature_data:
                return [], {}
            
            # Define feature families for analysis
            families = {
                "technical": ["rsi", "macd", "bb", "sma", "ema", "stoch", "atr"],
                "momentum": ["roc", "momentum", "trix", "ultimate", "williams"],
                "volume": ["obv", "cmf", "fi", "eom", "volume"],
                "volatility": ["volatility", "atr", "keltner", "bb_width"],
                "sentiment": ["fear_greed", "sentiment", "social"],
                "market_structure": ["support", "resistance", "trend", "pattern"]
            }
            
            # Calculate feature importance scores
            important_features = []
            family_scores = {}
            
            for feature_name, value_str in feature_data.items():
                try:
                    value = float(value_str)
                    # Simple importance scoring based on feature values
                    if "rsi" in feature_name.lower():
                        importance = abs(value - 50) / 50  # RSI deviation from neutral
                    elif "macd" in feature_name.lower():
                        importance = min(1.0, abs(value) / 0.01)  # MACD signal strength
                    elif "bb" in feature_name.lower():
                        importance = abs(value)  # Bollinger band position
                    elif "volume" in feature_name.lower():
                        importance = min(1.0, value / 2.0)  # Volume spike
                    else:
                        importance = min(1.0, abs(value))  # Generic normalization
                    
                    if importance > 0.3:  # Only include significant features
                        important_features.append((feature_name, importance))
                    
                    # Aggregate by family
                    for family, keywords in families.items():
                        if any(keyword in feature_name.lower() for keyword in keywords):
                            family_scores[family] = family_scores.get(family, 0) + importance
                            break
                            
                except ValueError:
                    continue
            
            # Sort by importance
            important_features.sort(key=lambda x: x[1], reverse=True)
            
            return important_features[:10], family_scores
            
        except Exception as e:
            logger.warning(f"⚠️ Feature analysis failed: {e}")
            return [], {}
    
    def _calculate_optimal_leverage(self, symbol: str, confidence: float, training_level: float, volatility: float) -> int:
        """Risk-first leverage: volatility + drawdown aware, capped globally.

        - Removes the old "90% confidence → near-max leverage" tiering.
        - Applies a hard global cap (majors default 10x, alts 5x, overridable per symbol).
        - Scales leverage down when volatility is elevated or training_level is low.
        - Always returns at least 1x and never exceeds the cap.
        """
        try:
            import os
            from math import isfinite
            from config import SYMBOL_LEVERAGE_CONFIG

            majors = {"BTCUSDT", "ETHUSDT"}

            # Symbol-specific caps with env override fallback (env should only lower, not raise unexpectedly)
            symbol_conf = SYMBOL_LEVERAGE_CONFIG.get(symbol, {})
            default_cap = float(symbol_conf.get("max_leverage", 25.0 if symbol not in majors else 100.0))
            default_min = float(symbol_conf.get("min_leverage", 1.0))

            # Parse env caps defensively (bad env values should never force a 1x fallback).
            if symbol in majors:
                env_val = os.getenv("GLOBAL_MAX_LEVERAGE") or os.getenv("GLOBAL_MAX_LEVERAGE_MAJORS") or str(default_cap)
                try:
                    symbol_cap = float(env_val)
                except Exception:
                    symbol_cap = float(default_cap)
            else:
                env_val = os.getenv("GLOBAL_MAX_LEVERAGE_ALTS") or str(default_cap)
                try:
                    symbol_cap = float(env_val)
                except Exception:
                    symbol_cap = float(default_cap)

            # Never exceed config max even if env is higher; always respect config min floor later
            symbol_cap = min(symbol_cap, float(symbol_conf.get("max_leverage", symbol_cap)))

            # Guardrails on inputs
            conf = confidence if isfinite(confidence) else 0.0
            conf = max(0.0, min(1.0, conf))
            training = max(0.0, min(1.0, training_level if isfinite(training_level) else 0.0))
            vol = max(0.0, volatility if isfinite(volatility) else 0.0)

            # Risk score: confidence + training readiness, dampened by volatility
            risk_score = (0.55 * conf) + (0.25 * training) + (0.20 * max(0.0, 1.0 - min(vol, 1.0)))
            risk_score = max(0.05, min(0.95, risk_score))

            # Volatility penalty: higher vol → reduces risk score
            vol_penalty = 0.35 * min(vol, 1.0)
            adjusted_risk = max(0.05, min(0.95, risk_score - vol_penalty))
            
            # Scale WITHIN the configured min-max range (not from 0 to max)
            leverage_range = symbol_cap - default_min
            recommended = default_min + (leverage_range * adjusted_risk)

            # Clamp to configured bounds
            final_leverage = int(max(default_min, min(symbol_cap, recommended)))

            logger.info(
                "[LEVERAGE_APPLIED] symbol=%s conf=%.3f vol=%.4f training_level=%.3f recommended=%.3f lev_cap=%.2f final_lev=%s",
                symbol,
                conf,
                vol,
                training,
                recommended,
                symbol_cap,
                final_leverage,
            )

            return final_leverage

        except Exception as e:
            logger.warning(f"⚠️ Leverage calculation failed: {e}")
            # Safety fallback: use config min leverage (never silently fall back to 1x for opens)
            try:
                from config import SYMBOL_LEVERAGE_CONFIG
                default_min = float(SYMBOL_LEVERAGE_CONFIG.get(symbol, {}).get("min_leverage", 1.0))
                return max(1, int(default_min))
            except Exception:
                return 1

    def _get_fastlane_protective_action(self, symbol: str, event: Dict, current_pos: Dict, confidence: float) -> Optional[str]:
        """Determine protective action for fast-lane event (close/reduce/hedge-safe)."""
        try:
            event_type = event.get("event_type")
            direction = event.get("direction")
            severity = float(event.get("severity", 0.0) or 0.0)
            pos_side = str(current_pos.get("side") or current_pos.get("position_side") or current_pos.get("positionSide") or "UNKNOWN").upper()
            pos_pnl_pct = float(current_pos.get("pnl_percentage") or current_pos.get("pnl_pct") or 0.0)

            # Extreme severity → close everything regardless of confidence
            extreme_cutoff = getattr(self.main_config, "FASTLANE_EXTREME_SEVERITY", 0.9)
            if severity >= extreme_cutoff:
                logger.warning(f"[FASTLANE] {symbol} EXTREME event severity={severity:.2f} → CLOSE_ALL")
                return "CLOSE_ALL"

            min_conf = getattr(self.main_config, "FASTLANE_MIN_CONF_PROTECT", 0.95)
            if confidence < min_conf:
                logger.debug(f"[FASTLANE] {symbol} confidence={confidence:.2f} < {min_conf:.2f} → skip")
                return None

            if event_type == "SQUEEZE_UP":
                if "LONG" in pos_side:
                    return "PARTIAL_CLOSE" if pos_pnl_pct > 2.0 else "DECREASE_LONG"
                if "SHORT" in pos_side:
                    return "CLOSE_SHORT" if pos_pnl_pct < -3.0 else "DECREASE_SHORT"

            if event_type == "SQUEEZE_DOWN":
                if "SHORT" in pos_side:
                    return "PARTIAL_CLOSE" if pos_pnl_pct > 2.0 else "DECREASE_SHORT"
                if "LONG" in pos_side:
                    return "CLOSE_LONG" if pos_pnl_pct < -3.0 else "DECREASE_LONG"

            if event_type in {"LIQ_BURST", "SPREAD_SHOCK"}:
                if abs(pos_pnl_pct) > 5.0:
                    return "PARTIAL_CLOSE"
                if "LONG" in pos_side:
                    return "DECREASE_LONG"
                if "SHORT" in pos_side:
                    return "DECREASE_SHORT"

            return None
        except Exception as e:
            logger.warning(f"[FASTLANE] {symbol} protective action failed: {e}")
            return None

    def _build_fastlane_signal_payload(self, symbol: str, action: str, event: Dict, current_pos: Dict, confidence: float) -> Optional[Dict]:
        """Build margin-compliant fast-lane payload (protective-only by default)."""
        try:
            now = time.time()
            equity = 0.0
            sizing_ctx: Dict[str, Any] = {}
            try:
                portfolio = self._get_portfolio_state(account_id=self._resolve_target_account())
                equity = float(portfolio.get("total_balance") or portfolio.get("available_balance") or 0.0)
                sizing_ctx = {"equity": equity, "available_balance": portfolio.get("available_balance", 0.0)}
            except Exception as e:
                logger.warning(f"[FASTLANE] {symbol} portfolio fetch failed: {e}")

            is_close_or_reduce = any(tok in action.upper() for tok in ["CLOSE", "REDUCE", "DECREASE", "PARTIAL"])
            is_hedge_open = ("HEDGE" in str(action or "").upper())

            if not is_close_or_reduce:
                allow_bypass = False
                try:
                    import config as _config
                    allow_bypass = bool(getattr(_config, "HEDGE_BYPASS_ALL_GATES", False))
                except Exception:
                    allow_bypass = False

                # When bypass is enabled, do not block hedge opens via fastlane policy.
                if (not allow_bypass) and is_hedge_open and (not getattr(self.main_config, "FASTLANE_ALLOW_HEDGE_OPEN", False)):
                    logger.info(f"[FASTLANE] {symbol} hedge open blocked (FASTLANE_ALLOW_HEDGE_OPEN=false)")
                    return None

                if (not is_hedge_open) and (not getattr(self.main_config, "FASTLANE_ALLOW_HEDGE_OPEN", False)):
                    logger.info(f"[FASTLANE] {symbol} hedge open blocked (FASTLANE_ALLOW_HEDGE_OPEN=false)")
                    return None
                if equity <= 0:
                    logger.error(f"[FASTLANE] {symbol} hedge open blocked (equity missing)")
                    return None

            base_payload = {
                "timestamp": now,
                "ts_ms": int(now * 1000),
                "created_ts_ms": int(now * 1000),
                "symbol": symbol,
                "producer": "trainer",
                "exchange": "binance",
                "timeframe": "1m",
                "action_name": action,
                "final_action": action,
                "model_confidence": confidence,
                "confidence": confidence,
                "trade_mode": "FASTLANE_PROTECTIVE",
                "urgency": 5,
                "model": "fastlane_protective",
                "source": "fastlane_1m",
                "decision_source": "fastlane_intrabar",
                "hedge_mode": 1,
                "margin_mode": "cross",
                "position_side": "BOTH",
                "bypass_confidence_check": True,
                "fast_lane": True,
                "fast_lane_event_id": event.get("event_id"),
                "fast_lane_event_type": event.get("event_type"),
                "fast_lane_severity": event.get("severity"),
                "fast_lane_direction": event.get("direction"),
                "intrabar_snapshot": event.get("intrabar_snapshot", {}),
                "reason_codes": event.get("trigger_reasons", []),
                "current_position": current_pos,
                "target_side": current_pos.get("side", "LONG"),
            }

            if is_close_or_reduce:
                base_payload.update({
                    "leverage": 1,
                    "position_size_pct": 0.0,
                    "margin_usd": 0.0,
                    "notional_usd": 0.0,
                    "sizing_source": "close_only",
                    "close_percentage": 0.5 if "PARTIAL" in action.upper() else 1.0,
                })
            else:
                hedge_margin_pct = getattr(self.main_config, "FASTLANE_MAX_HEDGE_PCT_EQUITY", 0.005)
                hedge_margin_usd = equity * hedge_margin_pct
                hedge_leverage = 10
                base_payload.update({
                    "leverage": hedge_leverage,
                    "position_size_pct": hedge_margin_pct * 100,
                    "margin_usd": hedge_margin_usd,
                    "notional_usd": hedge_margin_usd * hedge_leverage,
                    "sizing_source": "fastlane_hedge",
                    "equity": equity,
                })

            built, reason = self._build_signal_payload_margin_v1(base_payload, contract_required=not is_close_or_reduce)
            if not built:
                logger.warning(f"[FASTLANE] {symbol} payload blocked: {reason}")
                return None

            return built
        except Exception as e:
            logger.error(f"[FASTLANE] {symbol} payload build failed: {e}")
            return None

    def attach_signal_publisher(self, redis_client, min_conf: float):
        """TODO: attach a publisher (stream + last-hash) to PPO"""
        self._signal_redis = redis_client
        self._signal_min_conf = min_conf
        
        # AMBER #6: Standardize Redis client - inject into config for all feature readers
        self.config.redis_client = self._signal_redis

        # Initialize execution feedback system once per process (idempotent guard inside)
        try:
            from rl.trade_feedback import initialize_feedback_system
            if not getattr(self, "_feedback_initialized", False):
                self.feedback_tracker, self.signal_validator, self.feedback_consumer = initialize_feedback_system(self._signal_redis)
                self._feedback_initialized = True
                logger.info("🎯 [TRADE-FEEDBACK] TradeOutcomeTracker, SignalValidator, ExecutionFeedbackConsumer initialized")
                
                # Ensure feedback consumer is running
                if self.feedback_consumer and not self.feedback_consumer._running:
                    self.feedback_consumer.start()
                    logger.info("✅ [FEEDBACK-CONSUMER] Background thread started")
        except Exception as e:
            logger.warning(f"⚠️ Failed to initialize feedback system: {e}")
            import traceback
            logger.debug(f"Feedback init traceback: {traceback.format_exc()}")
        
        # Initialize WinRateTracker for adaptive confidence
        try:
            from rl.WIN_RATE_OPTIMIZER import WinRateTracker
            if not hasattr(self, 'win_rate_tracker') or self.win_rate_tracker is None:
                self.win_rate_tracker = WinRateTracker(target_win_rate=0.65)
                logger.info("📊 [WIN-RATE] WinRateTracker initialized (target=65%)")
        except Exception as wrt_err:
            logger.warning(f"⚠️ WinRateTracker initialization failed: {wrt_err}")
            self.win_rate_tracker = None
        
        # Connect feedback_tracker to portfolio_reward_fn for actual trade PnL integration
        try:
            if hasattr(self, 'portfolio_reward_fn') and self.portfolio_reward_fn is not None:
                if hasattr(self, 'feedback_tracker') and self.feedback_tracker is not None:
                    if hasattr(self.portfolio_reward_fn, 'set_feedback_tracker'):
                        self.portfolio_reward_fn.set_feedback_tracker(self.feedback_tracker)
                        logger.info("🔗 [FEEDBACK] Connected feedback_tracker to portfolio_reward_fn")
                    else:
                        logger.warning("⚠️ portfolio_reward_fn missing set_feedback_tracker method")
        except Exception as prf_err:
            logger.warning(f"⚠️ Failed to connect feedback_tracker to portfolio_reward_fn: {prf_err}")
        
        logger.info(f"✅ Signal publisher attached (Redis stream + last-hash, min_conf={min_conf})")
        logger.info(f"✅ Redis client standardized: all feature readers use self._signal_redis")
    
    
